window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s55-30","number":30,"surah":55,"verses":[10],"references":[{"surah":55,"verses":[10]}],"verseLabel":"الرحمن: 10","question":"لماذا قيل: ﴿لِلْأَنَامِ﴾ دون «للخلق»؟","answer":"لأن الأنام تستحضر الخلائق التي تدب على الأرض وتنتفع بها، وفيها جرس يلائم تعداد النعم، أما الخلق فأعم وأبعد عن تصوير هذا الانتفاع المباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص713–714، تحت عنوان «دلالة التعبير بمفردة (الأنام) دون (الخلق)»","url":""}]},{"id":"s55-13","number":13,"surah":55,"verses":[11],"references":[{"surah":55,"verses":[11]}],"verseLabel":"الرحمن: 11","question":"لماذا خُص النخل بالذكر بعد الفاكهة في قوله: ﴿وَالنَّخْلُ﴾؟","answer":"لشرف النخل وكثرة منافعه وكونه من أوضح نعم العرب، فخص بعد العموم تنبيهًا إلى منزلته، وعُرّف لاستحضار جنسه المعروف لديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص716–717، تحت عنوان «دلالة العطف في ﴿والنخل﴾، وسر تعريفه باللام دون الفاكهة»","url":""}]},{"id":"s55-31","number":31,"surah":55,"verses":[11],"references":[{"surah":55,"verses":[11]}],"verseLabel":"الرحمن: 11","question":"لماذا وُصف النخل بأنه ﴿ذَاتُ الْأَكْمَامِ﴾؟","answer":"لأن الأكمام تحفظ الطلع والثمر في نشأته حتى يكتمل، فالوصف يستحضر عناية الله الخفية بالثمرة قبل ظهورها ومراحل نموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص717، تحت عنوان «سر تقييد النخل بالوصف ﴿ذات الأكمام﴾»","url":""}]},{"id":"s55-14","number":14,"surah":55,"verses":[12],"references":[{"surah":55,"verses":[12]}],"verseLabel":"الرحمن: 12","question":"لماذا وُصف الحب بأنه ﴿ذُو الْعَصْفِ﴾؟","answer":"للتنبيه إلى تمام النعمة؛ فالحب غذاء للإنسان، وعصفه قشر وورق ينتفع به الحيوان، فلا يضيع من الزرع جزء بلا فائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص718–719، تحت عنوان «سر وصف الحب بأنه ﴿ذو العصف﴾»","url":""}]},{"id":"s55-32","number":32,"surah":55,"verses":[12],"references":[{"surah":55,"verses":[12]}],"verseLabel":"الرحمن: 12","question":"لماذا ذُكر ﴿الرَّيْحَانُ﴾ مع الحب ذي العصف؟","answer":"لأن الريحان يشمل الرزق الطيب أو النبات ذي الرائحة، فيجمع السياق بين القوت الضروري وما يكمّل الحياة من طيب ومتعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص720، تحت عنوان «دلالة التعبير بالريحان مادة وصيغة»","url":""}]},{"id":"s55-15","number":15,"surah":55,"verses":[13],"references":[{"surah":55,"verses":[13]}],"verseLabel":"الرحمن: 13","question":"لماذا جاء الخطاب مثنى في ﴿رَبِّكُمَا تُكَذِّبَانِ﴾ قبل التصريح بالجن والإنس؟","answer":"من أوجه عود التثنية أنها للإنس والجن، وقد دل عليهما السياق والإشارة إلى الأنام، ثم صرح بهما فيما بعد. فلا يتوقف فهم الضمير على تقدم اسميهما صراحة؛ ويجمع الخطاب الطرفين في الاعتراف بآلاء ربهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص724–725، تحت عنوان «المقصود بعود الضمير في علامة التثنية»","url":""}]},{"id":"s55-16","number":16,"surah":55,"verses":[17],"references":[{"surah":55,"verses":[17]}],"verseLabel":"الرحمن: 17","question":"لماذا ثنّى فقال ﴿رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِ﴾؟","answer":"من أشهر أوجه التثنية مشرقا الشمس ومغرباها في طرفي الصيف والشتاء، وما بينهما معلوم تبعًا. وفي ذلك تصوير لتنوع المطالع والمغارب مع خضوعها لرب واحد، وتناسب مع نسق التثنية البارز في السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص744، تحت عنوان «سر التعبير بالمثنى في ﴿المشرقين﴾»","url":""}]},{"id":"s55-17","number":17,"surah":55,"verses":[19,20],"references":[{"surah":55,"verses":[19,20]}],"verseLabel":"الرحمن: 19–20","question":"ما الصورة في قوله عن البحرين: ﴿يَلْتَقِيَانِ﴾؟","answer":"شُبّه تقارب البحرين واتصال مائهما بلقاء شخصين، فصار المشهد الكوني حركة حية مع بقاء لكل بحر خصائصه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص755، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿يلتقيان﴾»","url":""}]},{"id":"s55-33","number":33,"surah":55,"verses":[19,20],"references":[{"surah":55,"verses":[19,20]}],"verseLabel":"الرحمن: 19–20","question":"ما دلالة قوله عن البحرين: ﴿لَا يَبْغِيَانِ﴾؟","answer":"كُني عن عدم تجاوز أحدهما الحد المقدر له بصورة شخصين لا يعتدي أحدهما على الآخر، فبرز البرزخ قانونًا مانعًا للاختلاط المفسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص757، تحت عنوان «بلاغة التعبير بالكناية في ﴿يبغيان﴾»","url":""}]},{"id":"s55-18","number":18,"surah":55,"verses":[24],"references":[{"surah":55,"verses":[24]}],"verseLabel":"الرحمن: 24","question":"لماذا وُصفت السفن بأنها ﴿الْمُنْشَآتُ﴾؟","answer":"لأن اللفظ يستحضر صنعها ورفع شراعها وظهورها قائمة في البحر، فيجمع دقة الصناعة وضخامة الهيئة واستعدادها للجري.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص768، تحت عنوان «دلالة التعبير بـ﴿المنشآت﴾»","url":""}]},{"id":"s55-19","number":19,"surah":55,"verses":[26,27],"references":[{"surah":55,"verses":[26,27]}],"verseLabel":"الرحمن: 26–27","question":"لماذا ذُكر فناء من على الأرض في سياق تعداد النعم؟","answer":"للتذكير بأن نعم الدنيا مهما عظمت زائلة، فيتجه القلب إلى المنعم الباقي ويستعمل النعمة فيما ينفع قبل انقضائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص780–781، تحت عنوان «فائدة ذكر الفناء في السورة الكريمة»","url":""}]},{"id":"s55-34","number":34,"surah":55,"verses":[26,27],"references":[{"surah":55,"verses":[26,27]}],"verseLabel":"الرحمن: 26–27","question":"ما دلالة المقابلة بين ﴿فَانٍ﴾ و﴿وَيَبْقَى وَجْهُ رَبِّكَ﴾؟","answer":"تبرز أن الفناء شامل للخلق، وأن البقاء المطلق لله وحده؛ فتقطع تعلق القلب بالمحدود وترده إلى صاحب الجلال والإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص782–783، تحت عنوان «بلاغة التعبير بالطباق بين ﴿ويبقى﴾ و﴿فان﴾»","url":""}]},{"id":"s55-20","number":20,"surah":55,"verses":[29],"references":[{"surah":55,"verses":[29]}],"verseLabel":"الرحمن: 29","question":"ما دلالة ﴿يَوْمٍ﴾ في قوله: ﴿كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ﴾؟","answer":"اليوم هنا مجاز عن كل وقت ولحظة، أي إن آثار تدبير الله لا تنقطع في زمن دون زمن، بل تتجدد دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص794، تحت عنوان «دلالة المجاز في ﴿يوم﴾»","url":""}]},{"id":"s55-35","number":35,"surah":55,"verses":[29],"references":[{"surah":55,"verses":[29]}],"verseLabel":"الرحمن: 29","question":"ماذا يعني ﴿شَأْنٍ﴾ في قوله: ﴿كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ﴾، ولماذا نُكِّرت؟","answer":"الشأن فعل عظيم من أفعال تدبيره: يحيي ويميت ويعطي ويمنع ويغفر ويكشف الضر؛ وتنكيره للتعظيم والتكثير، إذ لا تحيط العبارة بتنوع شؤونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص795–796، تحت عنوان «المراد بـ﴿شأن﴾، والغرض من تنكيرها»","url":""}]},{"id":"s55-21","number":21,"surah":55,"verses":[31],"references":[{"surah":55,"verses":[31]}],"verseLabel":"الرحمن: 31","question":"ما سرّ التعبير بقوله ﴿سَنَفْرُغُ لَكُمْ أَيُّهَ الثَّقَلَانِ﴾ مع أن الله لا يشغله شأن؟","answer":"هو تصوير للوعيد وتمام القصد إلى المحاسبة، على نحو قول المهدد لمن يتوعده إنه سيتفرغ له. فالمراد تحقيق الحساب وشدته بعد انقضاء مهلة الدنيا، وليس خلو الله من شغل كان يعوقه عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص13–14، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿سنفرغ﴾»","url":""}]},{"id":"s55-22","number":22,"surah":55,"verses":[41],"references":[{"surah":55,"verses":[41]}],"verseLabel":"الرحمن: 41","question":"ما سرّ التعبير في قول ﴿يُعْرَفُ الْمُجْرِمُونَ بِسِيمَاهُمْ﴾، ولم يقل «الكافرون»؟","answer":"الإجرام وصف جامع لصور الشر والذنوب والجحود، فيبرز استحقاقهم العقوبة ويشتد به التبكيت. فالتعبير يواجههم بصفة ما اقترفوه من جرم، وهي المناسبة لهذا المقام من الأخذ والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص55، تحت عنوان «سر إيثار التعبير بنائب الفاعل بلفظ ﴿المجرمون﴾ دون غيره»","url":""}]},{"id":"s55-23","number":23,"surah":55,"verses":[46],"references":[{"surah":55,"verses":[46]}],"verseLabel":"الرحمن: 46","question":"لماذا أُفرد الخائف في قوله: ﴿وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ﴾؟","answer":"ليتناول الوعد كل فرد على حدة، فيشعر كل سامع أن الجزاء متعلق بخوفه وعمله شخصيًا، مع أن اللفظ يعم أفرادًا كثيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص78، تحت عنوان «علة التعبير بـ﴿خاف﴾ مسندًا للمفرد دون الجمع»","url":""}]},{"id":"s55-24","number":24,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا وُصفت الجنتان الأوليان بأنهما ﴿ذَوَاتَا أَفْنَانٍ﴾؟","answer":"للدلالة على كثرة الأغصان وتنوع الثمار والظلال؛ فالأفنان تجمع صورة الامتداد والجمال وتعدد ألوان النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص82–83، تحت عنوان «سر وصف الجنتين بقوله: ﴿ذواتا أفنان﴾»","url":""}]},{"id":"s55-36","number":36,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا قيل في العينين الأوليين: ﴿تَجْرِيَانِ﴾ بالمضارع؟","answer":"ليصور جريانهما متجددًا مستمرًا أمام أهل الجنة، فلا ينقطع ماؤهما ولا يفتر تدفقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص84، تحت عنوان «الغرض من وصف العينين بالجملة الفعلية بصيغة المضارع»","url":""}]},{"id":"s55-37","number":37,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا وُصفت الجنتان الأخريان بأنهما ﴿مُدْهَامَّتَانِ﴾ في مقابل ﴿ذَوَاتَا أَفْنَانٍ﴾؟","answer":"لأن شدة الخضرة في الأخريين تصور امتلاءهما بالنبات والري، بينما ﴿ذواتا أفنان﴾ تبرز تنوع الأغصان والثمار في الأوليين؛ فلكل مرتبة جمالها الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص121، تحت عنوان «دلالة الوصف بـ﴿مدهامتان﴾ في مقابل ﴿ذواتا أفنان﴾»","url":""}]},{"id":"s55-38","number":38,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا قيل في العينين الأخريين: ﴿نَضَّاخَتَانِ﴾ بدل «تجريان»؟","answer":"لأن النضخ يدل على فوران الماء واندفاعه من منبعه، فيعطي صورة قوة وغزارة تختلف عن صورة الجريان الممتد في الجنتين الأوليين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص122–123، تحت عنوان «دلالة التعبير بالنضخ دون النضح أو الجري»","url":""}]},{"id":"s55-39","number":39,"surah":55,"verses":[15],"references":[{"surah":55,"verses":[15]}],"verseLabel":"الرحمن: 15","question":"ما دلالة «الجان» في قوله: ﴿وَخَلَقَ الْجَانَّ مِن مَّارِجٍ مِّن نَّارٍ﴾، مقابلًا لـ﴿خَلَقَ الْإِنسَانَ﴾؟","answer":"«الجان» يُستعمل للواحد وللجنس، وهو ما يقابل «الإنسان» الذي يُراد به الجنس أيضًا، فقوبل جنس بجنس. وقد يُستعمل للجمع مقابلًا لـ«الإنس»، كقوله في السورة نفسها: ﴿لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَانٌّ﴾. أما «الجِنِّي» فهو الواحد من الجن ويقابله «الإنسي».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص56.","url":""}]},{"id":"s55-40","number":40,"surah":55,"verses":[26],"references":[{"surah":55,"verses":[26]}],"verseLabel":"الرحمن: 26","question":"ما سر إفراد الخبر في قوله: ﴿كُلُّ مَنْ عَلَيْهَا فَانٍ﴾، وجمعه في مثل: ﴿كُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"الإخبار عن «كل» بالجمع يدل على اجتماعهم في الحدث، والإفراد يدل على أن كل واحد قام به على انفراد. فأفرد «فانٍ» لأنهم لا يجتمعون في الفناء بل يفنى كل واحد على حدة، وجمع «يسبحون» لاجتماعها في السبح. وهذا التوجيه منقول عن «بدائع الفوائد».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص140–141.","url":""}]},{"id":"s55-41","number":41,"surah":55,"verses":[7],"references":[{"surah":55,"verses":[7]}],"verseLabel":"الرحمن: 7","question":"ما سر نصب «السماء» في قوله: ﴿وَالسَّمَاءَ رَفَعَهَا وَوَضَعَ الْمِيزَانَ﴾، ولم تُرفع مبتدأً؟","answer":"نُصبت لأن الكلام على الله الرحمن الخالق لا على السماء، فقد بدأت السورة بـ﴿الرَّحْمَٰنُ ۝ عَلَّمَ الْقُرْآنَ﴾ وتتابع الحديث عن أفعاله. ولو رُفعت لكان الحديث عن السماء، كما رُفع ﴿وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ﴾ لأن الكلام عليهم. وقُدّمت السماء والأرض للاهتمام بهما.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص135.","url":""}]},{"id":"s55-42","number":42,"surah":55,"verses":[7,9],"references":[{"surah":55,"verses":[7,9]}],"verseLabel":"الرحمن: 7، 9","question":"ما سر تكرار «الميزان» ثلاث مرات في قوله: ﴿وَوَضَعَ الْمِيزَانَ ۝ أَلَّا تَطْغَوْا فِي الْمِيزَانِ ۝ وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ وَلَا تُخْسِرُوا الْمِيزَانَ﴾، دون الإضمار؟","answer":"ليس ذلك للفاصلة وحدها، بل لأن الموازين في الحياة ثلاثة: ميزان العقل والفطرة الذي يزن به الإنسان الأمور، وميزان الشرائع الذي أنزله الله، والميزان الآلة التي يتعامل بها الناس. ولا تستقيم الحياة إلا بها جميعًا، فلا يصلح عود الضمير على الأول لأنها ليست ميزانًا واحدًا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص171–172.","url":""}]},{"id":"s55-43","number":43,"surah":55,"verses":[11],"references":[{"surah":55,"verses":[11]}],"verseLabel":"الرحمن: 11","question":"ما سر التعبير بـ«فاكهة» في قوله: ﴿وَالْأَرْضَ وَضَعَهَا لِلْأَنَامِ ۝ فِيهَا فَاكِهَةٌ﴾، وبـ«فواكه» في المؤمنون: ﴿لَّكُمْ فِيهَا فَوَاكِهُ كَثِيرَةٌ﴾؟","answer":"«الفاكهة» أعمّ من «الفواكه»، فهي تطلق على الحبة الواحدة والنوع الواحد والأنواع، أما «الفواكه» فلا تُقال إلا للأنواع المتعددة. ولذلك يأتي القرآن بالفاكهة في مواطن السعة، فلما ذكر الأرض على العموم قال «فاكهة»، ولما ذكر في المؤمنون جناتٍ مخصوصة من نخيل وأعناب قال «فواكه».","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص74–75.","url":""}]},{"id":"s55-44","number":44,"surah":55,"verses":[17],"references":[{"surah":55,"verses":[17]}],"verseLabel":"الرحمن: 17","question":"ما المراد بالتثنية في قوله: ﴿رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِ﴾، وقد جاء المشرق مفردًا في المزمل ومجموعًا في المعارج؟","answer":"قيل المشرقان مشرق الصيف ومشرق الشتاء والمغربان مغرباهما، إذ تشرق الشمس من كل مشرق مرتين في السنة وهي تنتقل بين المدارين، وقيل مشرقا الشمس والقمر ومغرباهما. والمشارق والمغارب مشارق الشمس ومغاربها على تعدد أيام السنة، وقيل مشارق الكواكب مطلقًا. وهذه الأقوال منقولة عن «روح المعاني».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص110–111.","url":""}]},{"id":"s55-46","number":46,"surah":55,"verses":[31,77],"references":[{"surah":55,"verses":[31,77]}],"verseLabel":"الرحمن: 31، 77","question":"ما اللطيفة المذكورة في عدد تكرار ﴿فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ﴾ في مشاهد الجنة والنار؟","answer":"ذكر السلف أنها تكررت في كل جنة من الجنتين ثماني مرات بعدد أبواب الجنة، وتكررت بعد قوله: ﴿سَنَفْرُغُ لَكُمْ أَيُّهَ الثَّقَلَانِ﴾ سبع مرات بعدد أبواب النار. وهذه العلاقات العددية لا يُقطع بها، وكثير منها ربما كان من باب الموافقات.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص218، 345.","url":""}]},{"id":"s55-45","number":45,"surah":55,"verses":[46,76],"references":[{"surah":55,"verses":[46,76]}],"verseLabel":"الرحمن: 46، 76","question":"ما الفرق بين وصف الجنتين في قوله: ﴿وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ﴾، ووصف الجنتين في قوله: ﴿وَمِن دُونِهِمَا جَنَّتَانِ﴾؟","answer":"الأوليان أعلى، وقد ظهر ذلك في الوصف: ﴿ذَوَاتَا أَفْنَانٍ﴾ مقابل ﴿مُدْهَامَّتَانِ﴾، و﴿عَيْنَانِ تَجْرِيَانِ﴾ وماء الجري أكثر من ﴿نَضَّاخَتَانِ﴾، و﴿مِن كُلِّ فَاكِهَةٍ زَوْجَانِ﴾ على الاستغراق، وذكر بطائن فُرُشهما من إستبرق وسكت عن الظهائر لعلوّها، و﴿قَاصِرَاتُ الطَّرْفِ﴾ باسم الفاعل مقابل ﴿مَّقْصُورَاتٌ﴾ باسم المفعول، ووصفهنّ بـ﴿كَأَنَّهُنَّ الْيَاقُوتُ وَالْمَرْجَانُ﴾. وفي «الكشاف» نحو بعض ذلك.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص216–218.","url":""}]},{"id":"s56-1","number":1,"surah":56,"verses":[13,14],"references":[{"surah":56,"verses":[13,14]}],"verseLabel":"الواقعة: 13–14","question":"ما سرّ التعبير في السابقين ﴿ثُلَّةٌ مِنَ الْأَوَّلِينَ وَقَلِيلٌ مِنَ الْآخِرِينَ﴾؟","answer":"المقابلة بين الثلة والقليل تبين كثرة السابقين من الأولين بالنسبة إلى السابقين من الآخرين. فالكثرة والقلة هنا في مرتبة المقربين، ولا يلزم منهما الحكم على مجموع أهل الجنة؛ كما أن المقصود تفاوت العدد النسبي بين الفريقين، لا تعيين عدد محدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص240–241، تحت عنوان «دلالة العطف التقابلي بين (قليل) و﴿ثلة﴾»","url":""}]},{"id":"s56-2","number":2,"surah":56,"verses":[21,22],"references":[{"surah":56,"verses":[21,22]}],"verseLabel":"الواقعة: 21–22","question":"لماذا ذُكر ﴿وَحُورٌ عِينٌ﴾ نعيمًا مستقلًا بعد الطعام والشراب؟","answer":"لأن استئناف العبارة ينقل المشهد من المطعومات التي يطوف بها الولدان إلى لون أرفع من نعيم الصحبة والأنس، فيفصل مقام الحور ويشرفه بدل أن يجعله مجرد عنصر في قائمة الطعام والشراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص275–276، تحت عنوان «نوع الواو في قوله: ﴿وحور﴾ ودلالتها»","url":""}]},{"id":"s56-3","number":3,"surah":56,"verses":[60,61],"references":[{"surah":56,"verses":[60,61]}],"verseLabel":"الواقعة: 60–61","question":"لماذا نُفي أن يكون الله ﴿بِمَسْبُوقِينَ﴾ بدل أن يقال «بمغلوبين»؟","answer":"لأن نفي السَّبق يقطع أصل إمكان أن يفوته شيء أو يتقدم على إرادته أحد؛ فالغلبة قد تُتصور بعد نزاع، أما السبق فينفي أن تبدأ المعارضة أصلًا أو يمر مانع قبل نفاذ قدره. وبذلك يشتد تقرير القدرة على الموت والإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص415–416، تحت عنوان «بلاغة استعمال مفردة السبق دون الغلبة»","url":""}]},{"id":"s56-29","number":29,"surah":56,"verses":[60,61],"references":[{"surah":56,"verses":[60,61]}],"verseLabel":"الواقعة: 60–61","question":"ماذا يتسع له قوله ﴿أَنْ نُبَدِّلَ أَمْثَالَكُمْ﴾؟","answer":"يتسع لأن يبدل الله قومًا بغيرهم، ولأن ينشئهم بعد الموت في خلق وهيئة لا يعرفونها. فلفظ الأمثال يوجز صور التبديل كلها، ويقرر أن القادر على الخلق الأول لا يعجزه إهلاكهم أو إعادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص416، تحت عنوان «بلاغة التعبير بلفظ: ﴿أمثالكم﴾»","url":""}]},{"id":"s56-4","number":4,"surah":56,"verses":[65,70],"references":[{"surah":56,"verses":[65,70]}],"verseLabel":"الواقعة: 65، 70","question":"ما دلالة إثبات اللام في ﴿لجعلناه حطامًا﴾ وحذفها في ﴿جعلناه أجاجًا﴾؟","answer":"إثبات اللام في الزرع يزيد التوكيد والتهديد، لأن انقلاب الزرع الناضر حطامًا يصادم ما اطمأن إليه صاحبه بعد تعهده. أما صيرورة الماء ملحًا فمما يقرب تصوره، فجاء الجواب دون هذه الزيادة. وتذكر الموسوعة وجهًا آخر: قد يوهم ما يبذله البشر في الزرع استقلالهم به، فاحتيج إلى توكيد القدرة، بخلاف إنزال الماء الذي لا يد لهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص465–466، تحت عنوان «توجيه المتشابه اللفظي في حذف اللام وإثباتها في السابقة»","url":""}]},{"id":"s56-5","number":5,"surah":56,"verses":[70],"references":[{"surah":56,"verses":[70]}],"verseLabel":"الواقعة: 70","question":"ما الذي تضيفه ﴿لَوْلَا﴾ إلى دعوة الناس لشكر نعمة الماء؟","answer":"تحول الدعوة إلى تحضيض قوي يحمل معنى: هلا تجددون الشكر وتداومون عليه؟ فهي توقظ الضمير بلطف العتاب، لأن بقاء النعمة مع ظهور مصدرها يجعل ترك الشكر أمرًا مستغربًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص467، تحت عنوان «غرض استعمال (لولا)»","url":""}]},{"id":"s56-30","number":30,"surah":56,"verses":[70],"references":[{"surah":56,"verses":[70]}],"verseLabel":"الواقعة: 70","question":"لماذا انتهت آية الماء إلى الشكر لا إلى مجرد الإيمان؟","answer":"لأن المقام مقام نعمة محسوسة يشربها الناس ويرون أثرها، والشكر هو ثمرة الإيمان عند مشاهدة الإنعام: اعتراف بالمنعم وخضوع له واستعمال النعمة في طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص467، تحت عنوان «بلاغة استعمال ﴿تشكرون﴾»","url":""}]},{"id":"s56-6","number":6,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"ما سرّ التعبير في قول ﴿فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ﴾ بدل «أقسم»؟","answer":"تذكر الموسوعة أن «لا» تحتمل تقوية القسم وتوكيده، وتحتمل نفي الحاجة إليه لوضوح الحق؛ وهذا النفي نفسه أسلوب في تعظيم المقسم عليه. ففي الوجهين تمهيد مهيب لتقرير كرامة القرآن، لا تراجع عن تأكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص488–489، تحت عنوان «دلالة استعمال (لا) في سياق القسم»","url":""}]},{"id":"s56-7","number":7,"surah":56,"verses":[84,85],"references":[{"surah":56,"verses":[84,85]}],"verseLabel":"الواقعة: 84–85","question":"كيف ينظر أهل المحتضر إليه ثم يقال لهم ﴿لَا تُبْصِرُونَ﴾؟","answer":"لأن النظر يقع بالعين إلى ظاهر المشهد، أما الإبصار هنا فهو إدراك حقيقته الغيبية. فهم يشاهدون الجسد وخروج الروح، لكنهم لا يرون قرب الملائكة ولا ينفذ حسهم إلى ما وراء الظاهر؛ فتتكشف محدودية الإدراك البشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص528–529، تحت عنوان «بلاغة مجيء فعل النظر مثبتًا والإبصار منفيًا»","url":""}]},{"id":"s56-8","number":8,"surah":56,"verses":[1],"references":[{"surah":56,"verses":[1]}],"verseLabel":"الواقعة: 1","question":"لماذا افتتحت السورة بفعل ﴿وَقَعَتِ﴾ لا «جاءت القيامة»؟","answer":"لأن الوقوع يوحي بسقوط أمر ثقيل مفاجئ لا يستطيع أحد دفعه أو رده؛ فليست القيامة مجيئًا عابرًا، بل حدثًا هائلًا يصيب العالم ويستقر أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص163، تحت عنوان «بلاغة استعمال مفردة ﴿وقعت﴾»","url":""}]},{"id":"s56-31","number":31,"surah":56,"verses":[1],"references":[{"surah":56,"verses":[1]}],"verseLabel":"الواقعة: 1","question":"لماذا صُورت القيامة بصيغة الماضي في ﴿إِذَا وَقَعَتِ﴾ وهي مستقبلة؟","answer":"لتنقلها من دائرة الانتظار إلى مشهد متحقق كأنه وقع وانتهى؛ فيترسخ اليقين بوعد الله، ويفاجأ السامع بهول الحدث حاضرًا أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص163–164، تحت عنوان «فائدة التعبير بصيغة الماضي ﴿وقعت﴾»","url":""}]},{"id":"s56-32","number":32,"surah":56,"verses":[1],"references":[{"surah":56,"verses":[1]}],"verseLabel":"الواقعة: 1","question":"ماذا يضيف تعريف القيامة باسم ﴿الْوَاقِعَةُ﴾؟","answer":"يجعلها الواقعة المعهودة التي تنصرف إليها الأذهان ولا تلتبس بحادثة أخرى، ويضفي عليها معنى الكمال والتهويل؛ فكأن الوقائع كلها دونها وهي وحدها الواقعة حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص165، تحت عنوان «معنى تعريف لفظ ﴿الواقعة﴾»","url":""}]},{"id":"s56-9","number":9,"surah":56,"verses":[2],"references":[{"surah":56,"verses":[2]}],"verseLabel":"الواقعة: 2","question":"كيف تحتمل كلمة ﴿كَاذِبَةٌ﴾ معنيين يؤكدان يقين القيامة؟","answer":"يجوز أن تكون وصفًا لنفس تكذب بوقوعها، فيكون المعنى أنه لا يبقى يومئذ مكذب؛ ويجوز أن تكون مصدرًا بمعنى الكذب، فينفي النص أن يخالط وقوعها أي باطل. والوجهان يقطعان الشك من جهة الناس ومن جهة الحدث نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص172–173، تحت عنوان «توجيه ﴿كاذبة﴾ بين المصدرية والوصفية»","url":""}]},{"id":"s56-10","number":10,"surah":56,"verses":[3],"references":[{"surah":56,"verses":[3]}],"verseLabel":"الواقعة: 3","question":"ما سرّ تقديم ﴿خَافِضَةٌ﴾ على ﴿رَافِعَةٌ﴾؟","answer":"تقديم الخفض يناسب مقام التهويل وما يبدأ به مشهد القيامة من انهيار القوى الشامخة واضطراب الأرض والجبال. ثم يأتي الرفع بعده، فيصور انقلاب موازين الدنيا: هبوط من اغتر بعلوه، وارتفاع من أكرمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص184، تحت عنوان «علة تقديم ﴿خافضة﴾ على ﴿رافعة﴾»","url":""}]},{"id":"s56-11","number":11,"surah":56,"verses":[6],"references":[{"surah":56,"verses":[6]}],"verseLabel":"الواقعة: 6","question":"ما سرّ التعبير في قول ﴿وَبُسَّتِ الْجِبَالُ بَسًّا﴾، ولم يقل «سيرت»؟","answer":"البس يدل على التفتيت والخلط حتى تزول صلابة الجبال وتتفرق أجزاؤها. فهو يصور انهيار بنيتها وتحولها إلى فتات، ولا يقتصر على معنى انتقالها من موضع إلى آخر الذي يوحي به التسيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص194–195، تحت عنوان «بلاغة استعمال مفردة (بست)»","url":""}]},{"id":"s56-12","number":12,"surah":56,"verses":[7],"references":[{"surah":56,"verses":[7]}],"verseLabel":"الواقعة: 7","question":"ما سرّ التعبير في قول ﴿وَكُنْتُمْ أَزْوَاجًا ثَلَاثَةً﴾، ولم يقل «أصنافًا»؟","answer":"الأزواج أصناف يقترن أفراد كل منها في الصفات والعمل والمصير. ففي اللفظ معنى المشاكلة والصحبة فوق مجرد التقسيم إلى أنواع، إذ يجتمع كل فريق بمن يناسبه في حاله وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص203، تحت عنوان «بلاغة استعمال مفردة ﴿أزواجًا﴾»","url":""}]},{"id":"s56-13","number":13,"surah":56,"verses":[8,9],"references":[{"surah":56,"verses":[8,9]}],"verseLabel":"الواقعة: 8–9","question":"ماذا تضيف كلمة ﴿أَصْحَابُ﴾ إلى وصف فريقي الميمنة والمشأمة؟","answer":"تشعر الصحبة بالملازمة والاتصال بالمصير؛ فكأن كل فريق صار ملازمًا للجهة والحال التي آل إليها، لا منسوبًا إليها نسبة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص210، تحت عنوان «نكتة استعمال مفردة (أصحاب)»","url":""}]},{"id":"s56-14","number":14,"surah":56,"verses":[10],"references":[{"surah":56,"verses":[10]}],"verseLabel":"الواقعة: 10","question":"ما دلالة تكرار ﴿والسابقون السابقون﴾؟","answer":"التكرار يفخم منزلتهم ويجعلهم كأنهم لا يعرفون بأبلغ من وصف السبق نفسه. ويحتمل أن يكون الثاني توكيدًا للأول ثم يأتي بيان منزلتهم في ﴿أولئك المقربون﴾، أو خبرًا عنه على معنى أنهم السابقون حقًا؛ وكلا الوجهين يرفع شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص222–223، تحت عنوان «نكتة تكرار لفظ ﴿السابقون﴾»","url":""}]},{"id":"s56-15","number":15,"surah":56,"verses":[11],"references":[{"surah":56,"verses":[11]}],"verseLabel":"الواقعة: 11","question":"ما سرّ التعبير في قول ﴿الْمُقَرَّبُونَ﴾، ولم يقل «القريبون»؟","answer":"صيغة «المقربون» تبرز أن الله هو الذي منحهم هذه المنزلة واصطفاهم لها. فالقرب قرب إكرام ورفعة، لا مجرد قرب مكاني؛ وفي البناء للمفعول جمع بين علو مقامهم وكونه فضلًا من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص228، تحت عنوان «نكتة التعبير بصيغة ﴿المقربون﴾»","url":""}]},{"id":"s56-16","number":16,"surah":56,"verses":[17],"references":[{"surah":56,"verses":[17]}],"verseLabel":"الواقعة: 17","question":"لماذا اختير وصف خدم الجنة بـ﴿وِلْدَانٌ﴾؟","answer":"لأنه يستحضر صغر السن ونضارة الهيئة وخفة الحركة، فيناسب خدمة لا كلفة فيها ولا رهبة، ويكمل صورة الأنس والنعيم والسرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص253، تحت عنوان «بلاغة استعمال مفردة ﴿ولدان﴾»","url":""}]},{"id":"s56-33","number":33,"surah":56,"verses":[17],"references":[{"surah":56,"verses":[17]}],"verseLabel":"الواقعة: 17","question":"ماذا يطمئن إليه أهل الجنة في وصف الخدم بأنهم ﴿مُخَلَّدُونَ﴾؟","answer":"يطمئنون إلى أنهم باقون على سن واحدة وهيئة ناضرة، لا يهرمون ولا تنقص طاقتهم ولا تنقطع خدمتهم؛ فالخلود هنا ثبات الصفة والجمال مع دوام البقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص254، تحت عنوان «فائدة الوصف بلفظ ﴿مخلدون﴾»","url":""}]},{"id":"s56-17","number":17,"surah":56,"verses":[19],"references":[{"surah":56,"verses":[19]}],"verseLabel":"الواقعة: 19","question":"كيف يكمل قوله ﴿وَلَا يُنْزِفُونَ﴾ نفي أضرار شراب الجنة؟","answer":"بعد نفي صداع الرأس نُفي ذهاب العقل ونفاد الشراب؛ فالعطف يستوفي الضرر الجسدي والنفسي والانقطاع، ويبين أن لذة خمر الجنة لا يعقبها ألم ولا سكر ولا زوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص264–265، تحت عنوان «فائدة عطف ﴿ولا ينزفون﴾»","url":""}]},{"id":"s56-18","number":18,"surah":56,"verses":[23],"references":[{"surah":56,"verses":[23]}],"verseLabel":"الواقعة: 23","question":"لماذا شبه الحور بـ﴿أَمْثَالِ اللُّؤْلُؤِ الْمَكْنُونِ﴾؟","answer":"اللؤلؤ المكنون محفوظ في صدفه، لم تخدش صفاءه الأيدي ولم تغيره المؤثرات. فالتشبيه يجمع النقاء والجمال والنفاسة والصون، ولا يقتصر على لون البياض وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص280، تحت عنوان «فائدة تشبيه الحور العين باللؤلؤ المكنون»","url":""}]},{"id":"s56-19","number":19,"surah":56,"verses":[25,26],"references":[{"surah":56,"verses":[25,26]}],"verseLabel":"الواقعة: 25–26","question":"لماذا تكرر السلام في قوله ﴿سَلَامًا سَلَامًا﴾؟","answer":"للتأكيد والتعظيم وإشعار أهل الجنة بأن السلام يتجدد عليهم مرة بعد مرة، وتتنوع وجوه الأمن والتكريم؛ فيدخل معنى الطمأنينة في النفس دخولًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص290، تحت عنوان «غرض تكرار ﴿سلامًا﴾»","url":""}]},{"id":"s56-20","number":20,"surah":56,"verses":[31],"references":[{"surah":56,"verses":[31]}],"verseLabel":"الواقعة: 31","question":"ما سرّ وصف الماء بأنه ﴿مَسْكُوبٍ﴾، لا «جارٍ»؟","answer":"المسكوب يوحي بماء يصب سهلًا متصلًا، متاح للانتفاع بلا عناء في طلبه. والجريان يصف حركة الماء، أما السكب فيزيد صورة الوفرة والتهيئة للشارب؛ فكأن الماء أعد وأرسل إلى أهل الجنة حيث يشاؤون.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص307، تحت عنوان «بلاغة وصف الماء بالمسكوب»","url":""}]},{"id":"s56-21","number":21,"surah":56,"verses":[35,36,37],"references":[{"surah":56,"verses":[35,36,37]}],"verseLabel":"الواقعة: 35–37","question":"إلى من يعود الضمير في ﴿إِنَّا أَنْشَأْنَاهُنَّ﴾ مع أن النساء لم يُذكرن صراحة؟","answer":"يعود إلى النساء اللاتي دل عليهن سياق الفرش والنعيم، ويشمل نساء الدنيا الصالحات والحور العين. وترك الاسم الظاهر يفتح المعنى على هذا الشمول ويعظم النعمة بدل حصرها في نوع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص316–317، تحت عنوان «تعيين مرجع الضمير في قوله: ﴿أنشأناهن﴾»","url":""}]},{"id":"s56-34","number":34,"surah":56,"verses":[35,36,37],"references":[{"surah":56,"verses":[35,36,37]}],"verseLabel":"الواقعة: 35–37","question":"لماذا وصف إيجاد نساء الجنة بقوله ﴿أَنْشَأْنَاهُنَّ﴾؟","answer":"لأن الإنشاء يتسع للخلق ابتداء ولإعادة الخلق في صورة أخرى؛ فيشمل خلق الحور وتجديد نساء الدنيا في أكمل هيئة، ويجمع الحقيقة والمجاز في لفظ موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص316، تحت عنوان «بلاغة استعمال مفردة ﴿أنشأناهن﴾»","url":""}]},{"id":"s56-35","number":35,"surah":56,"verses":[35,36,37],"references":[{"surah":56,"verses":[35,36,37]}],"verseLabel":"الواقعة: 35–37","question":"ماذا يفيد جعل نساء الجنة ﴿أَبْكَارًا﴾؟","answer":"يفيد دوام حال الكمال والتجدد؛ فكل واحدة تعاد إلى تمام العفة والنضارة، ولا يزيل تكرر المعاشرة عنها هذه الصفة، فتكون البكارة وصفًا دائمًا من أوصاف النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص320، تحت عنوان «توجيه وصفهن بالأبكار»","url":""}]},{"id":"s56-22","number":22,"surah":56,"verses":[42],"references":[{"surah":56,"verses":[42]}],"verseLabel":"الواقعة: 42","question":"لماذا جُمع لأصحاب الشمال بين ﴿سَمُومٍ وَحَمِيمٍ﴾؟","answer":"ليحيط بهم العذاب من جهتين: ريح حارة تحرق من الخارج، وماء بالغ الحرارة ينفذ إلى الداخل. فاجتماعهما يرسم إحاطة حسية لا يجد الجسد منها منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص339، تحت عنوان «توجيه تخصيص السموم والحميم بالذكر»","url":""}]},{"id":"s56-23","number":23,"surah":56,"verses":[45],"references":[{"surah":56,"verses":[45]}],"verseLabel":"الواقعة: 45","question":"لماذا علل عذابهم بأنهم ﴿كَانُوا قَبْلَ ذَلِكَ مُتْرَفِينَ﴾؟","answer":"ليس المقصود مجرد امتلاك النعمة، بل تنعم أورث الغفلة والبطر والتكبر وترك الشكر. فذكر الترف يكشف منشأ إصرارهم على الذنب وإنكار الحساب، ويبين مسؤوليتهم عن سوء استعمال ما أتيح لهم من النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص353، تحت عنوان «توجيه تخصيص الترف بالذكر»","url":""}]},{"id":"s56-24","number":24,"surah":56,"verses":[49,50],"references":[{"surah":56,"verses":[49,50]}],"verseLabel":"الواقعة: 49–50","question":"لماذا قيل عن الأولين والآخرين ﴿لَمَجْمُوعُونَ﴾ لا «لمبعوثون»؟","answer":"لأن الجمع يتضمن البعث ويزيد عليه أنهم يحشرون كلهم في وقت واحد بعد تفرق موتهم في الأزمنة والأماكن؛ فيصير اللفظ أصرح في الاجتماع وأشد وقعًا في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص372، تحت عنوان «نكتة العدول عن لفظ البعث إلى الجمع»","url":""}]},{"id":"s56-25","number":25,"surah":56,"verses":[58,59],"references":[{"surah":56,"verses":[58,59]}],"verseLabel":"الواقعة: 58–59","question":"لماذا ردَّهم القرآن إلى ما ﴿تُمْنُونَ﴾ عند الاستدلال على البعث؟","answer":"لأن اللفظ يعيد الإنسان إلى نقطة الخلق الأولى: قطرة مهينة لا يملك سرها ولا مصيرها. فمن أبدع الإنسان منها قادر على أن يعيده بعد أن يصير عظامًا وترابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص406–407، تحت عنوان «براعة اختيار مفردة ﴿تمنون﴾»","url":""}]},{"id":"s56-36","number":36,"surah":56,"verses":[58,59],"references":[{"surah":56,"verses":[58,59]}],"verseLabel":"الواقعة: 58–59","question":"ما الذي يقرره الاستفهام ﴿أَأَنْتُمْ تَخْلُقُونَهُ﴾ بعد ذكر النطفة؟","answer":"يقرر أن مباشرة السبب ليست خلقًا؛ فالناس يلقون النطفة لكنهم لا يصنعون مادتها ولا يدبرون أطوارها. والاستفهام يلزمهم بالإقرار بأن خالق النشأة الأولى هو القادر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص407–408، تحت عنوان «غرض الاستفهام في قوله: ﴿أأنتم﴾»","url":""}]},{"id":"s56-26","number":26,"surah":56,"verses":[63,64],"references":[{"surah":56,"verses":[63,64]}],"verseLabel":"الواقعة: 63–64","question":"كيف يكشف الانتقال من ﴿تَحْرُثُونَ﴾ إلى ﴿تَزْرَعُونَهُ﴾ حدود قدرة الإنسان؟","answer":"ذكر الحرث أولًا لأنه العمل الظاهر الذي يباشره الإنسان من شق الأرض وبذرها، ثم اختص الله بالزرع وهو الإحياء والإنبات. وحذف كل فعل من موضع صاحبه يكشف الفارق: للإنسان السبب، ولله الإيجاد الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص440، تحت عنوان «بلاغة الاحتباك بين فعلي الحرث والزراعة»","url":""}]},{"id":"s56-27","number":27,"surah":56,"verses":[68,69],"references":[{"surah":56,"verses":[68,69]}],"verseLabel":"الواقعة: 68–69","question":"لماذا قيل إن الماء ينزل من ﴿الْمُزْنِ﴾ لا من «السحاب»؟","answer":"لأن المزن أخص: هو السحاب المشحون بالماء والمنتظر منه المطر، لا مطلق السحاب العابر. فاختياره يربط ماء الشرب بوعائه الحقيقي، ويجعل النعمة والتحدي أوضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص462، تحت عنوان «نكتة استعمال مفردة ﴿المزن﴾ دون رديفاتها»","url":""}]},{"id":"s56-28","number":28,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"ما المعاني التي يفتحها القسم بـ﴿مَوَاقِعِ النُّجُومِ﴾؟","answer":"يفتح معنى منازل النجوم ومساراتها ومطالعها ومغاربها، ويفتح أيضًا معنى مواقع نزول آيات القرآن وتدرج الوحي؛ فعلى الأول تعظيم لنظام السماء، وعلى الثاني تعظيم لحكمة التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص490، تحت عنوان «دلالة مفردة (مواقع)»","url":""}]},{"id":"s56-37","number":37,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"لماذا أقسم القرآن بمواقع النجوم لا بالنجوم وحدها؟","answer":"لأن المواقع تشمل نظام النجوم كله: طلوعها وغروبها ومساراتها وتباعدها في الزمان والمكان، فتكون أوسع دلالة وأدعى إلى الخشوع والتأمل من ذكر الأجرام مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص493، تحت عنوان «نكتة ذكر (مواقع) دون الاكتفاء بالنجوم»","url":""}]},{"id":"s56-38","number":38,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"ماذا يضيف وصف القسم بمواقع النجوم بأنه ﴿عَظِيمٌ﴾؟","answer":"يفخم المقام ويوقظ السامع إلى جلال المقسَم به وخفاء أسراره، ويمهد لتعظيم المقسَم عليه وهو القرآن الكريم؛ فكأن عظمة الآية الكونية تقود إلى عظمة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص498، تحت عنوان «دلالة وصف القسم بعظيم»","url":""}]},{"id":"s56-39","number":39,"surah":56,"verses":[47],"references":[{"surah":56,"verses":[47]}],"verseLabel":"الواقعة: 47","question":"ما سر قوله: ﴿أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا﴾، وفي الإسراء: ﴿أَئِذَا كُنَّا عِظَامًا وَرُفَاتًا﴾؟","answer":"التراب والعظام أدلّ على البِلى من العظام والرفات، فالرفات إذا بَلِي صار ترابًا، فبعثه أبعد في عقولهم وأدعى إلى العجب. ولذلك أضافوا ذكر الموت للزيادة في الاستبعاد، وزادوا هنا ﴿أَوَآبَاؤُنَا الْأَوَّلُونَ﴾، فكيف يُبعث آباؤهم وقد أصابهم من البِلى ما أصابهم؟","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص117–118.","url":""}]},{"id":"s56-40","number":40,"surah":56,"verses":[65],"references":[{"surah":56,"verses":[65]}],"verseLabel":"الواقعة: 65","question":"ما سر حذف إحدى اللامين في قوله: ﴿فَظَلْتُمْ تَفَكَّهُونَ﴾، والأصل «ظَلَلْتم»؟","answer":"معنى «تفكّهون» تقولون ذلك متندّمين، والقول لا يظلّ مستمرًا على الدوام كما قد يستمر الحزن، فناسب الحذفُ من الفعل قصرَ الحدث، كما حُذفت في ﴿ظَلْتَ عَلَيْهِ عَاكِفًا﴾ لقصر مدة عكوفهم على العجل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص82–83.","url":""}]},{"id":"s56-41","number":41,"surah":56,"verses":[10,40],"references":[{"surah":56,"verses":[10,40]}],"verseLabel":"الواقعة: 10، 40","question":"ما الفرق بين وصف نعيم ﴿وَالسَّابِقُونَ السَّابِقُونَ﴾ ونعيم ﴿أَصْحَابُ الْيَمِينِ﴾ في السورة؟","answer":"ذكر للسابقين سررًا موضونة يتكئون عليها متقابلين ولأصحاب اليمين «فرشًا مرفوعة»، وذكر للسابقين ولدانًا يطوفون بأكواب وأباريق ولأولئك «ماءً مسكوبًا»، وللسابقين فاكهة مما يتخيّرون ولحم طير مما يشتهون ولأولئك سدر مخضود وطلح منضود، وصرّح بالحور العين للسابقين ولم يصرّح بهن لأصحاب اليمين، ففرّق بين النعيمين بحسب المنزلتين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص219–220.","url":""}]},{"id":"s56-42","number":42,"surah":56,"verses":[19],"references":[{"surah":56,"verses":[19]}],"verseLabel":"الواقعة: 19","question":"ما سر وصف شراب السابقين بقوله: ﴿لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ﴾، وفي الصافات: ﴿لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ﴾؟","answer":"سياق الواقعة في السابقين المقرّبين وهم أعلى من المخلصين في الصافات. ونفي الصداع نفيٌ للأدنى فينتفي الغول من باب أولى، ولا ينفي نفيُ الغول الصداع. و«يُنزِفون» بالكسر تجمع نفي السكر ونفي نفاد الشراب، أما «يُنزَفون» فنفي السكر وحده، فما في الواقعة أتمّ. ومعنى «يُنزِفون» منقول عن «لسان العرب» عن الفراء.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص73–76.","url":""}]},{"id":"s56-43","number":43,"surah":56,"verses":[50],"references":[{"surah":56,"verses":[50]}],"verseLabel":"الواقعة: 50","question":"ما سر «إلى» في قوله: ﴿لَمَجْمُوعُونَ إِلَىٰ مِيقَاتِ يَوْمٍ مَّعْلُومٍ﴾، واللام في الشعراء: ﴿فَجُمِعَ السَّحَرَةُ لِمِيقَاتِ يَوْمٍ مَّعْلُومٍ﴾؟","answer":"«إلى» تفيد انتهاء الغاية، والأولون والآخرون يستمر جمعهم حتى ينتهي إلى ميقات يوم القيامة. واللام في الشعراء أظهر أنها للتعليل، لأن السحرة جُمعوا قبل ذلك اليوم لأجله، ولم يكن جمعهم مستمرًا إليه.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص87.","url":""}]},{"id":"s57-1","number":1,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"ما سرّ افتتاح الحديد ﴿سَبَّحَ لِلَّهِ﴾ بعد أن ختمت الواقعة بالأمر ﴿فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ﴾؟","answer":"ختمت الواقعة بالأمر بالتسبيح، ثم أخبرت الحديد بتسبيح ما في السماوات والأرض، فظهر اتصال الأمر بما يشهد له الكون كله. وكأن المطلع يقول للمخاطب: سبح ربك، فقد سبحت له المخلوقات، فيتسع مشهد التعظيم ويؤكد استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص577، تحت عنوان «مناسبة السورة لما قبلها»","url":""}]},{"id":"s57-2","number":2,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"ما سرّ جمع السماوات والأرض تحت اسم الموصول الواحد في قوله ﴿مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"عدم تكرار «ما» يجمع السماوات والأرض في نظر المخاطب كأنهما شيء واحد في الخضوع لله ووحدة التسبيح. ويناسب ذلك ما يلي من تقرير صفات الله وملكه العام، فتلتقي كثرة المخلوقات في وحدة العبودية والسلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص585، تحت عنوان «سر عدم اقتران (ما) بالأرض كما اقترنت بالسماوات»","url":""}]},{"id":"s57-3","number":3,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"لماذا ناسب وصف الله بـ﴿الْحَكِيمُ﴾ تسبيح المخلوقات في مطلع الحديد؟","answer":"لأن التسبيح يقر بخضوع الكون لتدبير لا خلل فيه؛ فالحكيم يضع كل شيء موضعه، وتصدر أفعاله عن علم وإحكام لا عن عبث أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص586، تحت عنوان «سر اختيار وصف ﴿الحكيم﴾»","url":""}]},{"id":"s57-4","number":4,"surah":57,"verses":[18],"references":[{"surah":57,"verses":[18]}],"verseLabel":"الحديد: 18","question":"ما الذي تضيفه قراءتا ﴿الْمُصَّدِّقِينَ وَالْمُصَّدِّقَاتِ﴾ إلى معنى الآية؟","answer":"قراءة التشديد تعني المتصدقين والمتصدقات، فتبرز بذل المال؛ وقراءة التخفيف تعني المصدقين والمصدقات، فتبرز صدق الإيمان. وتتكامل القراءتان في وصل الاعتقاد بالعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص96–97، تحت عنوان «أثر اختلاف القراءات في قوله: ﴿المصدقين والمصدقات﴾»","url":""}]},{"id":"s57-5","number":5,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"ماذا يصور تشبيه عرض الجنة بعرض السماء والأرض؟","answer":"يقرب إلى الذهن سعة الجنة الهائلة بما يشاهده الإنسان من امتداد السماء والأرض، من غير أن يحصرها في قياس تدركه الأبصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص183، تحت عنوان «دلالة تشبيه عرض الجنة بمجموع عرضي السماء والأرض»","url":""}]},{"id":"s57-31","number":31,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"لماذا أُفردت ﴿السَّمَاءُ﴾ في وصف عرض الجنة؟","answer":"لأن المفرد قد يراد به جنس السماوات كلها، فيجمع الإيجاز بين العموم والعظمة، ويبقي الصورة حاضرة في الذهن بلا تعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص184، تحت عنوان «سر إفراد ﴿السماء﴾ دون جمعها»","url":""}]},{"id":"s57-6","number":6,"surah":57,"verses":[1,29],"references":[{"surah":57,"verses":[1,29]}],"verseLabel":"الحديد: 29، المجادلة 1","question":"كيف يكشف افتتاح المجادلة بسماع شكوى امرأة معنى فضل الله في ختام الحديد؟","answer":"ختمت الحديد بأن الفضل بيد الله، ثم جاء سماع شكوى امرأة وإنزال حكم يفرج عنها مثالًا حيًا لهذا الفضل ولإحاطة علم الله ومعيته بعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص398–399، تحت عنوان «مناسبة السورة لما قبلها»","url":""}]},{"id":"s57-7","number":7,"surah":57,"verses":[2],"references":[{"surah":57,"verses":[2]}],"verseLabel":"الحديد: 2","question":"لماذا ذُكر الإحياء والإماتة بعد ملك السماوات والأرض؟","answer":"لبيان أن ملك الله تصرف نافذ لا اسم مجرد؛ فمن أعظم آثاره إنشاء الحياة وإنهاؤها، وهما دليلان على كمال السلطان والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص594، تحت عنوان «موقع جملة ﴿يحيي ويميت﴾ مما قبلها ودلالته»","url":""}]},{"id":"s57-8","number":8,"surah":57,"verses":[3],"references":[{"surah":57,"verses":[3]}],"verseLabel":"الحديد: 3","question":"ما الذي يجمعه قوله ﴿الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ﴾ من معاني الكمال؟","answer":"يقرر أن الله الأول بلا ابتداء، والآخر بلا انتهاء، والظاهر بآياته وقهره، والباطن الذي لا تحيط به الأبصار ويحيط بالخفايا؛ فيستوعب كمال الوجود والعلم والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص602–603، تحت عنوان «بلاغة التعبير بأسلوب الطباق»","url":""}]},{"id":"s57-32","number":32,"surah":57,"verses":[3],"references":[{"surah":57,"verses":[3]}],"verseLabel":"الحديد: 3","question":"لماذا رُتبت أسماء الله: الأول والآخر والظاهر والباطن بهذا النسق؟","answer":"بدأ بمراتب الوجود زمانًا، ثم انتقل إلى الإحاطة ظهورًا وخفاءً؛ فكل اسم يقابله ما يتم به المعنى، ويتتابع النسق ليحيط القلب بجلال الله من كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص604، تحت عنوان «بلاغة ترتيب أسمائه سبحانه في الآية، وسر اقترانها»","url":""}]},{"id":"s57-10","number":10,"surah":57,"verses":[4],"references":[{"surah":57,"verses":[4]}],"verseLabel":"الحديد: 4","question":"كيف تكون معية الله لعباده في قوله ﴿وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ﴾؟","answer":"هي معية تليق بالله، معناها إحاطة علمه وقدرته وسلطانه بأحوالهم أينما كانوا، لا حلولًا في مكان؛ فتورث المراقبة والطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص626، تحت عنوان «بلاغة التعبير بالمعية ﴿معكم﴾»","url":""}]},{"id":"s57-12","number":12,"surah":57,"verses":[7],"references":[{"surah":57,"verses":[7]}],"verseLabel":"الحديد: 7","question":"ما سرّ التعبير في قول ﴿مِمَّا جَعَلَكُمْ مُسْتَخْلَفِينَ فِيهِ﴾ بدل «من أموالكم»؟","answer":"المال ليس ملكًا ذاتيًا مستقلًا للإنسان، بل هو مال الله جعله في يده مدة وأمره بحسن التصرف فيه. والاستخلاف يذكره أيضًا بأنه خلف غيره وسيخلفه غيره؛ فيخف تعلقه بالمال ويسهل عليه الإنفاق في طاعة مالكه الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص662–663، تحت عنوان «بلاغة التعبير بالمجاز في قوله: ﴿مستخلفين﴾»","url":""}]},{"id":"s57-13","number":13,"surah":57,"verses":[8],"references":[{"surah":57,"verses":[8]}],"verseLabel":"الحديد: 8","question":"ما غرض السؤال ﴿وَمَا لَكُمْ لَا تُؤْمِنُونَ بِاللَّهِ﴾؟","answer":"هو توبيخ وتعجيب من ترك الإيمان بعد قيام حجته؛ فليس سؤالًا يطلب جوابًا، بل يهز النفس لتفتش عما بقي من عذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص671–672، تحت عنوان «الغرض من التعبير بالاستفهام بـ (ما) في قوله: ﴿وما لكم﴾»","url":""}]},{"id":"s57-33","number":33,"surah":57,"verses":[8],"references":[{"surah":57,"verses":[8]}],"verseLabel":"الحديد: 8","question":"لماذا ذُكرت دعوة الرسول في أثناء عتابهم على ترك الإيمان؟","answer":"لأن دعوته قائمة واضحة تقطع الشبهة وتكشف أن الإعراض ليس لنقص البيان؛ فالرسول بين أظهرهم يتلو آيات الله ويدعوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص674، تحت عنوان «بلاغة التعبير بالجملة الحالية في قوله: ﴿والرسول يدعوكم لتؤمنوا بربكم﴾»","url":""}]},{"id":"s57-34","number":34,"surah":57,"verses":[8],"references":[{"surah":57,"verses":[8]}],"verseLabel":"الحديد: 8","question":"ماذا يضيف قوله ﴿وَقَدْ أَخَذَ مِيثَاقَكُمْ﴾ إلى عتابهم؟","answer":"يضيف حجة سابقة مؤكدة: فقد أخذ الله عليهم العهد، فصار الإعراض بعد الدعوة والميثاق أشد قبحًا وأبعد عن العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص677، تحت عنوان «سر التقييد بالجملة الحالية ﴿وقد أخذ ميثاقكم﴾»","url":""}]},{"id":"s57-14","number":14,"surah":57,"verses":[10],"references":[{"surah":57,"verses":[10]}],"verseLabel":"الحديد: 10","question":"لماذا كان الإنفاق والقتال قبل الفتح أعظم درجة؟","answer":"لأنهما وقعا في زمن شدة وقلة ناصر، فكان السبق إليهما أدل على قوة اليقين وصدق الإيمان وأعظم أثرًا في نصرة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص713، تحت عنوان «سر تقييد الفعلين ﴿أنفق﴾ و(قاتل) بقوله: ﴿من قبل﴾»","url":""}]},{"id":"s57-15","number":15,"surah":57,"verses":[11],"references":[{"surah":57,"verses":[11]}],"verseLabel":"الحديد: 11","question":"ماذا يفيد التعبير عن القرض لله بالفعل المضارع ﴿يُقْرِضُ﴾؟","answer":"يفيد تجدد باب الإنفاق واستمراره؛ فكأن الدعوة مفتوحة في كل وقت لمن يبذل ماله مخلصًا، مع وعده بعوض مضاعف لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص730، تحت عنوان «دلالة التعبير بالفعل ﴿يقرض﴾ مادة وصيغة، وسر استعارته»","url":""}]},{"id":"s57-16","number":16,"surah":57,"verses":[12],"references":[{"surah":57,"verses":[12]}],"verseLabel":"الحديد: 12","question":"لماذا قُدِّم نور المؤمنين بين أيديهم على نور أيمانهم؟","answer":"لأن ما بين الأيدي موضع الطريق والسير، فنورهم أمامهم يهديهم، ثم ذكر الأيمان لما فيها من اليمن والتشريف وأخذ الكتب بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص751–752، تحت عنوان «سر تقديم الأيدي على الأيمان»","url":""}]},{"id":"s57-35","number":35,"surah":57,"verses":[12],"references":[{"surah":57,"verses":[12]}],"verseLabel":"الحديد: 12","question":"هل يقتصر نور المؤمنين على ما بين أيديهم وأيمانهم؟","answer":"لا يلزم الحصر؛ فقد خُصت الجهتان لأنهما أشرف الجهات وأوضحها في مشهد المسير والكرامة، ويجوز أن يعم النور سائر جوانبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص752–753، تحت عنوان «دلالة تخصيص الجمع بين الأيدي والأيمان»","url":""}]},{"id":"s57-17","number":17,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"ما المقصود بالأمر للمنافقين ﴿ارْجِعُوا وَرَاءَكُمْ﴾؟","answer":"هو تهكم وتيئيس: ارجعوا إلى الدنيا حيث كان سبب النور الإيمان والعمل، وقد فات زمن الاكتساب؛ أو ارجعوا إلى موضع قسمة النور، ولن يجدوا شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص780–781، تحت عنوان «دلالة الأمر في قوله: ﴿ارجعوا﴾»","url":""}]},{"id":"s57-36","number":36,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"لماذا قيل للمنافقين ﴿فَالْتَمِسُوا نُورًا﴾ وهم يعلمون أنه مفقود؟","answer":"لإبراز خيبة أملهم؛ فطلب النور بعد انقضاء زمن العمل تهكم يوقظ حسرتهم ويكشف أن مجرد مصاحبة المؤمنين لم تمنحهم إيمانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص785، تحت عنوان «دلالة الأمر بالرجوع والتماس النور المفقود»","url":""}]},{"id":"s57-18","number":18,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"لماذا نُص على وجود باب في السور الفاصل بين المؤمنين والمنافقين؟","answer":"ليزيد حسرة المنافقين؛ يرون الرحمة وراء باب قريب ولا يملكون دخوله، وليبين أن طريق الجنة واحد لا يفتح إلا بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص791، تحت عنوان «دلالة التنصيص على وجود باب في السور»","url":""}]},{"id":"s57-37","number":37,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"ماذا يمثل السور المضروب بين المؤمنين والمنافقين؟","answer":"يمثل الفصل الحقيقي بين مصيرين بعد أن تشابه الفريقان ظاهرًا في الدنيا؛ نور ونعيم للمؤمنين، وظلمة وعذاب للمنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص792، تحت عنوان «بلاغة التمثيل في قوله: ﴿فضرب بينهم بسور﴾ الآية»","url":""}]},{"id":"s57-38","number":38,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"ما أثر المقابلة بين ﴿بَاطِنُهُ﴾ و﴿ظَاهِرُهُ﴾ في وصف السور؟","answer":"تبرز التناقض الحاد بين الرحمة والعذاب في مشهد واحد، وتكشف الفرق بين باطن الإيمان وباطن النفاق الذي ستره ظاهر الصحبة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص795، تحت عنوان «بلاغة الطباق بين قوله: ﴿باطنه﴾ و﴿ظاهره﴾»","url":""}]},{"id":"s57-19","number":19,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"ما الذي يوقظه السؤال ﴿أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا﴾؟","answer":"يوقظ الهمم بعتاب مؤثر: لقد حان وقت الخشوع فلا يليق بالمؤمن تأخيره، والاستفهام يقرع الوجدان من غير انتظار جواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص55، تحت عنوان «دلالة التعبير بأسلوب الاستفهام ﴿ألم يأن﴾»","url":""}]},{"id":"s57-39","number":39,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"لماذا أُسند الخشوع إلى القلوب؟","answer":"لأن القلب مركز الإيمان والتأثر، فإذا خشع انقادت الجوارح، والمطلوب خشوع داخلي صادق لا مجرد صمت الأصوات أو مظهر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص60، تحت عنوان «سر إسناد الخشوع إلى (القلوب)»","url":""}]},{"id":"s57-20","number":20,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"كيف أفضى طول الأمد بأهل الكتاب إلى قسوة القلوب؟","answer":"طال عليهم الزمن مع الغفلة وترك تجديد الصلة بالوحي، فضعف أثر الذكر ثم ثبتت القسوة في قلوبهم؛ فالسبب ليس الزمن وحده بل ما صحبه من إعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص70–72، تحت عنوان «نوع الفاء في قوله: ﴿فقست﴾، ودلالتها»","url":""}]},{"id":"s57-21","number":21,"surah":57,"verses":[17],"references":[{"surah":57,"verses":[17]}],"verseLabel":"الحديد: 17","question":"كيف يفتح إحياء الأرض باب الرجاء بعد الحديث عن قسوة القلوب؟","answer":"كما يحيي الله الأرض اليابسة بالمطر، يحيي القلب القاسي بالذكر والوحي؛ فالمشهد دليل قدرة وتشجيع على التوبة بعد اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص83–84، تحت عنوان «دلالة ارتباط إحياء الأرض بذكر الله في الآية السابقة»","url":""}]},{"id":"s57-22","number":22,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"ما سرّ وصف الدنيا بأنها ﴿لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌ... وَتَكَاثُرٌ﴾ بهذا الترتيب؟","answer":"يجري الترتيب مع أطوار التعلق بالدنيا: لعب في الصغر، ثم لهو، ثم عناية بالزينة، ثم تنافس في المكانة وكثرة المال والولد. فيختصر مسارًا طويلًا من الانشغال بالمظاهر، وينبه إلى قصره وسرعة انقضائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص143، تحت عنوان «بلاغة البدء باللعب والانتهاء بالتكاثر في الأموال والأولاد»","url":""}]},{"id":"s57-23","number":23,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"لماذا قيل ﴿ثُمَّ يَهِيجُ﴾ بعد نضرة النبات؟","answer":"لتصوير انتقاله بعد مدة من القوة والنضرة إلى الجفاف والذبول، فتفصل ثم بين مرحلتين وتستحضر تقلب الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص151، تحت عنوان «دلالة التعبير بـ﴿ثم﴾ دون الفاء في قوله: ﴿ثم يهيج﴾»","url":""}]},{"id":"s57-40","number":40,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"ماذا تفيد الفاء في قوله ﴿فَتَرَاهُ مُصْفَرًّا﴾؟","answer":"تفيد أن الاصفرار يعقب الهيجان ويظهر سريعًا للعين، فيرى الإنسان زوال البهجة رأي مشاهدة لا خبرًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص152، تحت عنوان «دلالة التعبير بالفاء في قوله: ﴿فتراه﴾»","url":""}]},{"id":"s57-41","number":41,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"لماذا عادت ﴿ثُمَّ﴾ في قوله ﴿ثُمَّ يَكُونُ حُطَامًا﴾؟","answer":"لتصور مرحلة لاحقة يكتمل فيها تفتت النبات بعد اصفراره، فتتدرج الصورة من الذبول إلى الانكسار والحطام.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص154، تحت عنوان «دلالة العطف بـ﴿ثم﴾ دون الفاء»","url":""}]},{"id":"s57-24","number":24,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"إلى ماذا يتسابق المؤمنون في قوله ﴿سَابِقُوا﴾ مع حذف جهة السباق؟","answer":"حُذف المتعلَّق ليعم كل عمل صالح يسبق بهم إلى المغفرة والجنة؛ فلا يحصر السباق في عبادة واحدة، بل يشمل أبواب الخير كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص177، تحت عنوان «دلالة الحذف من جملة المسابقة»","url":""}]},{"id":"s57-25","number":25,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"لماذا جُمعت مصائب الأرض ومصائب الأنفس؟","answer":"لاستيعاب المصائب العامة الواقعة في العالم، كالجدب، والخاصة التي تمس الإنسان في صحته وأهله وحاله؛ فلا يخرج شيء منها عن تقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص203، تحت عنوان «دلالة الواو في قوله: ﴿ولا في أنفسكم﴾»","url":""}]},{"id":"s57-42","number":42,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"ماذا يصور قوله إن المصائب ﴿فِي كِتَابٍ﴾؟","answer":"يصور ثبوتها في علم الله وتقديره قبل وقوعها، فالكتاب اللوح المحفوظ، وفي التعبير طمأنينة بأن الحوادث ليست فوضى ولا مفاجأة لعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص206، تحت عنوان «سر التعبير بـ﴿كتاب﴾»","url":""}]},{"id":"s57-43","number":43,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"ما الحكمة من معرفة أن المصائب والعطايا مقدرة؟","answer":"لكيلا يستولي الحزن على ما فات، ولا يتحول الفرح بالعطاء إلى بطر وفخر؛ فيعيش المؤمن بين الصبر والشكر والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص217، تحت عنوان «دلالة التعبير باللام في قوله: ﴿لكيلا﴾»","url":""}]},{"id":"s57-26","number":26,"surah":57,"verses":[23],"references":[{"surah":57,"verses":[23]}],"verseLabel":"الحديد: 23","question":"لماذا قيل ﴿بِمَا آتَاكُمْ﴾ بدل «أعطاكم»؟","answer":"لأن الإيتاء أوسع من مجرد التمليك، فيشمل كل ما وصل إلى العبد من فضل الله، ويذكره بجلالة مصدر النعمة فلا يبطر بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص222، تحت عنوان «دلالة التعبير بـ﴿آتاكم﴾»","url":""}]},{"id":"s57-44","number":44,"surah":57,"verses":[23],"references":[{"surah":57,"verses":[23]}],"verseLabel":"الحديد: 23","question":"ماذا يفيد مجيء ﴿آتَاكُمْ﴾ بصيغة الماضي؟","answer":"يفيد تحقق العطاء وثبوته، لا الوعد به، فيكون الفرح المذموم بما حصل فعلًا وكأن صاحبه يراه استحقاقًا ذاتيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص222، تحت عنوان «دلالة التعبير بالفعل ﴿آتاكم﴾ ماضيًا»","url":""}]},{"id":"s57-27","number":27,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"لماذا قرن إنزال الكتاب والميزان بإنزال الحديد؟","answer":"تجتمع الثلاثة في إقامة القسط: الكتاب يبين الحق ويهدي إليه، والميزان معيار العدل في التعامل، والحديد قوة تحمي العدل وترد العدوان. فالهداية والإنصاف يحتاجان إلى ما يصونهما، كما تحتاج القوة إلى هداية تضبط استعمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص271–272، تحت عنوان «وجه المناسبة بين ﴿الكتاب﴾ و﴿الميزان﴾ و﴿الحديد﴾»","url":""}]},{"id":"s57-28","number":28,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"لماذا قُدِّم بأس الحديد على منافعه للناس؟","answer":"لأن السياق يتحدث عن الرسل والبينات وإقامة القسط، وقد يحتاج الحق أمام العناد إلى قوة تحميه وتردع المعتدي؛ فناسب تقديم البأس، ثم ذُكرت المنافع لتكتمل صورة الحديد أداةً للحماية والعمران.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص276، تحت عنوان «سر تقديم البأس على المنافع»","url":""}]},{"id":"s57-45","number":45,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"ماذا يوحي تنكير ﴿مَنَافِعُ﴾ الحديد وجمعها؟","answer":"يوحي بأن منافعه كثيرة متنوعة لا تحصى ولا تنحصر في وجه واحد؛ فهي تمتد من أدوات الحماية إلى الزراعة والبناء والصناعة وسائر مصالح الحياة، ولذلك جاء اللفظ جمعًا منكرًا يفتح مجال الاتساع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص276، تحت عنوان «نكتة تنكير (منافع) وجمعه»","url":""}]},{"id":"s57-29","number":29,"surah":57,"verses":[27],"references":[{"surah":57,"verses":[27]}],"verseLabel":"الحديد: 27","question":"ماذا يقرر قوله عن الرهبانية ﴿مَا كَتَبْنَاهَا عَلَيْهِمْ﴾؟","answer":"يقرر أن الله لم يفرضها عليهم في أصل الشريعة، بل ابتدعوها من عند أنفسهم. فالدين لا يثبت بمجرد استحسان البشر، ولو كان الدافع حسنًا، وإنما مرد التشريع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص330، تحت عنوان «دلالة نفي الكتابة في قوله: ﴿ما كتبناها﴾»","url":""}]},{"id":"s57-46","number":46,"surah":57,"verses":[27],"references":[{"surah":57,"verses":[27]}],"verseLabel":"الحديد: 27","question":"كيف نُفي فرض الرهبانية ثم قيل ﴿إِلَّا ابْتِغَاءَ رِضْوَانِ اللَّهِ﴾؟","answer":"المعنى أنهم أحدثوها طلبًا لرضوان الله، لا أن الله شرعها لهم؛ ويحتمل أن المراد أنه لم يكتب عليهم إلا ما أوجبوه على أنفسهم ابتغاء الرضوان. وفي الوجهين يظهر أن حسن القصد لا يجعل الابتداع تشريعًا إلهيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص331–332، تحت عنوان «دلالة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s57-47","number":47,"surah":57,"verses":[27],"references":[{"surah":57,"verses":[27]}],"verseLabel":"الحديد: 27","question":"ماذا يضيف وصف الرعاية بأنها ﴿حَقَّ رِعَايَتِهَا﴾؟","answer":"يبين أن التقصير لم يكن هفوة يسيرة، بل إخلالًا بما التزموه من رعاية تامة صادقة؛ فالتعبير يحمّلهم مسؤولية الوفاء الكامل ويكشف أن الدعوى لا تغني من العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص336، تحت عنوان «دلالة التقييد بقوله: ﴿حق رعايتها﴾»","url":""}]},{"id":"s57-30","number":30,"surah":57,"verses":[28],"references":[{"surah":57,"verses":[28]}],"verseLabel":"الحديد: 28","question":"لماذا قيل ﴿نُورًا تَمْشُونَ بِهِ﴾ لا «تمشون فيه»؟","answer":"لأن الباء تجعل النور أداةً يستعينون بها ورفيقًا ملازمًا لسيرهم، لا مجرد مكان يحيط بهم؛ فيصحبهم نور الإيمان في الدنيا ونور النجاة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص364، تحت عنوان «دلالة تعدية ﴿تمشون﴾ بالباء دون (في)»","url":""}]},{"id":"s57-48","number":48,"surah":57,"verses":[28],"references":[{"surah":57,"verses":[28]}],"verseLabel":"الحديد: 28","question":"ما الصورة التي يرسمها قوله ﴿نُورًا تَمْشُونَ بِهِ﴾؟","answer":"يمثل المؤمن بمسافر يسير في طريق خطر ومعه نور يكشف العوائق ويهديه إلى الغاية؛ فتصير الهداية نورًا محسوسًا، والطاعة مشيًا ثابتًا، ويقابلها الضلال كالتخبط في الظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص365، تحت عنوان «بلاغة التمثيل في قوله: ﴿ويجعل لكم نورًا تمشون به﴾»","url":""}]},{"id":"s57-49","number":49,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"ما سر عدم تكرار «ما» في قوله تعالى: ﴿سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، وقد كُررت في مواضع أخرى من آيات التسبيح؟","answer":"حيث كُررت «ما» في آيات التسبيح فقيل ﴿وَمَا فِي الْأَرْضِ﴾ أعقب ذلك كلام على أهل الأرض، وحيث لم تُكرر لم يُذكر بعدها شيء يتعلق بأهل الأرض. ولما لم يأتِ بعد هذه الآية ما يتعلق بأهل الأرض لم تُكرر «ما».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص98–99؛ وعلى طريق التفسير البياني، ج1، ص236.","url":""}]},{"id":"s57-50","number":50,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"ما دلالة بناء الفعل للمجهول في قوله: ﴿كَالَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلُ﴾؟","answer":"يُستعمل «أوتوا الكتاب» بالبناء للمجهول في مواطن الذم، ويُستعمل «آتيناهم الكتاب» بإسناد الفعل إلى الله في مواطن المدح. والسياق هنا ذم، إذ قال بعده: ﴿فَطَالَ عَلَيْهِمُ الْأَمَدُ فَقَسَتْ قُلُوبُهُمْ﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص323–324.","url":""}]},{"id":"s57-51","number":51,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"ما سر قوله: ﴿أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ﴾ دون «ألم يأن لقلوب المؤمنين أن تخشع»؟","answer":"من أسباب ذلك أنه حذّرهم من أن يكونوا كالذين أوتوا الكتاب، فقال: ﴿وَلَا يَكُونُوا كَالَّذِينَ أُوتُوا الْكِتَابَ﴾، ولم يقل: كقلوب الذين أوتوا الكتاب، فناسب أن يكون الكلام على المؤمنين في مقابل الذين أوتوا الكتاب. وقد جمعت الآية ثلاثة دواعٍ إلى الخشية: كونهم مؤمنين، وذكر الله، وما نزل من الحق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص266–267.","url":""}]},{"id":"s57-52","number":52,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"ما سر قوله: ﴿إِنَّ اللَّهَ قَوِيٌّ عَزِيزٌ﴾ بلا لام، وفي الحج: ﴿إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ﴾ باللام؟","answer":"آية الحج في سياق القتال ونصرة المظلومين المعتدى عليهم، فناسبها التوكيد باللام. وآية الحديد في نصرة المؤمنين لدعوة الله ورسله: ﴿وَلِيَعْلَمَ اللَّهُ مَنْ يَنْصُرُهُ وَرُسُلَهُ بِالْغَيْبِ﴾، فلم تحتج إلى ذلك التوكيد.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص174–175.","url":""}]},{"id":"s57-53","number":53,"surah":57,"verses":[2],"references":[{"surah":57,"verses":[2]}],"verseLabel":"الحديد: 2","question":"ما سر قوله: ﴿لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ﴾ دون «وما بينهما» كما في المائدة والزخرف؟","answer":"كل موطن ذُكر فيه ﴿وَمَا بَيْنَهُمَا﴾ جاء تعقيبًا على قول في الله لا يليق به، كادعاء الولد، فذكر سعة ملكه بيانًا لغناه عن الولد. ومن الطريف أنه يأتي في سياق الكلام على ثلاث ملل: اليهود والنصارى والمسلمين، فناسب الثلاثةَ: السماوات والأرض وما بينهما. وليس هذا السياق في الحديد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص237–238.","url":""}]},{"id":"s57-54","number":54,"surah":57,"verses":[3],"references":[{"surah":57,"verses":[3]}],"verseLabel":"الحديد: 3","question":"ما دلالة تعريف الصفات وإطلاقها في قوله: ﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ﴾؟","answer":"تعريف الصفات بـ«أل» يفيد القصر، فلا يشاركه أحد في كونه أولًا أو آخرًا أو ظاهرًا أو باطنًا. ولم يقيدها بإضافة ولا وصف ليدل على أنه الأول المطلق والآخر المطلق والظاهر المطلق والباطن المطلق، لا بحسب شيء من الأشياء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص239.","url":""}]},{"id":"s57-55","number":55,"surah":57,"verses":[4],"references":[{"surah":57,"verses":[4]}],"verseLabel":"الحديد: 4","question":"ما سر تقديم العمل على البصر في قوله: ﴿وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ﴾؟","answer":"قدّم العمل لأن السياق في أعمالهم، وقد قال قبله: ﴿وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ﴾، وهو أيضًا تمهيد للأمر بالإنفاق بعده. وعلى هذا جاء قوله في الآية العاشرة: ﴿وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص133–134.","url":""}]},{"id":"s57-56","number":56,"surah":57,"verses":[7,11],"references":[{"surah":57,"verses":[7,11]}],"verseLabel":"الحديد: 7، 11","question":"ما سر وصف الأجر بالكبير في قوله: ﴿فَالَّذِينَ آمَنُوا مِنْكُمْ وَأَنْفَقُوا لَهُمْ أَجْرٌ كَبِيرٌ﴾، وبالكريم في قوله: ﴿فَيُضَاعِفَهُ لَهُ وَلَهُ أَجْرٌ كَرِيمٌ﴾؟","answer":"في الآية الأولى جمع بين الإيمان والإنفاق، فاتسعت الدائرة فوصف الأجر بأنه كبير. وفي الثانية ذكر مضاعفة الأجر، ومن يعطي الكثير على القليل فهو كريم، ومن معاني الكريم الجواد الذي لا ينفد عطاؤه. وفي «لسان العرب» نحو هذا المعنى للكريم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص254–255.","url":""}]},{"id":"s57-57","number":57,"surah":57,"verses":[12],"references":[{"surah":57,"verses":[12]}],"verseLabel":"الحديد: 12","question":"ما دلالة ذكر المؤمنات مع المؤمنين في قوله: ﴿يَوْمَ تَرَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ يَسْعَى نُورُهُمْ﴾؟","answer":"ذكر المؤمنين والمؤمنات، كما ذكر بعد ذلك المنافقين والمنافقات والمصّدّقين والمصّدّقات، لتنال البشرى جميع من آمن، وينال التبكيت جميع من نافق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص255.","url":""}]},{"id":"s57-58","number":58,"surah":57,"verses":[18],"references":[{"surah":57,"verses":[18]}],"verseLabel":"الحديد: 18","question":"ما سر عطف الفعل على الاسم في قوله: ﴿إِنَّ الْمُصَّدِّقِينَ وَالْمُصَّدِّقَاتِ وَأَقْرَضُوا اللَّهَ قَرْضًا حَسَنًا﴾؟","answer":"عبّر عن الصدقة بالاسم ليدل على أنها وصفهم الثابت المتكرر، بخلاف الإقراض فليس ثابتًا ثبوت الصدقة، ولذا لم يرد في القرآن بالصيغة الاسمية «المقرضين». ومن الطريف أن القرض لم يُذكر في القرآن إلا موصوفًا بالحسن ومقيدًا بأنه لله.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص272.","url":""}]},{"id":"s57-59","number":59,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"ما سر قوله: ﴿سَابِقُوا… وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا﴾، وفي آل عمران: ﴿وَسَارِعُوا… عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ﴾؟","answer":"«السماء» هنا أوسع من «السماوات»، والذين آمنوا عامة أوسع دائرة من المتقين، والمسابقة تتضمن المسارعة وزيادة. فلما كانت الجنة لعموم المؤمنين ناسب أن تكون أوسع، وأن يُختم بقوله: ﴿ذَلِكَ فَضْلُ اللَّهِ﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص43–44.","url":""}]},{"id":"s57-60","number":60,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"ما سر قوله: ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ﴾ بالتفصيل، وفي التغابن: ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ﴾؟","answer":"سياق الحديد في تفصيل أحوال الدنيا والآخرة، فناسبه تفصيل مواضع المصيبة في الأرض وفي الأنفس، ولم يكن السياق في التغابن كذلك فأُجمل. وفي «البرهان» للكرماني نحو هذا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص116–117.","url":""}]},{"id":"s58-1","number":1,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"ماذا تفيد ﴿قَدْ﴾ في افتتاح السورة: ﴿قَدْ سَمِعَ اللَّهُ﴾؟","answer":"تحقق وقوع السماع وتؤكد أن شكوى المرأة قد بلغت ربها وأجيب عنها، فتفتتح السورة بتطمين المظلوم أن صوته لم يضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص402، تحت عنوان «دلالة ﴿قد﴾ في ﴿قد سمع الله﴾»","url":""}]},{"id":"s58-28","number":28,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا افتتحت السورة بسماع الله للشكوى لا بمجرد علمه بها؟","answer":"لأن السماع يستحضر قرب الإجابة والعناية بالكلام المرفوع، وهو أبلغ في تسلية المشتكية من الإخبار المجرد بأن الله يعلم حالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص402، تحت عنوان «بلاغة المجاز في لفظ السماع»","url":""}]},{"id":"s58-2","number":2,"surah":58,"verses":[6,7],"references":[{"surah":58,"verses":[6,7]}],"verseLabel":"المجادلة: 6–7","question":"لماذا عُطف الإنباء بالأعمال أولًا بالفاء في ﴿فَيُنَبِّئُهُمْ﴾؟","answer":"للدلالة على سرعة مواجهتهم بأعمالهم عند البعث، فلا فاصل يضيع فيه شيء مما أحصاه الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص461، تحت عنوان «دلالة العطف بالفاء في ﴿فينبئهم﴾»","url":""}]},{"id":"s58-29","number":29,"surah":58,"verses":[6,7],"references":[{"surah":58,"verses":[6,7]}],"verseLabel":"المجادلة: 6–7","question":"لماذا عُطف الإنباء بالأعمال لاحقًا بـ﴿ثُمَّ﴾؟","answer":"لتصوير تراخي زمن الجزاء عن زمن النجوى والفعل، ثم حتمية الانتقال بعد المهلة إلى الإنباء والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص479، تحت عنوان «سر العطف بـ﴿ثم﴾»","url":""}]},{"id":"s58-3","number":3,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"لماذا خُصت نجوى الثلاثة والخمسة بالذكر؟","answer":"لأن الثلاثة أول عدد تتحقق فيه النجوى الجماعية، والخمسة تالية له من الأعداد الفردية التي يكثر اجتماع الناس عليها؛ وذكرهما مثالان يشملان ما بينهما وما بعدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص476، تحت عنوان «سر تخصيص الثلاثة والخمسة بالذكر»","url":""}]},{"id":"s58-30","number":30,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ماذا يضيف قوله: ﴿وَلَا أَدْنَى مِنْ ذَلِكَ وَلَا أَكْثَرَ﴾ بعد الثلاثة والخمسة؟","answer":"يرفع توهم الاختصاص بالعددين ويعم كل اجتماع، صغيرًا كان أو كبيرًا، تحت علم الله ومعيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص477، تحت عنوان «بلاغة عطف ﴿ولا أكثر﴾»","url":""}]},{"id":"s58-4","number":4,"surah":58,"verses":[12,13],"references":[{"surah":58,"verses":[12,13]}],"verseLabel":"المجادلة: 12–13","question":"لماذا قيل في العجز عن صدقة النجوى: ﴿فَإِنْ لَمْ تَجِدُوا﴾ بـ﴿إن﴾؟","answer":"لأن عدم الوجدان أمر محتمل لا واقع في كل مخاطب، فناسبته أداة الشرط التي لا تجزم بوقوع الحالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص552، تحت عنوان «علة إيثار (إن) على (إذا)»","url":""}]},{"id":"s58-31","number":31,"surah":58,"verses":[12,13],"references":[{"surah":58,"verses":[12,13]}],"verseLabel":"المجادلة: 12–13","question":"لماذا قيل بعد ذلك: ﴿فَإِذْ لَمْ تَفْعَلُوا﴾ بـ﴿إذ﴾؟","answer":"لأن تركهم تقديم الصدقة صار أمرًا واقعًا معلومًا، فجيء بـ﴿إذ﴾ التي تستحضر الحدث المتحقق وتبني عليه رفع الحكم والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص558، تحت عنوان «دلالة (إذ) في ﴿فإذ لم تفعلوا﴾»","url":""}]},{"id":"s58-5","number":5,"surah":58,"verses":[12],"references":[{"surah":58,"verses":[12]}],"verseLabel":"المجادلة: 12","question":"لماذا أُشير إلى صدقة النجوى باسم البعيد في ﴿ذَلِكَ خَيْرٌ لَكُمْ﴾؟","answer":"لتعظيم شأن هذا الأدب ورفع منزلته، مع أنه ذُكر قريبًا؛ فالبعد هنا بعد رتبة لا بعد مسافة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص550، تحت عنوان «نكتة إيثار اسم الإشارة للبعيد ﴿ذلك﴾»","url":""}]},{"id":"s58-32","number":32,"surah":58,"verses":[12],"references":[{"surah":58,"verses":[12]}],"verseLabel":"المجادلة: 12","question":"لماذا وُصفت صدقة النجوى بأنها ﴿خَيْرٌ لَكُمْ﴾؟","answer":"لأنها تطهر القلوب من الشح، وتميز حاجة المناجي الصادقة، وتدفع التزاحم على الرسول ﷺ؛ فهي خير ديني واجتماعي للمخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص550، تحت عنوان «نكتة التعبير بالخيرية»","url":""}]},{"id":"s58-6","number":6,"surah":58,"verses":[22],"references":[{"surah":58,"verses":[22]}],"verseLabel":"المجادلة: 22","question":"لماذا عُطف إدخال الجنات على الإيمان والتأييد في ﴿وَيُدْخِلُهُمْ جَنَّاتٍ﴾؟","answer":"ليبين ثمرة ما أودع في قلوبهم من الإيمان وما أيدوا به من روح: جزاء أخروي يتمثل في دخول الجنات ودوام النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص635–636، تحت عنوان «نكتة عطف ﴿ويدخلهم جنات﴾»","url":""}]},{"id":"s58-33","number":33,"surah":58,"verses":[22],"references":[{"surah":58,"verses":[22]}],"verseLabel":"المجادلة: 22","question":"لماذا جاء إدخالهم الجنات بالمضارع في ﴿وَيُدْخِلُهُمْ﴾؟","answer":"لاستحضار الوعد كأنه يقع أمام السامع، وللدلالة على تجدد دخول أفواج المؤمنين إلى الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص636، تحت عنوان «بلاغة التعبير بالمضارع في ﴿ويدخلهم﴾»","url":""}]},{"id":"s58-7","number":7,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"ماذا تفيد ﴿فِي﴾ في قول المرأة: ﴿تُجَادِلُكَ فِي زَوْجِهَا﴾؟","answer":"تجعل الزوج وقضيته موضوع المحاورة، فهي لا تجادل خصومة معه بل تبحث في الحكم المتعلق بعلاقتها به.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص404، تحت عنوان «معنى ﴿في﴾ من قوله: ﴿في زوجها﴾»","url":""}]},{"id":"s58-34","number":34,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا قيل: ﴿وَتَشْتَكِي إِلَى اللَّهِ﴾ بـ﴿إلى﴾؟","answer":"لأن الشكوى متجهة إلى الله طلبًا للفرج والحكم، فالحرف يصور انتهاء حاجتها ورجائها إلى من يملك كشفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص406، تحت عنوان «دلالة ﴿إلى﴾ في ﴿إلى الله﴾»","url":""}]},{"id":"s58-8","number":8,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"ماذا تضيف صيغة التفاعل في ﴿تَحَاوُرَكُمَا﴾؟","answer":"تصور مراجعة الكلام بين المرأة والنبي ﷺ أخذًا وردًا، لا كلام طرف واحد؛ وفيها عناية الله بكل تفاصيل الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص408، تحت عنوان «نكتة صيغة التفاعل في ﴿تحاوركما﴾»","url":""}]},{"id":"s58-35","number":35,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا جاء سماع الله لحوارهما بالمضارع في ﴿يَسْمَعُ﴾؟","answer":"ليدل على استمرار إحاطته بكل ما يتجدد من كلامهما، وليستحضر السامع قرب العناية الإلهية أثناء الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص408، تحت عنوان «بلاغة التعبير بالمضارع في ﴿يسمع﴾»","url":""}]},{"id":"s58-9","number":9,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا جُمع بين اسمي الله ﴿سَمِيعٌ بَصِيرٌ﴾ في ختام آية الشكوى؟","answer":"ليقرر إحاطته بالكلام المسموع والحال المشاهد معًا؛ فقد سمع حوارها ورأى ما نزل بها، فلا يغيب عنه قول ولا حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص409، تحت عنوان «نكتة الجمع بين السمع والبصر»","url":""}]},{"id":"s58-36","number":36,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا قُدِّم ﴿سَمِيعٌ﴾ على ﴿بَصِيرٌ﴾؟","answer":"لأن محور الآية شكوى منطوقة وحوار مسموع، فقدم الوصف الأنسب للسياق ثم ضم إليه البصر لتكتمل الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص409، تحت عنوان «غرض تقديم السمع على البصر»","url":""}]},{"id":"s58-10","number":10,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"ما بلاغة نفي الأمومة في قوله: ﴿مَا هُنَّ أُمَّهَاتِهِمْ﴾؟","answer":"ينفي التشبيه الذي توهمه الظهار من أصله؛ فقول الرجل لا يحول الزوجة إلى أم، وبطلان المشبه به يهدم الحكم المتوهم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص418، تحت عنوان «بلاغة التشبيه المنفي في ﴿ما هن أمهاتهم﴾»","url":""}]},{"id":"s58-11","number":11,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"لماذا حُصرت الأمومة في قوله: ﴿إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ﴾؟","answer":"لقطع كل ادعاء لفظي يجعل الزوجة أمًا؛ فالأمومة حقيقة ثابتة بالولادة لا تنشأ بكلمة ظهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص419، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s58-12","number":12,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"لماذا نُكِّر ﴿مُنْكَرًا﴾ في وصف الظهار؟","answer":"لتعظيم فظاعة هذا القول وبيان أنه منكر عظيم تنفر منه الفطرة والشرع، لا مجرد عبارة غير مستحسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص421، تحت عنوان «بلاغة إيثار لفظ (المنكر) بصيغة التنكير»","url":""}]},{"id":"s58-37","number":37,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"ماذا يضيف وصف الظهار بأنه ﴿زُورًا﴾ بعد كونه منكرًا؟","answer":"يبين أنه لا يجمع القبح فقط، بل الكذب أيضًا؛ فالزوجة ليست أمًا في الحقيقة، فاجتمع فساد القيمة وبطلان الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص422، تحت عنوان «بلاغة عطف ﴿وزورًا﴾»","url":""}]},{"id":"s58-13","number":13,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"لماذا أعقب ذم الظهار بقوله: ﴿وَإِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ﴾؟","answer":"ليفتح باب التوبة بعد بيان فظاعة القول، ويطمئن من زلّ ثم رجع أن التشريع لا يقصد اليأس بل الإصلاح والتطهير.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص422–423، تحت عنوان «بلاغة عطف جملة ﴿وإن الله لعفو غفور﴾»","url":""}]},{"id":"s58-14","number":14,"surah":58,"verses":[3],"references":[{"surah":58,"verses":[3]}],"verseLabel":"المجادلة: 3","question":"لماذا عُطف الرجوع في الظهار بـ﴿ثُمَّ﴾ في ﴿ثُمَّ يَعُودُونَ﴾؟","answer":"لأن العودة تقع بعد مهلة من قول الظهار، وللتنبيه إلى استبعاد أن يرجع المرء إلى ما حرمه على نفسه بعد هذا القول الشنيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص430–431، تحت عنوان «سر العطف بـ﴿ثم﴾ في ﴿ثم يعودون﴾»","url":""}]},{"id":"s58-38","number":38,"surah":58,"verses":[3],"references":[{"surah":58,"verses":[3]}],"verseLabel":"المجادلة: 3","question":"لماذا عُبِّر عن إرادة استئناف الحياة الزوجية بلفظ ﴿يَعُودُونَ﴾؟","answer":"استعير العود للرجوع إلى المعاشرة التي قطعها الظهار؛ فكأن العلاقة كانت طريقًا تركه ثم أراد العودة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص431، تحت عنوان «بلاغة المجاز في لفظ العود»","url":""}]},{"id":"s58-15","number":15,"surah":58,"verses":[3,4],"references":[{"surah":58,"verses":[3,4]}],"verseLabel":"المجادلة: 3–4","question":"لماذا تكرر قيد ﴿مِنْ قَبْلِ أَنْ يَتَمَاسَّا﴾ في العتق والصيام؟","answer":"لتأكيد أن الكفارة مانع واجب قبل استئناف المعاشرة، وتكراره مع البدلين يمنع توهم اختلاف ترتيب الحكم بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص442، تحت عنوان «سر تكرار ﴿من قبل أن يتماسا﴾»","url":""}]},{"id":"s58-39","number":39,"surah":58,"verses":[3,4],"references":[{"surah":58,"verses":[3,4]}],"verseLabel":"المجادلة: 3–4","question":"لماذا لم يُذكر ﴿مِنْ قَبْلِ أَنْ يَتَمَاسَّا﴾ مع الإطعام؟","answer":"لأن الإطعام بديل عند العجز عن الصيام، وقد ثبت ترتيب المنع قبلُ في الأصل وبدله الأول؛ فحذفه هنا اتكال على ما تقدم وتخفيف في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص443، تحت عنوان «سر عدم ذكر ﴿من قبل أن يتماسا﴾ مع الإطعام»","url":""}]},{"id":"s58-16","number":16,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"لماذا قيل: ﴿يُحَادُّونَ اللَّهَ وَرَسُولَهُ﴾ دون «يعادون»؟","answer":"لأن المحادة تصور كل فريق في حد منفصل مقابل حد الآخر، فتجسد شدة المخالفة والانفصال عن منهج الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص453، تحت عنوان «سر التعبير بالمحادة دون غيرها»","url":""}]},{"id":"s58-40","number":40,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"لماذا جاءت محادة الله ورسوله بالمضارع في ﴿يُحَادُّونَ﴾؟","answer":"لتصوير المخالفة سلوكًا متجددًا مستمرًا، لا موقفًا وقع وانتهى؛ فهم يكررون الوقوف في جانب الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص453، تحت عنوان «دلالة صيغة المضارع في ﴿يحادون﴾»","url":""}]},{"id":"s58-17","number":17,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"لماذا عُبِّر عن هزيمة المحادين بقوله: ﴿كُبِتُوا﴾؟","answer":"لأن الكبت يجمع الإذلال والقهر ورد المعتدي بغيظه، فيصور سقوط قوتهم النفسية والظاهرة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص454، تحت عنوان «بلاغة التعبير بالكبت»","url":""}]},{"id":"s58-41","number":41,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"ماذا يضيف تشبيههم بالذين من قبلهم في ﴿كَمَا كُبِتَ الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"يجعل مصيرهم سنة تاريخية مشاهدة؛ فكما أذل السابقون بسبب المحادة، يلحق اللاحقون بهم بلا استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص454–455، تحت عنوان «دلالة التشبيه بالكاف»","url":""}]},{"id":"s58-18","number":18,"surah":58,"verses":[6],"references":[{"surah":58,"verses":[6]}],"verseLabel":"المجادلة: 6","question":"لماذا عُبِّر عن حفظ الأعمال بقوله: ﴿أَحْصَاهُ اللَّهُ﴾؟","answer":"شُبه علم الله المحيط بأعمالهم بإحصاء دقيق لا يفوته عدد ولا تفصيل، فيوقن السامع أن كل صغيرة محفوظة للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص463، تحت عنوان «بلاغة المجاز بلفظ الإحصاء»","url":""}]},{"id":"s58-42","number":42,"surah":58,"verses":[6],"references":[{"surah":58,"verses":[6]}],"verseLabel":"المجادلة: 6","question":"ما دلالة الجمع بين ﴿أَحْصَاهُ اللَّهُ﴾ و﴿نَسُوهُ﴾؟","answer":"تقيم مقابلة بين ضعف ذاكرة البشر وكمال علم الله: ما أسقطوه من حسابهم بقي محفوظًا عنده وسيواجهون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص464، تحت عنوان «دلالة الواو في ﴿ونسوه﴾»","url":""}]},{"id":"s58-19","number":19,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ما معنى أن الله ﴿رَابِعُهُمْ﴾ و﴿سَادِسُهُمْ﴾ في النجوى؟","answer":"ليس دخوله في عدد أجسامهم، بل إحاطة علمه وسمعه بسرهم؛ فكل مجموعة يزيد عليها علم الله الحاضر الذي لا يخفى عليه حديثها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص475، تحت عنوان «توجيه كونه تعالى ﴿رابعهم﴾ و﴿سادسهم﴾»","url":""}]},{"id":"s58-43","number":43,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ماذا يفيد قوله: ﴿أَيْنَ مَا كَانُوا﴾ بعد إثبات معية الله؟","answer":"يعم كل مكان يمكن أن يختبئوا فيه، فيقطع وهم أن البعد أو الخفاء يحجب نجواهم عن علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص478، تحت عنوان «فائدة الظرف ﴿أين﴾»","url":""}]},{"id":"s58-20","number":20,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"ما سرّ التعبير في قول ﴿ثُمَّ يَعُودُونَ لِمَا نُهُوا عَنْهُ﴾ بالمضارع؟","answer":"المضارع يصور العودة عادة متجددة، فلا يعرضها على أنها مخالفة عارضة انقضت. وفي استحضار المشهد تعجيب من قلة اكتراثهم بالنهي وإصرارهم على ما يفسد الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص489، تحت عنوان «سر التعبير بالمضارع في ﴿يعودون﴾»","url":""}]},{"id":"s58-21","number":21,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"لماذا وُصفت نجواهم أولًا بأنها ﴿بِالْإِثْمِ﴾؟","answer":"لأن الإثم اسم جامع للذنب الذي يضر صاحبه، فبدأ به ليقرر فساد أصل حديثهم وسوء طويتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص492، تحت عنوان «نكتة التعبير بالإثم»","url":""}]},{"id":"s58-44","number":44,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"ماذا يضيف ﴿الْعُدْوَانِ﴾ بعد ﴿الْإِثْمِ﴾ في وصف النجوى؟","answer":"ينقل الذم من ذنب يعود ضرره عليهم إلى اعتداء يتجاوزهم فيؤذي الآخرين؛ فنجواهم فساد شخصي واجتماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص492–493، تحت عنوان «نكتة عطف العدوان على الإثم»","url":""}]},{"id":"s58-45","number":45,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"لماذا خُصت ﴿مَعْصِيَتِ الرَّسُولِ﴾ بعد الإثم والعدوان؟","answer":"لأنها أغلظ صور نجواهم وأشدها خطرًا على الجماعة، وفي تخصيصها تشنيع على تدبيرهم ما يخالف أمر الرسول ﷺ ويؤذيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص493، تحت عنوان «نكتة عطف ﴿ومعصيت الرسول﴾»","url":""}]},{"id":"s58-22","number":22,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"كيف سمّى القرآن قول اليهود المؤذي للنبي ﷺ تحية؟","answer":"سمّاه تحية على سبيل كشف المفارقة والتهكم؛ فقد حرّفوا السلام إلى لفظ يوهم التحية ويضمر الدعاء بالموت، ففضح التعبير سوءهم مع إبقاء صورة الفعل الذي تظاهروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص495، تحت عنوان «نكتة التعبير بالتحية»","url":""}]},{"id":"s58-46","number":46,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"ماذا يفضح قوله ﴿بِمَا لَمْ يُحَيِّكَ بِهِ اللَّهُ﴾؟","answer":"يفضح أن تحيتهم لم تكن مجرد إساءة اجتماعية، بل مخالفة متعمدة لأدب شرعه الله وأمر به؛ فمن تجاوز التحية التي رضيها الله عرّض نفسه لسخطه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص495–496، تحت عنوان «دلالة التعبير بالموصول وصلته في قوله: ﴿بما لم يحيك﴾»","url":""}]},{"id":"s58-23","number":23,"surah":58,"verses":[9],"references":[{"surah":58,"verses":[9]}],"verseLabel":"المجادلة: 9","question":"لماذا لم يكتف بالنهي عن نجوى الإثم، بل أمر بالنجوى بالبر والتقوى؟","answer":"لأن إصلاح المجتمع لا يكتمل بترك التآمر والعدوان، بل يحتاج أن تتحول المجالس الخفية نفسها إلى تشاور في الخير والإصلاح؛ فجمع السياق إزالة الشر وبناء البديل النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص511، تحت عنوان «نكتة عطف ﴿وتناجوا بالبر والتقوى﴾»","url":""}]},{"id":"s58-47","number":47,"surah":58,"verses":[9],"references":[{"surah":58,"verses":[9]}],"verseLabel":"المجادلة: 9","question":"ماذا تضيف ﴿التَّقْوَى﴾ بعد الأمر بالتناجي بالبر؟","answer":"البر يشمل وجوه الخير الواسعة التي تنفع الناس، والتقوى تضيف رقابة القلب وخشيته لله؛ فيجتمع صلاح العمل الظاهر مع الدافع الباطن الذي يحفظه من الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص512، تحت عنوان «نكتة عطف التقوى على البر»","url":""}]},{"id":"s58-24","number":24,"surah":58,"verses":[10],"references":[{"surah":58,"verses":[10]}],"verseLabel":"المجادلة: 10","question":"هل قوله ﴿إِنَّمَا النَّجْوَى مِنَ الشَّيْطَانِ﴾ يذم كل حديث سري؟","answer":"لا؛ التعريف يشير إلى النجوى المعهودة في السياق، وهي التناجي بالإثم والعدوان ومعصية الرسول. أما التشاور في الخير فمأمور به، وإنما ينسب إلى الشيطان ما كان وسيلة للشر والإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص518، تحت عنوان «دلالة تعريف ﴿النجوى﴾»","url":""}]},{"id":"s58-48","number":48,"surah":58,"verses":[10],"references":[{"surah":58,"verses":[10]}],"verseLabel":"المجادلة: 10","question":"لماذا خُصَّ حزن المؤمنين غايةً للنجوى الشيطانية؟","answer":"لأن المتناجين قد لا يملكون إيقاع ضرر حقيقي، فيلجؤون إلى الإيهام والهمس ليوقعوا الريبة والخوف في قلوب المؤمنين؛ ففضح القرآن غايتهم النفسية حتى لا تستولي الحيلة على النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص519، تحت عنوان «سر تخصيص علة الحزن بالذكر»","url":""}]},{"id":"s58-49","number":49,"surah":58,"verses":[10],"references":[{"surah":58,"verses":[10]}],"verseLabel":"المجادلة: 10","question":"ماذا يقرر قوله إن النجوى لا تضر المؤمنين ﴿إِلَّا بِإِذْنِ اللَّهِ﴾؟","answer":"يقرر أن كيدها لا يستقل بإحداث شيء، وأن الضرر لا يقع في حال إلا بتقدير الله؛ فيقطع سلطان الوهم، ويدعو المؤمن إلى التوكل بدل الاستسلام للخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص521، تحت عنوان «بلاغة الحصر بالنفي والاستثناء»","url":""}]},{"id":"s58-25","number":25,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ماذا يطلب الأمر ﴿تَفَسَّحُوا فِي الْمَجَالِسِ﴾ وراء مجرد تحريك الأجساد؟","answer":"يطلب أن يتعمد المؤمن توسيع المكان لإخوانه بسماحة وكرم، فيزول التزاحم والضيق وتظهر المودة؛ فاللفظ يصور فسحة في الصدر قبل فسحة المجلس.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص532–533، تحت عنوان «بلاغة التعبير بالتفسح»","url":""}]},{"id":"s58-50","number":50,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"لماذا عبّر عن القيام من المجلس بقوله ﴿انْشُزُوا﴾؟","answer":"لأن النشوز يدل على الارتفاع من موضع مستقر؛ فيحث على سرعة الاستجابة إذا دعت الحاجة إلى القيام، ويحوّل التنازل عن المكان إلى طاعة ترفع صاحبها عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص536، تحت عنوان «سر التعبير بالنشوز»","url":""}]},{"id":"s58-26","number":26,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ما الصورة في قوله ﴿يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا﴾؟","answer":"يصوّر علو المنزلة والكرامة كأنه ارتفاع حسي تراه العين؛ فمن ارتفع عن مكانه امتثالًا وتواضعًا رفعه الله في القدر والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص536–537، تحت عنوان «بلاغة الاستعارة في قوله: ﴿يرفع﴾»","url":""}]},{"id":"s58-51","number":51,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"لماذا خُصَّ الذين أوتوا العلم بعد ذكر المؤمنين؟","answer":"لأن العلماء داخلون في المؤمنين، ثم خُصوا بالذكر تشريفًا وبيانًا لزيادة منزلتهم؛ فالإيمان يرفع، والعلم المصحوب به يفتح درجة أخرى من الفضل والعمل والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص538، تحت عنوان «بلاغة عطف ﴿والذين أوتوا العلم﴾»","url":""}]},{"id":"s58-52","number":52,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ماذا يوحي جمع ﴿دَرَجَاتٍ﴾ وتنكيرها؟","answer":"يوحي بمراتب كثيرة عالية لا يحيط السامع بمقدارها، تتفاوت بحسب الإيمان والعلم والعمل؛ فالتنكير يعظمها والجمع يوسعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص540، تحت عنوان «غرض تنكير لفظ ﴿درجات﴾ وجمعه»","url":""}]},{"id":"s58-27","number":27,"surah":58,"verses":[19],"references":[{"surah":58,"verses":[19]}],"verseLabel":"المجادلة: 19","question":"ما النتيجة الأخطر لاستحواذ الشيطان عليهم في قوله ﴿فَأَنْسَاهُمْ ذِكْرَ اللَّهِ﴾؟","answer":"أن سيطرته لم تقف عند وسوسة عابرة، بل انتهت إلى طمس ذكر الله من قلوبهم وعقولهم؛ فالفاء تكشف أن الغفلة ثمرة مباشرة للتمادي في طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص609، تحت عنوان «دلالة الفاء في ﴿فأنساهم﴾»","url":""}]},{"id":"s58-53","number":53,"surah":58,"verses":[19],"references":[{"surah":58,"verses":[19]}],"verseLabel":"المجادلة: 19","question":"لماذا سُمّي المنافقون ﴿حِزْبَ الشَّيْطَانِ﴾؟","answer":"لأن الحزب جماعة يجمعها قائد وغاية، وقد وحّدهم اتباع الشيطان ونصرة الباطل حتى صاروا كجنوده المنظمين؛ والاسم يفضح ولاءهم الحقيقي ومصيرهم معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص611، تحت عنوان «بلاغة التعبير بالحزب»","url":""}]},{"id":"s58-54","number":54,"surah":58,"verses":[19],"references":[{"surah":58,"verses":[19]}],"verseLabel":"المجادلة: 19","question":"لماذا صُوِّر مصير حزب الشيطان بالخسران؟","answer":"لأن الخسران في أصله ضياع رأس المال بعد انتظار الربح؛ وهؤلاء أضاعوا فطرتهم وأعمارهم ودينهم، فلم يفقدوا ربحًا عارضًا فحسب بل خسروا الأصل والمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص613، تحت عنوان «بلاغة الاستعارة في لفظ الخسران»","url":""}]},{"id":"s58-55","number":55,"surah":58,"verses":[3],"references":[{"surah":58,"verses":[3]}],"verseLabel":"المجادلة: 3","question":"ما سر الجمع في قوله: ﴿ذَلِكُمْ تُوعَظُونَ بِهِ﴾، والإفراد في البقرة: ﴿ذَلِكَ يُوعَظُ بِهِ﴾، والخطاب للجميع في الموضعين؟","answer":"الوعظ في المجادلة أشد وآكد؛ لأنه في حكم الظهار الذي وصفه بأنه ﴿مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا﴾، وطلب من قائله تحرير رقبة أو صيام شهرين متتابعين أو إطعام ستين مسكينًا، بخلاف سياق الطلاق في البقرة. فجاء بمطابقة الجمع في الموطن المؤكد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص102–103.","url":""}]},{"id":"s58-56","number":56,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"ما سر النفي بـ«ما» ثم بـ«إِن» في قوله تعالى: ﴿مَا هُنَّ أُمَّهَاتِهِمْ إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ﴾؟","answer":"«إِن» آكد من «ما» في النفي، وتُستعمل كثيرًا في الإنكار. فلما أراد الإنكار على المظاهرين وأن يرجعهم إلى حقيقة كأنهم جهلوها جاء بـ«إِن» في الجملة الثانية، كما في قول النسوة: ﴿مَا هَذَا بَشَرًا إِنْ هَذَا إِلَّا مَلَكٌ كَرِيمٌ﴾.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص257–258.","url":""}]},{"id":"s58-57","number":57,"surah":58,"verses":[6,7],"references":[{"surah":58,"verses":[6,7]}],"verseLabel":"المجادلة: 6–7","question":"ما سر العطف بالفاء في قوله: ﴿يَوْمَ يَبْعَثُهُمُ اللَّهُ جَمِيعًا فَيُنَبِّئُهُمْ﴾، وبـ«ثم» في الآية التالية: ﴿ثُمَّ يُنَبِّئُهُمْ بِمَا عَمِلُوا يَوْمَ الْقِيَامَةِ﴾؟","answer":"الآية الأولى في يوم القيامة، بدليل ﴿يَوْمَ يَبْعَثُهُمُ اللَّهُ﴾، فالتنبئة قريبة فجاء بالفاء التي تدل على الترتيب والتعقيب. والثانية في الدنيا وتناجي أهلها، والتنبئة إنما تكون يوم القيامة وهو متراخٍ عن الدنيا، فجاء بـ«ثم» التي تدل على الترتيب والتراخي.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص104.","url":""}]},{"id":"s58-58","number":58,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ما سر تكرار «ما» في قوله: ﴿أَلَمْ تَرَ أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾، ولم تُكرر في العنكبوت: ﴿يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"آية المجادلة موطن إحاطة وتفصيل، فقد ذكرت أنه لا يغيب عنه مجلس قلّ أو كثر، ثم ينبئ أهله بكل ما تناجوا به، أحصاه الله ونسوه. فلما فصّل أعاد «ما»، ولما أجمل في العنكبوت أجمل في ذكر الموصول.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص97.","url":""}]},{"id":"s58-59","number":59,"surah":58,"verses":[8,9],"references":[{"surah":58,"verses":[8,9]}],"verseLabel":"المجادلة: 8–9","question":"ما دلالة الجمع بين الإثم والعدوان والمعصية في قوله: ﴿وَيَتَنَاجَوْنَ بِالْإِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُولِ﴾؟","answer":"الإثم عموم الذنب تعلّق بالغير أو لم يتعلق، والعدوان الظلم وهو إنما يتعلق بالغير. ولم ترد «المعصية» في القرآن إلا في هاتين الآيتين مخصوصة بمعصية الرسول، أما «العصيان» فاستُعمل عامًا في قوله: ﴿وَكَرَّهَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص17–18.","url":""}]},{"id":"s58-60","number":60,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ما دلالة بناء الفعل للمجهول في قوله: ﴿إِذَا قِيلَ لَكُمْ تَفَسَّحُوا فِي الْمَجَالِسِ﴾؟","answer":"حُذف الفاعل لأنه لا يتعلق بذكره غرض؛ إذ ليس المقصود إسناد القول إلى فاعل مخصوص، بل إلى أي فاعل كان، فالأمر بالتفسح لازم أيًا كان الآمر. وهذا التوجيه منقول عن «التصريح».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص72.","url":""}]},{"id":"s58-61","number":61,"surah":58,"verses":[12],"references":[{"surah":58,"verses":[12]}],"verseLabel":"المجادلة: 12","question":"ما سر الإفراد في قوله: ﴿ذَلِكَ خَيْرٌ لَكُمْ وَأَطْهَرُ﴾، وفي البقرة: ﴿ذَلِكُمْ أَزْكَى لَكُمْ وَأَطْهَرُ﴾، وفي الصف: ﴿ذَلِكُمْ خَيْرٌ لَكُمْ﴾؟","answer":"آية المجادلة في تقديم صدقة عند مناجاة الرسول، وهو حكم يخص الأغنياء الذين يناجونه، وقد نُسخ وشيكًا بالآية التي بعدها. أما آية البقرة ففي تزكية القلوب بحكم خالد، وآية الصف في الجهاد والخطاب فيها لعموم المؤمنين إلى يوم القيامة، فجمع في المقام الآكد والأعم وأفرد هنا.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص103–104؛ وعلى طريق التفسير البياني، ج1، ص228.","url":""}]},{"id":"s59-1","number":1,"surah":59,"verses":[1],"references":[{"surah":59,"verses":[1]}],"verseLabel":"الحشر: 1","question":"ما سر تكرار «ما» في ﴿سبح لله ما في السماوات وما في الأرض﴾ في الحشر، بخلاف مطلع الحديد؟","answer":"في الحديد جُمعت الموجودات تحت موصول واحد لأن المقام للاستدلال بعموم الخلق على عظمة الله وصفاته. أما الحشر فتمهد لنعمة أرضية هي خذلان بني النضير، فخُص أهل الأرض بموصول ثانٍ لإبراز شأن هذه النعمة، مع شمول التسبيح للسماوات والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص661–662، تحت عنوان «توجيه المتشابه اللفظي بين مطلعي سورة الحشر وسورة الحديد»","url":""}]},{"id":"s59-2","number":2,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ما سرّ التعبير في قول ﴿هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا﴾ ولم يسم بني النضير؟","answer":"عدل عن اسم بني النضير إلى الموصول وصلته لتشنيع صنيعهم وتسجيل وصف الكفر عليهم، والإيماء إلى أنه باعث الغدر والخيانة وسبب استحقاق الإخراج؛ فالتعبير يربط مصيرهم بعملهم، لا بمجرد انتسابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص666، تحت عنوان «نكتة التعبير عن المفعول بالاسم الموصول»","url":""}]},{"id":"s59-3","number":3,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"لماذا قيل عن إخراج بني النضير: ﴿لِأَوَّلِ الْحَشْرِ﴾؟","answer":"لأنه كان أول إخراج جماعي لهم من جزيرة العرب، وفي وصفه بالأول إشعار بأن وراءه حشرًا آخر؛ فالكلمة لا تسجل الواقعة وحدها، بل تفتح أفق ما سيأتي بعدها من إجلاء وحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص669، تحت عنوان «وجه التعبير بقوله: ﴿أول﴾»","url":""}]},{"id":"s59-4","number":4,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ماذا تكشف مقابلة ظن المؤمنين بظن بني النضير في مطلع مشهد إخراجهم؟","answer":"تكشف انقلاب الموازين الذي أحدثه نصر الله: المؤمنون استبعدوا خروجهم لقوة حصونهم، وهم جزموا أن الحصون ستحميهم؛ ثم أبطل الواقع الظنين معًا، فظهر أن التقدير الإلهي يأتي من وراء حساب الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص672، تحت عنوان «بلاغة الطباق بين فعلي الظن»","url":""}]},{"id":"s59-5","number":5,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ماذا يضيف نفي الاحتساب في قوله: ﴿فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا﴾؟","answer":"يصور مباغتة التدبير الإلهي لهم من جهة لم تدخل أصلًا في حسابهم؛ فقد حصّنوا ما توقعوا أن يأتيهم منه الخطر، فجاء انهيارهم من داخل النفوس حين قذف الله الرعب في قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص677، تحت عنوان «دلالة التعبير بفعل الاحتساب منفيًا»","url":""}]},{"id":"s59-23","number":23,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ما الصورة التي يرسمها قوله: ﴿فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا﴾؟","answer":"يمثل حال نزول أمر الله وعقابه بهم بحال قوة تأتي المحاصَر من منفذ لم يراقبه، فتجاوز التعبير ذكر السبب المباشر إلى تصوير المفاجأة والإحاطة والعجز عن دفع القضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص678، تحت عنوان «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s59-6","number":6,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"لماذا قيل: ﴿يُخْرِبُونَ بُيُوتَهُمْ﴾ لا يهدمونها؟","answer":"لأن التخريب أوسع دلالة من مجرد إسقاط البناء؛ فهو إفساد للعمران وإخراج له عن الانتفاع، ويصور أنهم شاركوا بأيديهم في تحويل حصون ظنوها مصدر أمن إلى بيوت معطلة مهدمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص681، تحت عنوان «بلاغة استعمال مفردة ﴿يخربون﴾»","url":""}]},{"id":"s59-24","number":24,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ماذا يكشف جمع ﴿بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ﴾ في تخريب البيوت؟","answer":"يكشف اشتراك الفريقين في النتيجة مع اختلاف القصد: كان اليهود ينقضون ما يمكن حمله أو يحرمون المسلمين الانتفاع به، وكان المؤمنون يفتحون الحصون ويزيلون موانعها؛ فاجتمعت الأيدي على إسقاط ما عُدَّ سببًا للمنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص684، تحت عنوان «بلاغة العطف بالواو»","url":""}]},{"id":"s59-7","number":7,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"لماذا قيل: ﴿فَاعْتَبِرُوا﴾ ولم يقل: فاتعظوا؟","answer":"لأن الاعتبار عبور من الواقعة المشاهدة إلى حكم يتجاوزها؛ فيقيس الناظر أحواله على مصير من اغتروا بقوتهم، أما الاتعاظ فقد يقف عند التأثر العابر. فالمطلوب قراءة السنن لا مجرد الانفعال بالمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص685، تحت عنوان «بلاغة استعمال مفردة الاعتبار دون الاتعاظ»","url":""}]},{"id":"s59-8","number":8,"surah":59,"verses":[3],"references":[{"surah":59,"verses":[3]}],"verseLabel":"الحشر: 3","question":"ما دلالة مقابلة العذاب في الدنيا بعذاب النار في الآخرة في الحشر: 3؟","answer":"المقابلة تبين أن عقابهم لا ينحصر في الدنيا. فجملة ﴿ولهم في الآخرة عذاب النار﴾ تحتاط من توهم أن الجلاء أو التعذيب الدنيوي بدل من عذاب الآخرة، وذكر النار يزيد تصوير شدته؛ فلكل من الدارين عذابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص697، تحت عنوان «بلاغة الطباق بين ﴿الدنيا﴾ و﴿الآخرة﴾»","url":""}]},{"id":"s59-9","number":9,"surah":59,"verses":[4],"references":[{"surah":59,"verses":[4]}],"verseLabel":"الحشر: 4","question":"ما دلالة التعبير بالمضارع في قوله ﴿ومن يشاق الله فإن الله شديد العقاب﴾؟","answer":"المضارع يستحضر تجدد المشاقة ويجعل الوعيد متوجهًا إلى كل من يستمر في عداوة الله ورسوله بعد معرفته ما حل ببني النضير؛ فليس المقصود حكاية ماضٍ انقضى وحده، بل التحذير من تجدد سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص701، تحت عنوان «دلالة التعبير بالمضارع: ﴿يشاق﴾»","url":""}]},{"id":"s59-10","number":10,"surah":59,"verses":[5],"references":[{"surah":59,"verses":[5]}],"verseLabel":"الحشر: 5","question":"ما سرّ التعبير في قول ﴿مَا قَطَعْتُمْ مِنْ لِينَةٍ﴾ ولم يقل «نخلة»؟","answer":"تذكر الموسوعة في «اللينة» أوجهًا: النخل سوى بعض أنواعه، أو النخلة الكريمة، أو مطلق النخلة. فعلى تخصيصها بنوع يكون ذكرها أشد في تصوير ما أصابهم من غيظ بقطع نخيلهم، وعلى العموم يجري اللفظ على استعمال أهل المدينة؛ فلا يجزم الجواب بنوع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص708–709، تحت عنوان «نكتة التعبير بـ﴿لينة﴾ نكرة»","url":""}]},{"id":"s59-11","number":11,"surah":59,"verses":[6],"references":[{"surah":59,"verses":[6]}],"verseLabel":"الحشر: 6","question":"لماذا عُبّر عن السعي بالخيل والركاب بـ﴿أَوْجَفْتُمْ﴾؟","answer":"لأن الإيجاف هو الإسراع الذي يجهد الدابة ويثير حركة الغزو؛ فنفيه ينفي عن المسلمين كلفة القتال والسعي العسكري، ويبين أن المال حصل بتسليط الله لا بقوة جيشهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص720، تحت عنوان «بلاغة التعبير بفعل الإيجاف دون غيره»","url":""}]},{"id":"s59-25","number":25,"surah":59,"verses":[6],"references":[{"surah":59,"verses":[6]}],"verseLabel":"الحشر: 6","question":"لماذا سُمّي مال بني النضير فيئًا لا غنيمة؟","answer":"لأنه آل إلى المسلمين من غير قتال ولا إيجاف، فكأنه رجع إلى الجهة التي تصرفه في مصالح الجماعة، بخلاف الغنيمة التي تُنال بالمواجهة ويكون للغانمين فيها نصيب مقرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص726–727، تحت عنوان «الفيء والغنيمة»","url":""}]},{"id":"s59-12","number":12,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"لماذا عُللت مصارف الفيء بقوله: ﴿كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنْكُمْ﴾؟","answer":"ليبين أن توزيع الفيء ليس قائمة عطاءات منفصلة، بل سياسة تمنع احتباس المال في دائرة الأقوياء؛ فالمقصد أن يتحرك المال في المجتمع وألا يزيد الغنى تركّزًا والفقر حرمانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص735، تحت عنوان «سر المجيء بالجملة التعليلية»","url":""}]},{"id":"s59-26","number":26,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"ماذا يفيد تنكير ﴿دُولَةً﴾ في تعليل توزيع الفيء؟","answer":"يفيد العموم؛ فيمنع أن يصير المال أيَّ صورة من صور التداول المحتكر بين الأغنياء، قليلة كانت أو كثيرة. فالحكم لا يعالج واقعة مخصوصة، بل يغلق كل طريق يعيد الثروة إلى الحلقة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص737–738، تحت عنوان «دلالة استعمال مفردة ﴿دولة﴾ نكرة»","url":""}]},{"id":"s59-13","number":13,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"ماذا يحقق التقابل بين ﴿فَخُذُوهُ﴾ و﴿فَانْتَهُوا﴾؟","answer":"يجمع الطاعة من جهتيها: قبول ما يأتي به الرسول والعمل به، والكف عما يمنع منه. فليس الاتباع انتقاءً للأوامر المحبوبة، بل استجابة كاملة في الفعل والترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص741–742، تحت عنوان «بلاغة العطف بين الجمل المتقابلة»","url":""}]},{"id":"s59-14","number":14,"surah":59,"verses":[8,9],"references":[{"surah":59,"verses":[8,9]}],"verseLabel":"الحشر: 8–9","question":"كيف تبوأ الأنصار ﴿الدَّارَ وَالْإِيمَانَ﴾ مع أن الإيمان لا يُسكن؟","answer":"جُعل الإيمان كأنه منزل استقروا فيه وتمكنوا منه كما استقروا في المدينة؛ فالعطف يصور سبقهم إلى الإيمان وثباتهم فيه، ويجعل بيئتهم المكانية والروحية مأوى واحدًا استقبلوا منه المهاجرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص765، تحت عنوان «توجيه عطف ﴿والإيمان﴾ على ﴿الدار﴾»","url":""}]},{"id":"s59-15","number":15,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"ما الذي تكني عنه عبارة ﴿وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِمَّا أُوتُوا﴾؟","answer":"تكني عن نقاء الأنصار من الحسد والضيق حين خُص المهاجرون بالفيء؛ فنفى النص حتى الإحساس الباطن بالحاجة والحرج، لا مجرد الاعتراض الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص769، تحت عنوان «بلاغة الكناية في نفي الحاجة»","url":""}]},{"id":"s59-16","number":16,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"ماذا يكشف اختيار ﴿وَيُؤْثِرُونَ﴾ في وصف الأنصار؟","answer":"يكشف أنهم لا يعطون من الفاضل عن حاجتهم فحسب، بل يقدّمون غيرهم على أنفسهم عن قصد؛ وصيغة المضارع تصور الإيثار خلقًا متجددًا لا موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص773، تحت عنوان «دلالة التعبير بـ﴿ويؤثرون﴾ مادة وصيغة»","url":""}]},{"id":"s59-27","number":27,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"لماذا سُميت حاجتهم ﴿خَصَاصَةً﴾؟","answer":"لأن أصل الخصاصة الفُرجة والخلل؛ فصورت الحاجة كأنها فجوة ظاهرة في معاشهم، ومع ذلك سدوا حاجة إخوانهم قبل حاجتهم. وهذا يجعل الإيثار أبلغ من مجرد الكرم مع السعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص777، تحت عنوان «بلاغة التعبير بمفردة ﴿خصاصة﴾ مادة وصيغة»","url":""}]},{"id":"s59-17","number":17,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"لماذا قيل: ﴿شُحَّ نَفْسِهِ﴾ لا بخل نفسه؟","answer":"لأن الشح أغلظ من البخل؛ فهو حرص داخلي شديد على المنع والاستئثار، وقد يدفع صاحبه إلى طلب ما ليس له، أما البخل فيظهر غالبًا في منع ما عنده. فالنجاة من الشح تحرير لمنبع السلوك قبل ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص778، تحت عنوان «بلاغة التعبير بالـ﴿شح﴾»","url":""}]},{"id":"s59-18","number":18,"surah":59,"verses":[10],"references":[{"surah":59,"verses":[10]}],"verseLabel":"الحشر: 10","question":"لماذا بدأ اللاحقون بطلب المغفرة لأنفسهم قبل إخوانهم؟","answer":"لأن الداعي يبدأ بإصلاح نفسه والاعتراف بحاجته، فيكون أصدق دعاءً وأبعد عن تزكية الذات، ثم يوسع الرحمة لإخوانه. فالتقديم ترتيب أدب لا استئثار بالمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص790–791، تحت عنوان «لطيفة تقديم الدعاء للنفس على الدعاء للآخرين»","url":""}]},{"id":"s59-28","number":28,"surah":59,"verses":[10],"references":[{"surah":59,"verses":[10]}],"verseLabel":"الحشر: 10","question":"لماذا وصف السابقون في الإيمان بأنهم ﴿إِخْوَانِنَا﴾؟","answer":"ليقرر أن رابطة الإيمان تتجاوز اختلاف الأزمنة والديار، وتجعل المؤمنين أمة واحدة يدعو لاحقها لسابقها. وفي الوصف أيضًا وفاء لأهل الفضل وتطهير للقلب من الغل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص791، تحت عنوان «فائدة وصف المؤمنين السابقين بالإخوة»","url":""}]},{"id":"s59-19","number":19,"surah":59,"verses":[11],"references":[{"surah":59,"verses":[11]}],"verseLabel":"الحشر: 11","question":"لماذا سمّى القرآن يهود بني النضير إخوانًا للمنافقين؟","answer":"لأن الفريقين اجتمعا على الكفر برسالة النبي ﷺ وعداوة الإسلام والتناصر عليه؛ فهي أخوة ولاء ومصلحة لا أخوة نسب، ويفضح الاسم حقيقة التحالف المستتر وراء اختلاف الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص15، تحت عنوان «وجه التعبير عن اليهود بلفظ: ﴿لإخوانهم﴾»","url":""}]},{"id":"s59-29","number":29,"surah":59,"verses":[11],"references":[{"surah":59,"verses":[11]}],"verseLabel":"الحشر: 11","question":"ماذا يفضح وصف إخوان المنافقين بأنهم ﴿الَّذِينَ كَفَرُوا﴾؟","answer":"يصرح بالصفة التي قامت عليها أخوتهم: الكفر، فلا تبقى علاقتهم مجرد جوار أو مصلحة سياسية؛ كما يكشف أن نفاق المتكلمين لا يحجب اشتراكهم الباطني مع الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص16، تحت عنوان «دلالة التعبير بالاسم الموصول»","url":""}]},{"id":"s59-20","number":20,"surah":59,"verses":[14],"references":[{"surah":59,"verses":[14]}],"verseLabel":"الحشر: 14","question":"ماذا يكشف قوله ﴿تَحْسَبُهُمْ جَمِيعًا﴾ عن وحدة أعداء المؤمنين؟","answer":"يكشف أنها وحدة في المظهر والحساب الخارجي فقط؛ فمن يراهم يظنهم كتلة متماسكة، ثم يفضح الواقع أن اجتماع الأجساد والصفوف لا يعني اتحاد القلوب والغايات.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص51، تحت عنوان «بلاغة التعبير بـ﴿تحسبهم﴾»","url":""}]},{"id":"s59-30","number":30,"surah":59,"verses":[14],"references":[{"surah":59,"verses":[14]}],"verseLabel":"الحشر: 14","question":"ماذا توحي كلمة ﴿شَتَّى﴾ في وصف قلوبهم؟","answer":"توحي بتفرق شديد متعدد الصور؛ ليست قلوبهم مختلفة في أمر عابر، بل موزعة بين أهواء وأحقاد وغايات لا يجمعها مقصد ثابت، ولذلك تنهار وحدتهم عند الاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص53، تحت عنوان «بلاغة التعبير بلفظ ﴿شتى﴾»","url":""}]},{"id":"s59-21","number":21,"surah":59,"verses":[16],"references":[{"surah":59,"verses":[16]}],"verseLabel":"الحشر: 16","question":"لماذا شُبّه المنافقون بالشيطان الذي يأمر الإنسان بالكفر ثم يتبرأ منه؟","answer":"لأن كليهما يغري ضحيته بالباطل ويعدها النصرة، ثم يخذلها عند حلول العاقبة: حرّض المنافقون اليهود ووعدوهم، فلما جدّ الخطر تركوهم كما يتبرأ الشيطان ممن أطاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص78، تحت عنوان «بلاغة تشبيه المنافقين بالشيطان»","url":""}]},{"id":"s59-22","number":22,"surah":59,"verses":[18,19,20,21,22,23,24],"references":[{"surah":59,"verses":[18,19,20,21,22,23,24]}],"verseLabel":"الحشر: 18–24","question":"كيف يلتقي ختام سورة الحشر بمطلعها؟","answer":"افتتحت بتسبيح الله في السماوات والأرض، وختمت بأن الخلائق كلها تسبح له بعد عرض أسمائه الحسنى؛ فيعود آخر السورة إلى أولها وتصبح آياتها كلها شاهدًا على كماله واستحقاقه للتنزيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص149، تحت عنوان «بلاغة رد عجز السورة على صدرها»","url":""}]},{"id":"s59-31","number":31,"surah":59,"verses":[24],"references":[{"surah":59,"verses":[24]}],"verseLabel":"الحشر: 24","question":"ما سر ترك العطف في قوله: ﴿الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ﴾، والعطف في قوله: ﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ﴾؟","answer":"الصفات المتعددة لا يُعطف بعضها على بعض لاتحاد محلها، ولذا يقل عطف صفات الله في التنزيل. وعُطفت في الحديد لأنها متضادة المعاني، فدفع العطف استبعاد اجتماعها في ذات واحدة. وهذا التوجيه منقول عن «البرهان».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص204.","url":""}]},{"id":"s59-32","number":32,"surah":59,"verses":[24],"references":[{"surah":59,"verses":[24]}],"verseLabel":"الحشر: 24","question":"ما سر عدم تكرار «ما» في قوله: ﴿يُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، وقد كُررت في أول السورة؟","answer":"لم يذكر بعد هذه الآية شيئًا عن أهل الأرض فأجمل ولم يكرر. أما في أولها فأعقب التسبيح بذكر إخراج الذين كفروا من أهل الكتاب وأحوالهم فكرر؛ فكرر في أول السورة وأجمل في آخرها.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص99؛ ومعاني النحو، ج1، ص146. المصادر","url":""}]},{"id":"s59-33","number":33,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"ما دلالة التعبير بالإيتاء في قوله: ﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ﴾ دون «أعطاكم»؟","answer":"الإعطاء يوجب التمليك، فلصاحبه أن يتصرف فيه كما يشاء، أما الإيتاء فقد لا يكون تمليكًا، ومثّل لذلك بهذه الآية وبقوله: ﴿وَآتَيْنَا ثَمُودَ النَّاقَةَ مُبْصِرَةً﴾. والإيتاء في الغالب للأمور العظيمة، والإعطاء للأمور المادية.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص79.","url":""}]},{"id":"s59-34","number":34,"surah":59,"verses":[18],"references":[{"surah":59,"verses":[18]}],"verseLabel":"الحشر: 18","question":"ما سر تقديم الخبرة على العمل في قوله: ﴿وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ﴾؟","answer":"إذا كان السياق في العمل قدّم العمل فقال: ﴿وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ﴾، وإذا كان في الأمور القلبية أو الكلام على الله قدّم صفته. والتقوى أمر قلبي فقدّم الخبرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص134–135.","url":""}]},{"id":"s59-35","number":35,"surah":59,"verses":[20],"references":[{"surah":59,"verses":[20]}],"verseLabel":"الحشر: 20","question":"ما سر النفي بـ«لا» في قوله: ﴿لَا يَسْتَوِي أَصْحَابُ النَّارِ وَأَصْحَابُ الْجَنَّةِ﴾، وبـ«ما» في قوله: ﴿وَمَا يَسْتَوِي الْأَعْمَى وَالْبَصِيرُ﴾؟","answer":"«ما» مع المضارع لنفي الحال، و«لا» لنفي الاستقبال. وعدم استواء الأعمى والبصير مشاهد في الدنيا، أما عدم استواء أصحاب النار وأصحاب الجنة فإنما يظهر في الآخرة، فنُفي بـ«لا».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص95–96.","url":""}]},{"id":"s60-1","number":1,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"ما سرّ التعبير في قوله ﴿لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ﴾ فقدم عداوته سبحانه؟","answer":"قدم عداوتهم لله لأنها الأصل والأعظم، ومنها تنشأ عداوتهم لأهل الإيمان، فكان تقديمها أبلغ في التنفير من موالاتهم. ثم عطف ﴿وعدوكم﴾ ليذكر المؤمنين بأن ضرر هذه العداوة متوجه إليهم أيضًا، وليقوي داعي اجتنابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص165، تحت عنوان «دلالة عطف (عدوكم) على ﴿عدوي﴾»","url":""}]},{"id":"s60-2","number":2,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"كيف صوّر قوله ﴿تُلْقُونَ إِلَيْهِمْ بِالْمَوَدَّةِ﴾ وضع المودة في غير موضعها؟","answer":"استعار الإلقاء، وهو طرح الشيء المحسوس، لإيصال المودة؛ فبدت المودة كشيء يرمى إلى العدو، وفي هذه الصورة تقبيح لوضعها حيث لا ينبغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص167–168، تحت عنوان «بلاغة الاستعارة في لفظة الإلقاء»","url":""}]},{"id":"s60-18","number":18,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"كيف ناسب لفظ ﴿تُلْقُونَ﴾ خفاء رسالة حاطب وسرعة إيصالها؟","answer":"يلمح الإلقاء إلى سرعة نقل الرسالة وخفة إيصالها في خفاء؛ فاختير لفظ يصور الحركة العاجلة التي جرى بها بث المودة إلى المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص168، تحت عنوان «مناسبة استعمال مفردة الإلقاء لسبب النزول»","url":""}]},{"id":"s60-3","number":3,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"كيف تكشف جملة الحال ﴿وَقَدْ كَفَرُوا بِمَا جَاءَكُمْ مِنَ الْحَقِّ﴾ تناقض مودتهم؟","answer":"تستحضر كفرهم الثابت بالحق حال إلقاء المودة إليهم؛ فتجعل الموالاة مستنكرة لأنهم يعادون أصل الإيمان الذي جاء المؤمنين، لا لأن خلافهم أمر عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص171، تحت عنوان «بلاغة جملة الحال ﴿وقد كفروا﴾ ببيان صاحبها»","url":""}]},{"id":"s60-4","number":4,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"لماذا تقدّم النهي عن موالاة الأعداء على شرط ﴿إِنْ كُنْتُمْ خَرَجْتُمْ جِهَادًا فِي سَبِيلِي﴾؟","answer":"لأن قطع الموالاة هو المقصود الأهم والأعجل، ثم جاء الشرط لتهييج المؤمنين وتذكيرهم بأن خروجهم لله وطلب مرضاته يقتضي حتمًا ترك موالاة عدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص179–180، تحت عنوان «السر البلاغي في تقديم النهي على الشرط دون العكس»","url":""}]},{"id":"s60-19","number":19,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"هل يشكك شرط ﴿إِنْ كُنْتُمْ خَرَجْتُمْ جِهَادًا فِي سَبِيلِي﴾ في صدق المؤمنين؟","answer":"لا؛ فالشرط جيء به للتحذير من فعل يناقض الخروج في سبيل الله، وليصور الموالاة كأمر لا يُتوقع ممن تحقق منه الجهاد وابتغاء مرضاة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص181، تحت عنوان «بلاغة المجاز المرسل المركب في أسلوب الشرط»","url":""}]},{"id":"s60-5","number":5,"surah":60,"verses":[2],"references":[{"surah":60,"verses":[2]}],"verseLabel":"الممتحنة: 2","question":"ما سرّ التعبير في قوله ﴿إِنْ يَثْقَفُوكُمْ﴾ لا «إن يظفروا بكم»؟","answer":"«يثقفوكم» تتضمن الظفر مع الحذق وسرعة الإدراك والإحكام؛ فتصور ترصدهم للمؤمنين وحرصهم على التمكن منهم. وهذه المعاني تزيد على مطلق الظفر، وتلائم ما يترتب عليه من إظهار العداوة والاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص199، تحت عنوان «نكتة استعمال مفردة ﴿يثقفوكم﴾»","url":""}]},{"id":"s60-6","number":6,"surah":60,"verses":[3],"references":[{"surah":60,"verses":[3]}],"verseLabel":"الممتحنة: 3","question":"لماذا قيل للمؤمنين ﴿لَنْ تَنْفَعَكُمْ أَرْحَامُكُمْ وَلَا أَوْلَادُكُمْ﴾؟","answer":"لإبطال الدافع الذي قد يحملهم على موالاة العدو طلبًا لحماية الأقارب والأولاد؛ فهذه الروابط لا تدفع حكم الله يوم القيامة، ولا تبرر مخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص211، تحت عنوان «فائدة النفي وغرضه»","url":""}]},{"id":"s60-20","number":20,"surah":60,"verses":[3],"references":[{"surah":60,"verses":[3]}],"verseLabel":"الممتحنة: 3","question":"لماذا خُصّ الأولاد بالذكر بعد ﴿أَرْحَامُكُمْ﴾؟","answer":"لأن الأولاد داخلون في الأرحام، لكنهم ألصق بالنفس وأشد استدعاء للعطف؛ فإفرادهم بعد العام يستوعب أقوى دوافع الموالاة ويؤكد أن قربهم لا ينفع يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص213، تحت عنوان «بلاغة التتميم في عطف الخاص على العام»","url":""}]},{"id":"s60-7","number":7,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"لماذا قيل ﴿أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ﴾ لا «بإبراهيم»؟","answer":"صوّر حرف الظرفية إبراهيم والذين معه كأنهم محل مستقر للأسوة؛ فالقدوة ليست وصفًا عابرًا، بل موقف متجسد في براءتهم من الشرك وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص224، تحت عنوان «بلاغة استعمال حرف الظرفية»","url":""}]},{"id":"s60-8","number":8,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"ما الذي أخرجه الاستثناء في ﴿إِلَّا قَوْلَ إِبْرَاهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ﴾ من الاقتداء؟","answer":"أخرج هذا القول الخاص من الأسوة؛ فلا يتخذ المؤمنون وعد إبراهيم لأبيه المشرك ذريعة للاستغفار للمشركين، مع بقاء الاقتداء به في البراءة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص235–236، تحت عنوان «نوع الاستثناء ودلالته»","url":""}]},{"id":"s60-21","number":21,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"لماذا وُجّه الاستثناء إلى وعد إبراهيم لأبيه بالاستغفار؟","answer":"لأن الوعد جاء مؤكدًا بالقسم والنون، فنهى الاستثناء عن الاقتداء بهذا الالتزام ابتداءً، ومنع تبعًا له ما يفضي إليه من الاستغفار للمشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص236، تحت عنوان «توجيه الاستثناء للوعد لا للاستغفار»","url":""}]},{"id":"s60-9","number":9,"surah":60,"verses":[7],"references":[{"surah":60,"verses":[7]}],"verseLabel":"الممتحنة: 7","question":"لماذا فُصل رجاء المودة في ﴿عَسَى اللَّهُ أَنْ يَجْعَلَ بَيْنَكُمْ﴾ عما قبله؟","answer":"جاء استئنافًا يؤنس المؤمنين بعد شدة الأمر بالبراءة، ويفتح لهم باب الرجاء بأن تتحول عداوة المشركين إلى مودة إذا هداهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص269، تحت عنوان «نكتة فصل الجملة عن السابق»","url":""}]},{"id":"s60-22","number":22,"surah":60,"verses":[7],"references":[{"surah":60,"verses":[7]}],"verseLabel":"الممتحنة: 7","question":"ماذا تحمل ﴿عَسَى﴾ من الله في وعد تبدل العداوة مودة؟","answer":"تحمل الإطماع والوعد القريب؛ فإذا أسند الرجاء إلى الله لم يبق مجرد احتمال مضطرب، بل صار باعثًا على الأمل في هداية من كان عدوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص269–270، تحت عنوان «بلاغة استعمال الفعل ﴿عسى﴾»","url":""}]},{"id":"s60-23","number":23,"surah":60,"verses":[7],"references":[{"surah":60,"verses":[7]}],"verseLabel":"الممتحنة: 7","question":"لماذا قيل ﴿أَنْ يَجْعَلَ بَيْنَكُمْ... مَوَدَّةً﴾؟","answer":"لأن الجعل يصور نقل العلاقة من حال العداوة إلى حال المودة، وهو تحول عجيب لا يقدر عليه إلا الله؛ فأسند إليه لإظهار قدرته ولطف تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص270–271، تحت عنوان «نكتة التعبير بالفعل ﴿يجعل﴾»","url":""}]},{"id":"s60-10","number":10,"surah":60,"verses":[8,9],"references":[{"surah":60,"verses":[8,9]}],"verseLabel":"الممتحنة: 8–9","question":"لماذا استؤنف قوله ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ﴾؟","answer":"ليقرر حكمًا مستقلًا يرفع توهم أن البراءة من عداوة الكافرين تعني منع البر والعدل مع كل غير محارب؛ فبيّن أن المسالمين بابهم غير باب المعتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص280، تحت عنوان «علة فصل جملة ﴿لا ينهاكم الله﴾»","url":""}]},{"id":"s60-24","number":24,"surah":60,"verses":[8,9],"references":[{"surah":60,"verses":[8,9]}],"verseLabel":"الممتحنة: 8–9","question":"ما الذي يحصره قوله ﴿إِنَّمَا يَنْهَاكُمُ اللَّهُ﴾ في الممتحنة؟","answer":"يحصر النهي عن التولي في الذين قاتلوا المؤمنين وأخرجوهم وأعانوا على إخراجهم؛ فيميز بوضوح بين معاملة المسالمين وبين موالاة المعتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص293، تحت عنوان «نوع القصر وبلاغته في قوله: ﴿إنما ينهاكم الله﴾ الآية»","url":""}]},{"id":"s60-25","number":25,"surah":60,"verses":[8,9],"references":[{"surah":60,"verses":[8,9]}],"verseLabel":"الممتحنة: 8–9","question":"لماذا عبّرت الآية عن المحظور بـ﴿أَنْ تَوَلَّوْهُمْ﴾ لا «أن تبروهم»؟","answer":"لأن التولي هو النصرة والموالاة التي تذيب موقف المؤمن في صف المعتدي، أما البر والإنصاف فليسَا ولاءً؛ فاختيار اللفظ يرسم الحد الفاصل بين الإحسان المشروع والموالاة المنهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص297، تحت عنوان «دلالة استعمال مفردة التولي دون البر»","url":""}]},{"id":"s60-11","number":11,"surah":60,"verses":[8],"references":[{"surah":60,"verses":[8]}],"verseLabel":"الممتحنة: 8","question":"لماذا اختير ﴿أَنْ تَبَرُّوهُمْ﴾ في معاملة غير المحاربين؟","answer":"لأن البر لفظ واسع يجمع الإحسان والإكرام وحسن المعاملة، فلا يقف الحكم عند مجرد ترك الأذى، بل يفتح أبواب الصلة التي لا تتعارض مع الولاء لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص286–287، تحت عنوان «نكتة التعبير بمفردة ﴿تبروهم﴾»","url":""}]},{"id":"s60-26","number":26,"surah":60,"verses":[8],"references":[{"surah":60,"verses":[8]}],"verseLabel":"الممتحنة: 8","question":"لماذا قُدِّم البر على الإقساط في ﴿أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ﴾؟","answer":"لأن البر أوسع وجوه الإحسان، ثم خُص العدل بالذكر لعظم شأنه ولئلا يظن أن اختلاف الدين يسوغ الجور؛ فانتقل النظم من العام إلى ما يحتاج إلى توكيد خاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص289، تحت عنوان «سر تقديم البر على الإقساط»","url":""}]},{"id":"s60-12","number":12,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"لماذا اعترض قوله ﴿اللَّهُ أَعْلَمُ بِإِيمَانِهِنَّ﴾ بين امتحان المهاجرات والحكم عليهن؟","answer":"ليحدد حد الامتحان البشري: يُبنى الحكم على العلامات الظاهرة، أما حقيقة الإيمان في القلوب فعلمها لله وحده؛ فلا يوهم الأمر بالامتحان إمكان كشف السرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص310–311، تحت عنوان «بلاغة الجملة الاعتراضية»","url":""}]},{"id":"s60-27","number":27,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"كيف قيل ﴿فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَاتٍ﴾ مع أن حقيقة الإيمان لا يعلمها إلا الله؟","answer":"أطلق العلم على الظن الغالب الذي تقوم عليه الأحكام بعد الامتحان؛ فالمطلوب تحقق بشري معتبر بالقرائن، لا يقين يحيط بما في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص313، تحت عنوان «بلاغة إطلاق العلم على الظن الغالب»","url":""}]},{"id":"s60-13","number":13,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"لماذا نُفي الحل من الجانبين في ﴿لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾؟","answer":"لقطع كل توهم ببقاء رابطة الزواج من جهة أحد الزوجين؛ فالنفي الثاني يتمم الأول ويؤكد أن الانفصال واقع على الطرفين بلا استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص316–317، تحت عنوان «دلالة العطف بين التتميم والتأكيد»","url":""}]},{"id":"s60-28","number":28,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"ما أثر عكس ترتيب الضمائر في ﴿لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾؟","answer":"صنع تقابلًا محكمًا يواجه كل طرف بالآخر، ثم يعكس موضعيهما في الجملة الثانية؛ فتتجسد المباعدة المتبادلة وانقطاع الحل بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص317، تحت عنوان «بلاغة العكس في النظم بين الجمل المتقابلة»","url":""}]},{"id":"s60-14","number":14,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"ما الصورة التي يرسمها قوله ﴿وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ﴾ لرابطة الزواج؟","answer":"يصوّر عقد الزواج بحبل يعصم الزوجين ويربط أحدهما بالآخر، ثم يصور بقاء الزوج متمسكًا بذلك الحبل؛ فجاء النهي إعلانًا لقطع الرابطة بعد اختلاف الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص325–326، تحت عنوان «بلاغة الاستعارة»","url":""}]},{"id":"s60-29","number":29,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"من المراد بـ﴿الْكَوَافِرِ﴾ في سياق ﴿وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ﴾؟","answer":"المراد في هذا السياق المشركات الوثنيات اللاتي قامت الآية بقطع عصمتهن من المؤمنين، فلا يحمل اللفظ هنا على كل كافرة بلا نظر إلى الأحكام الأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص326، تحت عنوان «معنى تعريف لفظ ﴿الكوافر﴾»","url":""}]},{"id":"s60-15","number":15,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا بدأت منهيات بيعة النساء بترك الشرك؟","answer":"لأن التوحيد أصل صحة الإيمان والعمل، فلا يستقيم إصلاح بقية السلوك مع فساد الاعتقاد؛ ثم إنه كان أظهر المفاسد وأشيعها في ذلك المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص350، تحت عنوان «دلالة البدء بترك الشرك»","url":""}]},{"id":"s60-30","number":30,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا ذُكرت السرقة بعد الشرك في بيعة النساء؟","answer":"لأن الشرك تضييع لحق الله، وأعقبه الاعتداء على أموال الناس بوصفه تضييعًا لحقوق العباد؛ فانتقل السياق من أصل الدين إلى أول مظاهر العدوان الاجتماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص353، تحت عنوان «بلاغة ذكر السرقة بعد الشرك»","url":""}]},{"id":"s60-31","number":31,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا جاء النهي عن قتل الأولاد بعد النهي عن الزنا؟","answer":"لأن الزنا قد يفضي إلى حمل واختلاط نسب ثم إلى التخلص من الولد بالقتل، فذكر المسبب بعد سببه، مع كون الزنا أشيع يومئذ فجاء ترتيبه أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص354، تحت عنوان «نكتة ذكر جريمة القتل بعد فاحشة الزنا»","url":""}]},{"id":"s60-32","number":32,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا خُتمت منهيات البيعة بقوله ﴿وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ﴾؟","answer":"ليجمع ما لم تفصله المنهيات السابقة تحت قاعدة عامة: طاعة النبي ﷺ في كل معروف وترك كل معصية؛ فكان الختام جامعًا لما تقدم وما يستجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص360، تحت عنوان «مناسبة ختم المنهيات بترك العصيان»","url":""}]},{"id":"s60-16","number":16,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"كيف أعاد استئناف ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَوَلَّوْا قَوْمًا﴾ ختام السورة إلى مطلعها؟","answer":"استأنف نهيًا جديدًا يرسخ مقصد السورة؛ فكما بدأت بمنع موالاة أعداء الله، ختمت بمنع تولي قوم غضب الله عليهم، فانتظم أولها وآخرها في التحذير نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص370، تحت عنوان «دلالة جملة الاستئناف»","url":""}]},{"id":"s60-33","number":33,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"لماذا عاد نداء المؤمنين في ختام سورة الممتحنة؟","answer":"ليجدد استدعاء إيمانهم عند آخر وصية، ويعمم الخطاب لكل المؤمنين في كل زمان ومكان؛ فيبقى النهي حاضرًا بعد انقضاء سبب النزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص370–371، تحت عنوان «دلالة نداء المؤمنين في الختام»","url":""}]},{"id":"s60-17","number":17,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"كيف يغيّر معنى ﴿مِنْ﴾ في ﴿كَمَا يَئِسَ الْكُفَّارُ مِنْ أَصْحَابِ الْقُبُورِ﴾ وجه التشبيه؟","answer":"إن كانت لابتداء الغاية فالصورة ليأس الكفار الأحياء من عودة أصحاب القبور، وإن كانت بيانية فالمراد كفار القبور أنفسهم وقد انقطع رجاؤهم من نعيم الآخرة؛ وفي الوجهين يبرز انقطاع الأمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص376–377، تحت عنوان «دلالة الحرف ﴿من﴾ وأثره في توجيه التشبيه البلاغي»","url":""}]},{"id":"s60-34","number":34,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"ماذا يضيف تشبيه يأسهم من الآخرة بيأس الكفار من أصحاب القبور؟","answer":"يجعل انقطاع رجائهم محسوسًا كحال من تيقن فوات ما يطلبه: إما يأس الحي من رجوع الميت، أو يأس الميت الكافر من نعيم الآخرة؛ فيشدد صورة الإعراض وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص377–378، تحت عنوان «بلاغة التشبيه ودلالته»","url":""}]},{"id":"s60-35","number":35,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"ما دلالة تعدية الإيمان بالباء في قوله: ﴿حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ﴾؟","answer":"الإيمان بالله لا يُعدّى في القرآن إلا بالباء، فإذا رأيت الإيمان معدّى باللام فهو لغير الله، وأكثر ما يكون مع الأشخاص، كقوله: ﴿لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللَّهَ جَهْرَةً﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص75.","url":""}]},{"id":"s60-36","number":36,"surah":60,"verses":[3],"references":[{"surah":60,"verses":[3]}],"verseLabel":"الممتحنة: 3","question":"ما سر التعبير بالفصل في قوله تعالى: ﴿لَنْ تَنْفَعَكُمْ أَرْحَامُكُمْ وَلَا أَوْلَادُكُمْ يَوْمَ الْقِيَامَةِ يَفْصِلُ بَيْنَكُمْ﴾ دون «يحكم» أو «يقضي»؟","answer":"الفصل أشد من الحكم والقضاء، إذ يقتضي الافتراق في الحكم والخاتمة. والفصل هنا بين المؤمنين وأعداء الله الذين نهاهم عن موالاتهم في أول السورة: ﴿لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ﴾، فناسب ذكر الفصل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص13–14.","url":""}]},{"id":"s60-37","number":37,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"ما سر تأنيث الفعل في قوله: ﴿قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ﴾، وتذكيره في الآية السادسة وفي الأحزاب: ﴿لَقَدْ كَانَ لَكُمْ… أُسْوَةٌ حَسَنَةٌ﴾؟","answer":"الأسوة تُطلق على الخصلة المؤتسى بها وعلى الشخص المؤتسى به. والمراد في الآية الرابعة الخصلة، بدليل أنه بيّنها بقوله: ﴿إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ﴾ فأُنث، وفي الموضعين الآخرين الشخص فذُكر، وحسّن التذكيرَ كثرةُ الفواصل بين «كان» واسمها. ومعنى الأسوة وترجيح الخصلة منقولان عن «روح المعاني».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص184–185.","url":""}]},{"id":"s60-38","number":38,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"ما دلالة تقديم الجار والمجرور في قوله: ﴿رَبَّنَا عَلَيْكَ تَوَكَّلْنَا﴾؟","answer":"التقديم لقصد الاختصاص، أي: عليك وحدك توكلنا، نظير قوله: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾. ولو قيل: «توكلنا عليك» لم يُفد نفي التوكل على غيره.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص41.","url":""}]},{"id":"s60-39","number":39,"surah":60,"verses":[4,6],"references":[{"surah":60,"verses":[4,6]}],"verseLabel":"الممتحنة: 4، 6","question":"ما سر تقديم الأسوة على المؤتسى به في قوله: ﴿أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ﴾، وتأخيرها في قوله: ﴿لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ﴾؟","answer":"في الآية الرابعة الكلام يدور على الخصلة وقد بيّنها، فقدّم الأسوة. وفي السادسة ذكر المؤتسى به وحده فقدّمه، وأطلق التأسي ليشمل كل الأمور الحسنة، فأكّد بلام القسم مع «قد»، وأبدل بقوله: ﴿لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ﴾ للدلالة على أهمية التأسي.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص185.","url":""}]},{"id":"s60-40","number":40,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"ما سر التعبير بالاسم ثم بالفعل في قوله: ﴿لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾؟","answer":"الاسم يدل على الثبوت والفعل على الحدوث والتغير. فعبّر عن المؤمنات بالاسم لأن الحكم في حقهن ثابت لا يتغير، وعن الكفار بالفعل لأن الحكم يتغير بتغيرهم إذا أسلموا. وفي «روح المعاني» نحو هذا عن الطيبي.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص186.","url":""}]},{"id":"s60-41","number":41,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"ما دلالة التعبير بالقبور في قوله: ﴿كَمَا يَئِسَ الْكُفَّارُ مِنْ أَصْحَابِ الْقُبُورِ﴾ دون «الأجداث»؟","answer":"الأجداث خُصّت في الاستعمال القرآني بحالة الخروج من القبور مسرعين إلى المحشر، أما القبور فاستُعملت في حال السكون والهمود. ومثّل لذلك بهذه الآية وبقوله: ﴿وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص154.","url":""}]},{"id":"s61-1","number":1,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما سرّ افتتاح سورة الصف بالفعل الماضي ﴿سَبَّحَ﴾؟","answer":"الماضي يقرر تحقق التسبيح وثبوته، ولا يحصره في زمن انتهى؛ فالمبحث يوجهه إلى الدوام والاستمرار، لأن تنزيه الخلق لخالقهم لا ينقطع. وفي صيغة «سبّح» مبالغة في التنزيه، فيفتتح الخطاب بإعلان خضوع الكون لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص390–391، تحت عنوان «دلالة التعبير بالفعل ﴿سبح﴾ مادة وصيغة»","url":""}]},{"id":"s61-2","number":2,"surah":61,"verses":[2],"references":[{"surah":61,"verses":[2]}],"verseLabel":"الصف: 2","question":"ما سرّ التعبير في قوله ﴿لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾ ولم يقل «لم لا تفعلون ما تقولون»؟","answer":"وجه الإنكار إلى القول لأن إطلاق الدعوى أو الوعد يجعل صاحبه كأنه متعهد بالوفاء، ثم يكشف قوله ﴿ما لا تفعلون﴾ مخالفة هذا التعهد. فالتوبيخ متعلق بقول لا يصدقه العمل، وهو تنبيه إلى خطورة الالتزام باللسان ثم ترك الوفاء، لا مجرد السؤال عن ترك فعلٍ من الأفعال.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص408–409، تحت عنوان «دلالة اسم الاستفهام (ما)، وتعيين المستفهم عنه»","url":""}]},{"id":"s61-3","number":3,"surah":61,"verses":[3],"references":[{"surah":61,"verses":[3]}],"verseLabel":"الصف: 3","question":"ما سر أن قيل ﴿كَبُرَ مَقْتًا عِنْدَ اللَّهِ﴾ بدل «كبر المقت»؟","answer":"يجعل النظم السامع يترقب أولًا: ما الذي كبر؟ ثم يأتي ﴿مقتًا﴾ بيانًا بعد إبهام، فيهوّل شأن هذا القول ويعظّم قبحه في النفس. واختيار المقت، وهو أشد البغض، يزيد التشنيع على أن يقول الإنسان ما لا يفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص414–415، تحت عنوان «الموقع الإعرابي لـ﴿مقتًا﴾ ودلالته»","url":""}]},{"id":"s61-4","number":4,"surah":61,"verses":[4],"references":[{"surah":61,"verses":[4]}],"verseLabel":"الصف: 4","question":"ما الصورة التي يرسمها تشبيه صف المؤمنين بالبنيان؟","answer":"يصورهم أجزاء متساندة من بناء واحد، يشد بعضها بعضًا ولا تترك للعدو ثغرة. فالتشبيه ينقل انتظام الصف ووحدة القصد والثبات من معنى معنوي إلى مشهد محسوس قوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص430، تحت عنوان «دلالة (كأن) التشبيهية»","url":""}]},{"id":"s61-16","number":16,"surah":61,"verses":[4],"references":[{"surah":61,"verses":[4]}],"verseLabel":"الصف: 4","question":"ماذا يضيف وصف بنيان المؤمنين بأنه ﴿مَرْصُوصٌ﴾؟","answer":"يدل على إحكام اتصال أجزائه حتى لا يبقى بينها خلل، فيصور تماسك المؤمنين ظاهرًا وباطنًا، وثباتهم أمام العدو كأنهم جسم واحد لا يتفكك.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص432، تحت عنوان «دلالة الصفة ﴿مرصوص﴾»","url":""}]},{"id":"s61-5","number":5,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"ماذا يضيف قوله ﴿وَقَدْ تَعْلَمُونَ أَنِّي رَسُولُ اللَّهِ﴾ إلى إنكار موسى أذاهم؟","answer":"يجعل أذاهم واقعًا مع علمهم برسالته، فيشتد الإنكار؛ لأن مقتضى هذا العلم تصديقه وتعظيمه لا إيذاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص442، تحت عنوان «معنى (الواو) ودلالتها في ﴿وقد﴾»","url":""}]},{"id":"s61-6","number":6,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"لماذا تعلقت عقوبة الزيغ بقلوبهم في قوله ﴿أَزَاغَ اللَّهُ قُلُوبَهُمْ﴾؟","answer":"لأنهم اختاروا الميل عن الحق مع معرفته، فبلغ الجزاء موضع الإدراك والإيمان فيهم. وإزاغة القلوب تعني حرمانها التوفيق والثبات بعد إصرار أصحابها، فتظهر خطورة الانحراف المتعمد حين يتحول إلى طبع مستقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص448، تحت عنوان «دلالة تعليق الإزاغة بالقلوب»","url":""}]},{"id":"s61-7","number":7,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"لماذا نادى عيسى قومه ﴿يَا بَنِي إِسْرَائِيلَ﴾ بدل «يا قوم»؟","answer":"يذكرهم باسم أبيهم الكريم وما يقتضيه الانتساب إليه من طاعة الله، ويستعطفهم بما يجمعهم من أصل معروف. ومن وجوه العدول أيضًا أن عيسى لا أب له فينسب نفسه إليهم بقول «يا قوم»، فاختير النداء الذي يحقق التذكير والاستمالة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص459، تحت عنوان «دلالة العدول من (القوم) إلى (بني إسرائيل)»","url":""}]},{"id":"s61-8","number":8,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ماذا يقرر وصف عيسى نفسه بأنه ﴿مُصَدِّقًا﴾ للتوراة؟","answer":"يقرر أن رسالته ليست قطيعة مع الوحي السابق، بل جاءت مؤيدة لأصله الحق ومبينة له؛ ولذلك كان تصديقه للتوراة حجة على بني إسرائيل ودعوة إلى قبول الرسول الذي وافق ما عرفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص461، تحت عنوان «دلالة ﴿مصدقًا﴾ موقعًا ومادة»","url":""}]},{"id":"s61-17","number":17,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"كيف جمع عيسى بين تصديق التوراة والتبشير برسول يأتي بعده؟","answer":"جمع بين حفظ صلة الرسالة بماضي الوحي وفتحها على خاتمته: يصدق ما قبله ويبشر بما بعده. فالعطف يكشف وحدة مصدر الرسالات وتكاملها، وينفي توهم التناقض أو الانقطاع بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص463–464، تحت عنوان «معنى (الواو) ودلالتها في ﴿ومبشرًا﴾»","url":""}]},{"id":"s61-9","number":9,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"لماذا صرحت بشارة عيسى باسم الرسول ﴿أَحْمَدُ﴾؟","answer":"ليتعين المبشر به تعيينًا يزيل الإبهام ويمنع صرف البشارة إلى غيره؛ فذكر الاسم العلم يجعل العلامة أوضح وأقوى في إقامة الحجة على من عرف البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص467، تحت عنوان «دلالة التعبير بالاسم العلم ﴿أحمد﴾»","url":""}]},{"id":"s61-18","number":18,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ما الدلالة التي يحملها اسم ﴿أَحْمَدُ﴾ في البشارة؟","answer":"يجمع الاسم معنى كثرة الحمد أو شدة استحقاقه؛ فهو أكثر حمدًا لربه، وأجمع للخصال التي يُحمد عليها. وبذلك يطابق الاسم كمال صفته ورسالة الخير التي جاء بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص469، تحت عنوان «دلالة الاسم ﴿أحمد﴾»","url":""}]},{"id":"s61-10","number":10,"surah":61,"verses":[8],"references":[{"surah":61,"verses":[8]}],"verseLabel":"الصف: 8","question":"ما الصورة في محاولة إطفاء نور الله بالأفواه؟","answer":"تمثل محاولتهم إبطال الوحي وإخماد الدعوة بمن ينفخ بفمه في نور عظيم ليطفئه؛ فتفضح ضآلة الوسيلة أمام قوة الحق، وتسخر من وهم قدرتهم على منع تمام نور الله وانتشاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص496، تحت عنوان «دلالة الاستعارة التمثيلية»","url":""}]},{"id":"s61-11","number":11,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ماذا يعني وعد الله أن ﴿يُظْهِرَهُ﴾ على الدين؟","answer":"يعني أن يعلي دين الحق ويبين حجته حتى يظهر صدقه وبطلان ما يخالفه، ويشمل علو البرهان وانتشار الدين وغلبته؛ فلا ينحصر الوعد في صورة واحدة من صور الظهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص514، تحت عنوان «دلالة الكناية في (يظهره)»","url":""}]},{"id":"s61-19","number":19,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ماذا يضيف التوكيد بـ﴿كُلِّهِ﴾ في وعد إظهار دين الحق؟","answer":"يؤكد أن الوعد لا يقتصر على بعض الأديان أو بعض المواطن، بل يتعلق بجنس الدين المخالف كله؛ فيستغرق المقابلة ويزيل احتمال التخصيص.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص517، تحت عنوان «دلالة التوكيد بـ﴿كله﴾»","url":""}]},{"id":"s61-12","number":12,"surah":61,"verses":[10],"references":[{"surah":61,"verses":[10]}],"verseLabel":"الصف: 10","question":"كيف يصبح الإيمان والجهاد ﴿تِجَارَةً﴾ رابحة؟","answer":"شُبها بالتجارة لأن المؤمن يبذل ماله ونفسه في طاعة الله وينال في المقابل نجاة ومغفرة وجنة. والصورة تخاطب رغبة الإنسان في الربح، ثم ترتقي بها من المكسب العاجل إلى صفقة لا خسارة فيها ولا نفاد لعوضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص526–527، تحت عنوان «دلالة الاستعارة في ﴿تجارة﴾»","url":""}]},{"id":"s61-13","number":13,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سرّ تقديم الأموال على الأنفس في الجهاد؟","answer":"تقديم الأموال ثم الأنفس يصور الترقي في مراتب البذل إلى ما هو أشق وأعظم، وتذكر الموسوعة أن المال وسيلة يستعان بها في الإنفاق وإعانة النفس. فترتيبهما يجمع البدء بما يعين على الجهاد ثم بلوغ غايته ببذل النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص536–537، تحت عنوان «معنى (الواو) ودلالتها في ﴿وأنفسكم﴾»","url":""}]},{"id":"s61-14","number":14,"surah":61,"verses":[13],"references":[{"surah":61,"verses":[13]}],"verseLabel":"الصف: 13","question":"لماذا سُمّي النصر والفتح ﴿أُخْرَى﴾ بعد المغفرة والجنة؟","answer":"لأنهما نعمة أخرى عاجلة تضاف إلى الجزاء الأخروي ولا تساويه رتبة؛ فالمغفرة والجنة الأصل الأعظم، ثم يأتي النصر والفتح زيادةً تقوي المؤمنين في الدنيا وتبشرهم بقرب الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص551–552، تحت عنوان «دلالة صيغة (أخرى)»","url":""}]},{"id":"s61-20","number":20,"surah":61,"verses":[13],"references":[{"surah":61,"verses":[13]}],"verseLabel":"الصف: 13","question":"لماذا وُصفت نعمة النصر والفتح بأنها ﴿تُحِبُّونَهَا﴾؟","answer":"لمراعاة ميل النفوس إلى رؤية ثمرة قريبة محسوسة، فتزداد رغبتها في الجهاد والثبات. ولا يعني ذلك أن النصر الدنيوي أفضل من نعيم الآخرة، بل هو حافز عاجل بعد الوعد الأعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص552–553، تحت عنوان «دلالة النعت بالجملة الفعلية المضارعية ﴿تحبونها﴾»","url":""}]},{"id":"s61-15","number":15,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ماذا يطلب الأمر ﴿كُونُوا أَنْصَارَ اللَّهِ﴾ فوق مجرد فعل النصرة مرة؟","answer":"يطلب أن تصبح النصرة صفة ثابتة وهوية ملازمة للمؤمنين، فيقيموا على حماية الدين والدعوة إليه والطاعة، لا أن تكون استجابتهم موقفًا عابرًا ينتهي بزوال سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص564–565، تحت عنوان «دلالة فعل الكون أمرًا»","url":""}]},{"id":"s61-21","number":21,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"لماذا قُربت دعوة المؤمنين إلى النصرة بمثال حواريي عيسى؟","answer":"ليتحول الأمر إلى قدوة تاريخية مجربة: دعا عيسى أنصاره فاستجاب الحواريون بوضوح، فكان موقفهم مثالًا للصدق والثبات يحفز أمة محمد ﷺ إلى جواب مماثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص567، تحت عنوان «نوع التشبيه في ﴿كما قال﴾ والغرض منه»","url":""}]},{"id":"s61-22","number":22,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ماذا تبشر به خاتمة قصة الحواريين في قوله ﴿فَأَيَّدْنَا الَّذِينَ آمَنُوا﴾؟","answer":"تبشر بأن نصرة دين الله لا تضيع؛ فقد قوى الله المؤمنين وثبتهم حتى غلبوا عدوهم وظهروا. والتعبير بالماضي يعرض تحقق الوعد في القصة دليلًا يطمئن المؤمنين إلى عاقبة النصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص580–581، تحت عنوان «دلالة الفعل الماضي ﴿فأيدنا﴾ مادة وصيغة»","url":""}]},{"id":"s61-23","number":23,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما دلالة تعدية التسبيح باللام في قوله: ﴿سَبَّحَ لِلَّهِ﴾، وتعديته بنفسه في مثل: ﴿وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا﴾؟","answer":"«سبّحه» نزّهه، و«سبّح له» فعل ذلك لأجله واللام للتعليل، فتدل على الإخلاص. ويستعمل المعدّى باللام للعقلاء وغيرهم ومع ما هو أعم من المسبّحين والأوقات، أما المعدّى بنفسه فلم يرد إلا للعقلاء. وفي «البحر المحيط» نحو هذا في معنى اللام.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص200–201.","url":""}]},{"id":"s61-24","number":24,"surah":61,"verses":[4],"references":[{"surah":61,"verses":[4]}],"verseLabel":"الصف: 4","question":"ما سر تقديم ﴿فِي سَبِيلِهِ﴾ على ﴿صَفًّا﴾، والتعبير بـ﴿بُنْيَانٌ﴾ دون «بناء»؟","answer":"قدّم ﴿فِي سَبِيلِهِ﴾ لتقدم النية وأهميتها قبل الدخول في الصف، وتوحيد النية سبب لتوحيد الصف. والقرآن يستعمل «البناء» للسماء و«البنيان» لما يبنيه البشر، ووصفه بالمرصوص للدلالة على شدة تماسكه وقوته.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص209.","url":""}]},{"id":"s61-25","number":25,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"ما دلالة النداء بـ«يا قوم» والمضارع في قوله: ﴿يَا قَوْمِ لِمَ تُؤْذُونَنِي وَقَدْ تَعْلَمُونَ أَنِّي رَسُولُ اللَّهِ إِلَيْكُمْ﴾؟","answer":"ناداهم بـ«يا قوم» تألفًا واستصراخًا لداعي القربى، وذكر مانعين من الأذى: كونهم قومه، وعلمهم أنه رسول الله، وقد آذوه مع ذلك. وقال ﴿تُؤْذُونَنِي﴾ ولم يقل «آذيتموني» للدلالة على استمرار الأذى له.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص210–212.","url":""}]},{"id":"s61-26","number":26,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ما دلالة نصب ﴿مُصَدِّقًا﴾ و﴿مُبَشِّرًا﴾، وقوله: ﴿يَأْتِي مِنْ بَعْدِي﴾ دون «بعدي»؟","answer":"جاء بهما حالين عاملهما ﴿رَسُولُ اللَّهِ﴾ ليدل على أنهما مما أُرسل به، ولو رفعهما لأفاد أنه أخبر عن نفسه بذلك. وقال ﴿مِنْ بَعْدِي﴾ ليدل على أنه ليس بينهما نبي، لأن «مِن» تفيد ابتداء الغاية، و«بعد» وحدها تحتمل القريب والبعيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص214.","url":""}]},{"id":"s61-27","number":27,"surah":61,"verses":[8],"references":[{"surah":61,"verses":[8]}],"verseLabel":"الصف: 8","question":"ما دلالة اسم الفاعل في قوله: ﴿وَاللَّهُ مُتِمُّ نُورِهِ﴾، وفي التوبة: ﴿وَيَأْبَى اللَّهُ إِلَّا أَنْ يُتِمَّ نُورَهُ﴾، وما دلالة ﴿بِأَفْوَاهِهِمْ﴾؟","answer":"اسم الفاعل يدل على الثبوت وأن الأمر استقر، و«أن يتم» تنصيص على الاستقبال، فما في الصف آكد. وقال ﴿بِأَفْوَاهِهِمْ﴾ ليدل على الصورة المضحكة لمن ينفخ بفمه في نور الشمس ليطفئه، ولأن كيدهم هنا تكذيب وافتراء وقولهم ﴿هَذَا سِحْرٌ مُبِينٌ﴾، وهذا محاربة بالأفواه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص220.","url":""}]},{"id":"s61-28","number":28,"surah":61,"verses":[8],"references":[{"surah":61,"verses":[8]}],"verseLabel":"الصف: 8","question":"ما سر اللام في قوله: ﴿يُرِيدُونَ لِيُطْفِئُوا نُورَ اللَّهِ﴾، وفي التوبة: ﴿يُرِيدُونَ أَنْ يُطْفِئُوا﴾؟","answer":"اللام يُؤتى بها مع مفعول فعل الإرادة للتوكيد، والسياق في الصف متجه إلى النبوة وتكذيب البشارة بمجيء أحمد، فاقتضى التوكيد. وآية التوبة في النعي على معتقدات أهل الكتاب في عزير والمسيح. ومعنى زيادة اللام للتوكيد منقول عن «الكشاف».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص219–220.","url":""}]},{"id":"s61-29","number":29,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ما سر ختم الآية بـ﴿وَلَوْ كَرِهَ الْمُشْرِكُونَ﴾، ولم تُختم بها آية الفتح: ﴿لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللَّهِ شَهِيدًا﴾؟","answer":"لم يُذكر في سياق آية الفتح محادّة المشركين ولا محاربتهم كما في الصف والتوبة، وإنما تقدمها الوعد بدخول المسجد الحرام آمنين، وقد تم بالاتفاق مع المشركين في صلح الحديبية، فلم يقتضِ ذلك الختم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص223–224.","url":""}]},{"id":"s61-30","number":30,"surah":61,"verses":[10],"references":[{"surah":61,"verses":[10]}],"verseLabel":"الصف: 10","question":"ما دلالة التعبير في قوله: ﴿هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنْجِيكُمْ مِنْ عَذَابٍ أَلِيمٍ﴾؟","answer":"الاستفهام للتشويق، ولم يقل «قل هل أدلكم» فكان الدالّ هو الله، وخصّ الدلالة والإنجاء بضمير المخاطبين إمحاضًا للنصح. وقال ﴿تُنْجِيكُمْ﴾ بالتخفيف للدلالة على سرعة الإنجاء، ونكّر العذاب وأطلقه ليشمل كل عذاب في الدنيا والآخرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص224–225.","url":""}]},{"id":"s61-31","number":31,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سر الجمع في قوله: ﴿ذَلِكُمْ خَيْرٌ لَكُمْ﴾، والإفراد في المجادلة: ﴿ذَلِكَ خَيْرٌ لَكُمْ وَأَطْهَرُ﴾؟","answer":"أراد أن الخير للأمة جميعها وعلى سبيل الدوام، فآية الجهاد لعموم المؤمنين غنيّهم وفقيرهم إلى يوم القيامة، وهي محكمة. أما آية المجادلة فتخص الأغنياء الذين يناجون الرسول، وقد نُسخ حكمها بعد مدة وجيزة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص228.","url":""}]},{"id":"s61-32","number":32,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سر تقديم ﴿فِي سَبِيلِ اللَّهِ﴾ على ﴿بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ﴾، وقد أُخّر في الأنفال والحجرات؟","answer":"الكلام في الصف على التجارة التي تنجي من العذاب فقدّم ما يتعلق بها، وقد تقدم في أول السورة ذكر القتال في سبيله وشاع فيها جو القتال. أما الحجرات فالكلام على صفة المؤمنين فقدّم ما يتعلق بهم، وفي الأنفال تقدم ذكر المال والفداء والغنيمة فقدّم المال.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص227.","url":""}]},{"id":"s61-33","number":33,"surah":61,"verses":[12],"references":[{"surah":61,"verses":[12]}],"verseLabel":"الصف: 12","question":"ما سر ذكر المساكن وجنات عدن في قوله: ﴿وَمَسَاكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ﴾؟","answer":"خُصّت المساكن بالذكر لأن في الجهاد مفارقة المساكن، فوُعدوا بمساكن أبدية، وهذا التعليل منقول عن «التحرير والتنوير». ومعنى «عدن» الإقامة والبقاء، والقتال مظنة مفارقة الحياة، فذكر أن المجاهد ذاهب إلى مساكن أطيب في دار البقاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص229.","url":""}]},{"id":"s61-34","number":34,"surah":61,"verses":[13],"references":[{"surah":61,"verses":[13]}],"verseLabel":"الصف: 13","question":"ما دلالة قوله: ﴿وَأُخْرَى تُحِبُّونَهَا نَصْرٌ مِنَ اللَّهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ الْمُؤْمِنِينَ﴾؟","answer":"﴿تُحِبُّونَهَا﴾ تقابل قوله في أول السورة ﴿إِنَّ اللَّهَ يُحِبُّ﴾، فكأنه قال: أطيعوا الله بما يحب وتكرهون يُعطِكم ما تحبون، ولم يقل «تجارة تحبونها» لأن فيها القتال. وقال ﴿نَصْرٌ مِنَ اللَّهِ﴾ ليدل على أن النصر منه لا من عدتهم، وأمر بالبشارة لأنها لا تكون إلا لما هو حاصل قطعًا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص231.","url":""}]},{"id":"s61-35","number":35,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ما دلالة الفاء وإسناد التأييد إلى الله في قوله: ﴿فَأَيَّدْنَا الَّذِينَ آمَنُوا عَلَى عَدُوِّهِمْ فَأَصْبَحُوا ظَاهِرِينَ﴾؟","answer":"الحواريون قالوا ﴿نَحْنُ أَنْصَارُ اللَّهِ﴾ أي الآن، وقاموا بالنصرة فعلًا فاستحقوا التأييد بالفاء الدالة على التعقيب لا بـ«ثم». وأسند التأييد إلى نفسه ليدل على أنه منه وحده، وارتبط باسميه ﴿الْعَزِيزُ الْحَكِيمُ﴾ في أول السورة. وفي «تفسير أبي السعود» أن التأييد بالحجة أو بالسيف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص232–233.","url":""}]},{"id":"s61-36","number":36,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما سر تكرار «ما» في قوله تعالى: ﴿سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾؟","answer":"حيث كُررت «ما» في آيات التسبيح أُعقبت بالكلام على أهل الأرض. وقد ذكر بعدها هنا أمرًا يتعلق بأهل الأرض فقال: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾، فكان التكرار هو المناسب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص202–203؛ والتعبير القرآني، ص99.","url":""}]},{"id":"s61-37","number":37,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما سر تقديم الجار والمجرور ﴿لِلَّهِ﴾ على الفاعل، وتقديم ﴿مَا فِي السَّمَاوَاتِ﴾ على ﴿مَا فِي الْأَرْضِ﴾؟","answer":"قدّم المجرور لأنه أهم، فالسياق على مستحق التسبيح، ولذا ذكر بعده من صفاته: ﴿وَهُوَ الْعَزِيزُ الْحَكِيمُ﴾. وقدّم ما في السماوات لأن أهلها أسبق في التسبيح وأدوم، كما قال: ﴿يُسَبِّحُونَ اللَّيْلَ وَالنَّهَارَ لَا يَفْتُرُونَ﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص203.","url":""}]},{"id":"s61-38","number":38,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما دلالة تعريف الوصفين في قوله: ﴿وَهُوَ الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"التعريف يدل على أنه لا عزيز في الحقيقة سواه ولا حاكم ولا حكيم سواه، فكل عز أو حكمة لغيره فهو منه. وقد شاع في السورة جو العزة والحكمة، كقوله: ﴿وَاللَّهُ مُتِمُّ نُورِهِ وَلَوْ كَرِهَ الْكَافِرُونَ﴾، ولا يفعل ذلك إلا العزيز الحكيم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص204.","url":""}]},{"id":"s61-39","number":39,"surah":61,"verses":[2],"references":[{"surah":61,"verses":[2]}],"verseLabel":"الصف: 2","question":"ما سر إخراج الكلام مخرجًا عامًا في قوله: ﴿لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾ مع أن السبب خاص؟","answer":"لو ذكر الأمر الذي نزلت بسببه الآية لظُنّ أن الإنكار مقصور عليه، فلو قالوا أمرًا آخر ولم يفعلوه كانوا بمنجاة من اللوم. فجعله عامًا في كل ما يُقال ولا يُفعل، إذ لا يتغير الحكم على هذا الوصف الممقوت أيًا كان السبب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص205.","url":""}]},{"id":"s61-40","number":40,"surah":61,"verses":[3],"references":[{"surah":61,"verses":[3]}],"verseLabel":"الصف: 3","question":"ما سر قوله: ﴿أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ﴾ بالمصدر المؤول دون «قولُكم»؟","answer":"«قولكم» يحتمل أن ذلك وقع مرة واحدة فيكون المقت الكبير لما حصل ولو مرة، وليس ذلك مرادًا. فجاء بالفعل المضارع الدال على التجدد والاستمرار، لبيان أن هذا المقت يكون إذا تكرر ذلك، ولم يقل «أن قلتم ما لم تفعلوا» للسبب نفسه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص207.","url":""}]},{"id":"s61-41","number":41,"surah":61,"verses":[3,4],"references":[{"surah":61,"verses":[3,4]}],"verseLabel":"الصف: 3–4","question":"ما سر جعل المقت للفعل في قوله: ﴿كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا﴾، والحب للفاعلين في قوله: ﴿إِنَّ اللَّهَ يُحِبُّ الَّذِينَ يُقَاتِلُونَ﴾؟","answer":"خاطب أصحاب الوصف الممقوت بـ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾، فلو قال: «إن الله يمقت الذين يقولون…» لأفضى ذلك إلى مقت المؤمنين، فجعل المقت للفعل دون المؤمن. وجعل الحب للفاعلين بسبب فعلهم، فأحب الفعل والفاعلين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص207–208.","url":""}]},{"id":"s61-42","number":42,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"ما سر وصفهم بالفسق في قوله: ﴿فَلَمَّا زَاغُوا أَزَاغَ اللَّهُ قُلُوبَهُمْ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ﴾؟","answer":"الفسق في أصله الخروج، من «فسقت الرطبة» إذا خرجت من قشرها. وهؤلاء زاغوا أي مالوا عن الطريق الحق وخرجوا عنه، فكان وصفهم بالفسق أنسب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص213.","url":""}]},{"id":"s61-43","number":43,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ما سر قول عيسى: ﴿يَا بَنِي إِسْرَائِيلَ﴾ دون «يا قوم» كما قال موسى، ونسبته إلى أمه ﴿عِيسَى ابْنُ مَرْيَمَ﴾؟","answer":"نسبه إلى أمه ليدل على أنه ليس ابن الله، ولم ينادهم «يا قوم» لأنه لا نسب له فيهم، إذ قوم الرجل من كان أبوه منهم. ولم يرد في القرآن أن ناداهم عيسى «يا قوم»، ولا ناداهم موسى «يا بني إسرائيل». وفي «الكشاف» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص213.","url":""}]},{"id":"s61-44","number":44,"surah":61,"verses":[7],"references":[{"surah":61,"verses":[7]}],"verseLabel":"الصف: 7","question":"ما دلالة الاستفهام وتعريف «الكذب» في قوله: ﴿وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ الْكَذِبَ﴾، وقد نُكّر في الأنعام ﴿كَذِبًا﴾؟","answer":"أخرجه مخرج الاستفهام ليشارك السامع بالإجابة ويقرر بنفسه أنه لا أظلم منه. وعرّف الكذب لأن الافتراء هنا في أمر معيّن هو صفة النبي والتبشير به، ونكّره في الأنعام لأن افتراءهم هناك عام في أمور متعددة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص215–217.","url":""}]},{"id":"s61-45","number":45,"surah":61,"verses":[7],"references":[{"surah":61,"verses":[7]}],"verseLabel":"الصف: 7","question":"ما سر قوله: ﴿وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ﴾ بلا توكيد، وفي الأنعام: ﴿لِيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍ إِنَّ اللَّهَ لَا يَهْدِي﴾؟","answer":"ختم بنفي الهداية لأنه قال: ﴿وَهُوَ يُدْعَى إِلَى الْإِسْلَامِ﴾ أي إلى الهدى. وزاد في الأنعام ﴿لِيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍ﴾ فاقتضى ذلك توكيد نفي الهداية بـ«إن»، وليس ذلك في آية الصف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص216.","url":""}]},{"id":"s61-46","number":46,"surah":61,"verses":[8,9],"references":[{"surah":61,"verses":[8,9]}],"verseLabel":"الصف: 8–9","question":"ما سر ختم الآية الثامنة بـ﴿وَلَوْ كَرِهَ الْكَافِرُونَ﴾، والتاسعة بـ﴿وَلَوْ كَرِهَ الْمُشْرِكُونَ﴾؟","answer":"الكفر في اللغة الستر والتغطية، ومن يريد إطفاء النور يريد أن يبدله ظلامًا، فناسب ذكر الكافرين. والكفر أعم من الشرك والنور أعم من الرسول والدين، فجعل العام بمقابل العام والخاص بمقابل الخاص. وفي «التفسير الكبير» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص222–223.","url":""}]},{"id":"s61-47","number":47,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ما دلالة الإضافة في قوله: ﴿هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ﴾؟","answer":"أضاف الرسول إلى ضميره تكريمًا له ودلالة على أنه حافظه وناصره. وأضاف الدين إلى الحق ولم يصفه به، فالحق من أسمائه فكأنه قال: دين الله، وهو دين الحق نقيض الباطل، ويحتمل إضافة الموصوف إلى صفته، فجمع أكثر من معنى لا يجمعها «الدين الحق».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص220–222.","url":""}]},{"id":"s61-48","number":48,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سر قوله: ﴿تُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ﴾ دون «أن تؤمنوا»؟","answer":"«أن» تفيد الاستقبال، فلو ذُكرت لكان المعنى أن الإيمان مطلوب في المستقبل، والإيمان ينبغي أن يكون في الحال. ولو قيل «أن تؤمنوا» لكان المصدر بدلًا من التجارة أو خبرًا لمبتدأ محذوف، والدلالة على الشيء لا تعني القيام به، فقال ﴿تُؤْمِنُونَ﴾ أي تفعلون ذلك.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص225–226.","url":""}]},{"id":"s61-49","number":49,"surah":61,"verses":[12],"references":[{"surah":61,"verses":[12]}],"verseLabel":"الصف: 12","question":"ما دلالة جزم ﴿يَغْفِرْ﴾ وقوله ﴿ذُنُوبَكُمْ﴾ دون «من ذنوبكم» في قوله: ﴿يَغْفِرْ لَكُمْ ذُنُوبَكُمْ﴾؟","answer":"الجزم يدل على أن ﴿تُؤْمِنُونَ﴾ طلب بمعنى «آمِنوا»، وعُدل عن الأمر إلى الخبر كأنهم امتثلوا فهم يفعلونه، ولا يصح جعله جوابًا للاستفهام لأن الدلالة لا تستلزم المغفرة. وقال ﴿ذُنُوبَكُمْ﴾ ليدل على غفرانها كلها. وفي «الكشاف» أن الخبر هنا للإيذان بوجوب الامتثال.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص226، 229.","url":""}]},{"id":"s61-50","number":50,"surah":61,"verses":[12],"references":[{"surah":61,"verses":[12]}],"verseLabel":"الصف: 12","question":"ما سر قوله: ﴿ذَلِكَ الْفَوْزُ الْعَظِيمُ﴾، وفي التوبة: ﴿وَذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ﴾ بضمير الفصل؟","answer":"التضحية في آية التوبة أعلى: فقد اشترى الله منهم أنفسهم وأموالهم، وذكر القتال ﴿فَيَقْتُلُونَ وَيُقْتَلُونَ﴾، أما في الصف فيجاهدون بأموالهم وأنفسهم وهي لا تزال لهم. والفوز إنما يكون على قدر التضحية، فلما زادوا في التضحية زاد لهم في الفوز وأكده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص230.","url":""}]},{"id":"s61-51","number":51,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ما سر قوله: ﴿كُونُوا أَنْصَارَ اللَّهِ﴾ دون «قولوا نحن أنصار الله» كما قال الحواريون؟","answer":"طلب الفعل ولم يطلب القول، وهذا مناسب لتأنيبه في أول السورة من قال ولم يفعل. وجاء بالأمر بعد التشويق بالتجارة ليعلموا أن ذلك من باب التكليف، والقائل للمؤمنين هو الله أما قائل ﴿مَنْ أَنْصَارِي﴾ فعيسى، وذلك يدل على عظم التبليغ.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص232.","url":""}]},{"id":"s61-52","number":52,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ما سر قول عيسى: ﴿مَنْ أَنْصَارِي إِلَى اللَّهِ﴾، وجواب الحواريين: ﴿نَحْنُ أَنْصَارُ اللَّهِ﴾ دون «نحن أنصارك»؟","answer":"أضاف عيسى الأنصار إلى نفسه لتكون نصرة الله بنصر النبي الجديد، ولو قال «من أنصار الله» لادّعى ذلك كل أحد، وفيه إلماح إلى انقطاع رسالته. وقال الحواريون ﴿أَنْصَارُ اللَّهِ﴾ للإعلام بأن نصرتهم لا تنقطع بعد ذهابه، وقال للمؤمنين ﴿كُونُوا أَنْصَارَ اللَّهِ﴾ لا «أنصار محمد» لئلا ترتبط النصرة بشخص.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص233–234.","url":""}]},{"id":"s62-1","number":1,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"كيف يمهّد افتتاح سورة الجمعة بقوله ﴿يُسَبِّحُ لِلَّهِ﴾ لمقصدها؟","answer":"يفتتح السورة بصورة الكون كله قائمًا بتعظيم الله، فيهيئ لإنكار من يترك ذكره عند نداء الجمعة وينفض إلى التجارة أو اللهو؛ فمن سبّح له الوجود كله أحق أن تُعظَّم عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص600، تحت عنوان «براعة الاستهلال في جملة ﴿يسبح لله﴾ الآية»","url":""}]},{"id":"s62-15","number":15,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"لماذا قيل في الجمعة ﴿يُسَبِّحُ﴾ بالمضارع، وفي الصف ﴿سَبَّحَ﴾ بالماضي؟","answer":"يستحضر المضارع دوام التسبيح وتجددَه، وهو أنسب بسورة تأمر بذكر الله وتنهى عن الانشغال عنه؛ أما الماضي في الصف فقرر وقوع التسبيح وثبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص601، تحت عنوان «نكتة العدول عن الماضي ﴿سبح﴾ في سورة الصف إلى المضارع هنا ﴿يسبح﴾»","url":""}]},{"id":"s62-16","number":16,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"ما مناسبة افتتاح السورة بأسماء الله ﴿الْمَلِكِ الْقُدُّوسِ الْعَزِيزِ الْحَكِيمِ﴾؟","answer":"تجمع كمال السلطان والتنزه والغلبة والحكمة: فهو الملك الذي تُقصد حضرته، المنزه عن النقص، العزيز الذي لا يُغلب، الحكيم في تشريعه. لذلك تقبح الغفلة عن ذكره لأجل تجارة أو لهو.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص606، تحت عنوان «مناسبة ذكر الصفات: ﴿الملك القدوس العزيز الحكيم﴾»","url":""}]},{"id":"s62-2","number":2,"surah":62,"verses":[2],"references":[{"surah":62,"verses":[2]}],"verseLabel":"الجمعة: 2","question":"لماذا وصف العرب الذين بُعث فيهم الرسول ﷺ بـ﴿الْأُمِّيِّينَ﴾؟","answer":"لإظهار عظم التحول الذي صنعته الرسالة في قوم لم يكونوا أهل كتاب وتعليم؛ فانتقلوا بالوحي إلى التلاوة والتزكية والحكمة، كما كانت أميته ﷺ برهانًا على أن هذا العلم وحي لا تعلم بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص611–612، تحت عنوان «معنى (أل) في ﴿الأميين﴾، ونكتة إيثار التعبير بهذه اللفظة»","url":""}]},{"id":"s62-3","number":3,"surah":62,"verses":[2],"references":[{"surah":62,"verses":[2]}],"verseLabel":"الجمعة: 2","question":"ما سرّ تقديم ﴿يَتْلُو عَلَيْهِمْ آيَاتِهِ﴾ على التزكية والتعليم؟","answer":"يعرض الترتيب مراحل الدعوة: تبليغ الآيات وتدبرها، ثم تطهير النفوس من الكفر والرذائل، ثم ترسيخ العقيدة والشرائع والحكمة بالتعليم. فالتلاوة مدخل التغيير، والتزكية تهيئ النفس لبناء العلم والعمل، وهو من ترتيب مقاصد الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص621، تحت عنوان «دلالة ترتيب جمل الصفات الثلاث ﴿يتلو﴾، ﴿ويزكيهم﴾، ﴿ويعلمهم﴾»","url":""}]},{"id":"s62-5","number":5,"surah":62,"verses":[3],"references":[{"surah":62,"verses":[3]}],"verseLabel":"الجمعة: 3","question":"ماذا يفيد تنكير ﴿آخَرِينَ﴾ في امتداد بعثة النبي ﷺ؟","answer":"يفتح اللفظ الباب لأجيال وأقوام غير معينين يلتحقون بالأمة بعد السابقين، ومنهم غير العرب؛ فلا تحصر الرسالة في جماعة الميلاد الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص629–630، تحت عنوان «دلالة التعبير بـ﴿وآخرين﴾، ولطيفة تنكيره»","url":""}]},{"id":"s62-17","number":17,"surah":62,"verses":[3],"references":[{"surah":62,"verses":[3]}],"verseLabel":"الجمعة: 3","question":"إلى من يعود الضمير في قوله ﴿آخَرِينَ مِنْهُمْ﴾؟","answer":"يحتمل عوده إلى الأميين، فيدخل من يأتي من العرب بعد السابقين، ويحتمل عوده إلى المؤمنين فيشمل كل من لحق بهم في الإيمان من العرب وغيرهم؛ وجامع الجميع الانتماء إلى أمة الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص630–631، تحت عنوان «مرجع الضمير في ﴿منهم﴾»","url":""}]},{"id":"s62-18","number":18,"surah":62,"verses":[3],"references":[{"surah":62,"verses":[3]}],"verseLabel":"الجمعة: 3","question":"ماذا توحي ﴿لَمَّا﴾ في قوله ﴿لَمَّا يَلْحَقُوا بِهِمْ﴾؟","answer":"تنفي أن اللاحقين أدركوا السابقين وقت نزول الآية، مع إشعار قوي بأن لحاقهم سيقع؛ فهي تجمع تأخرهم الزمني ووعد امتداد الأمة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص633، تحت عنوان «معنى ﴿لما﴾ في جملة ﴿لما يلحقوا بهم﴾»","url":""}]},{"id":"s62-6","number":6,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"لماذا قيل إن الحمار يحمل ﴿أَسْفَارًا﴾ لا «كتبًا»؟","answer":"الأسفار كتب عظيمة تكشف العلم، فاختيارها يعظم قيمة ما حُملوه ثم يضاعف المفارقة حين لا ينتفع الحامل بشيء منه. وتنكيرها يستكثر تلك الكتب وينوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص654–655، تحت عنوان «دلالة التعبير بـ﴿أسفارًا﴾ دون غيرها كـ(كتبًا)، ونكتة تنكيرها»","url":""}]},{"id":"s62-19","number":19,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"كيف يكشف مثل الحمار الحامل أسفارًا عيب العلم الذي لا يُعمل به؟","answer":"يشبه من أُلزم التوراة ثم عطلها بحمار يحمل كتبًا نفيسة ولا يدرك معناها ولا ينتفع بها؛ فالذم ليس في حمل العلم، بل في بقاء أثره خارج القلب والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص656–657، تحت عنوان «نوع التشبيه، وبلاغته في قوله: ﴿مثل الذين حملوا﴾ الآية»","url":""}]},{"id":"s62-7","number":7,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"ماذا يعني أنهم ﴿حُمِّلُوا التَّوْرَاةَ﴾؟","answer":"يعني أنهم كُلّفوا حفظها وفهمها والعمل بأحكامها وتبليغها، لا مجرد امتلاك نصها؛ فالتحميل يصور أمانة ثقيلة ضيعوا حقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص649–650، تحت عنوان «دلالة التعبير بالتحميل في جملة ﴿حملوا﴾، ولطيفة صوغه ماضيًا»","url":""}]},{"id":"s62-20","number":20,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"لماذا بُني ﴿حُمِّلُوا التَّوْرَاةَ﴾ للمجهول؟","answer":"لصرف التركيز إلى خيانتهم للأمانة التي أُلزموها، مع تنزيه اسم الله عن أن يذكر في سياق تشبيههم بالحمار وإهانة صنيعهم؛ فالفاعل معلوم من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص650، تحت عنوان «نكتة بناء الفعل ﴿حملوا﴾ لما لم يسم فاعله»","url":""}]},{"id":"s62-8","number":8,"surah":62,"verses":[6],"references":[{"surah":62,"verses":[6]}],"verseLabel":"الجمعة: 6","question":"لماذا تحداهم بتمني الموت إن كانوا ﴿أَوْلِيَاءَ لِلَّهِ مِنْ دُونِ النَّاسِ﴾؟","answer":"جاء الأمر بتمني الموت للتعجيز وكشف بطلان دعوى اختصاصهم بالولاية؛ فلو صدقوا في الاطمئنان إلى كرامتهم عند الله لما خافوا المصير إليه. وامتناعهم عن التمني حجة تكشف كذب الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص678، تحت عنوان «غرض الأمر في قوله: ﴿فتمنوا﴾»","url":""}]},{"id":"s62-9","number":9,"surah":62,"verses":[8],"references":[{"surah":62,"verses":[8]}],"verseLabel":"الجمعة: 8","question":"ما الصورة في قوله عن الموت ﴿فَإِنَّهُ مُلَاقِيكُمْ﴾؟","answer":"يجعل الموت كطالب يسير نحو الفارين حتى يلقاهم؛ فليست المسألة أنهم يقبلون عليه أو يبتعدون عنه، بل هو آتٍ يدركهم مهما فروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص695، تحت عنوان «بلاغة المجاز في قوله: ﴿فإنه ملاقيكم﴾»","url":""}]},{"id":"s62-10","number":10,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"ما المقصود بالسعي إلى الجمعة في قوله ﴿فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ﴾؟","answer":"هو الجد في القصد والمبادرة وترك الشواغل، لا الجري الذي يخل بالسكينة؛ فيأتي المصلي بوقار لكنه يقدم الجمعة على غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص717–718، تحت عنوان «دلالة السعي، وغرض الأمر في جملة ﴿فاسعوا﴾»","url":""}]},{"id":"s62-21","number":21,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"لماذا عُبّر عن صلاة الجمعة وخطبتها بقوله ﴿ذِكْرِ اللَّهِ﴾؟","answer":"لأن الصلاة والخطبة قائمتان على ذكر الله وتذكير الناس به، فسميت العبادة بأبرز ما تشتمل عليه؛ واللفظ يسع الخطبة والصلاة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص718–719، تحت عنوان «بلاغة المجاز في التعبير بـ﴿ذكر الله﴾»","url":""}]},{"id":"s62-11","number":11,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"ماذا يفيد الأمر ﴿وَذَرُوا الْبَيْعَ﴾ عند النداء للجمعة؟","answer":"يفيد ترك البيع وقطعه فورًا لا مجرد تخفيفه، لأن حق النداء مقدم على صفقة قائمة أو ربح منتظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص720–721، تحت عنوان «دلالة التعبير بلفظة (ذروا)، وغرض الأمر منه»","url":""}]},{"id":"s62-22","number":22,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"لماذا قيل ﴿وَذَرُوا الْبَيْعَ﴾ ولم يقل «التجارة»؟","answer":"خُص البيع لأنه أبرز معاملة تشغل وقت النداء، وأريد به ما يشمل البيع والشراء وسائر ما يصد عن الجمعة؛ فذكر الصورة الأظهر لينبه إلى جنس الشاغل كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص721، تحت عنوان «معنى (أل) في ﴿البيع﴾، ووجه المجاز فيه»","url":""}]},{"id":"s62-12","number":12,"surah":62,"verses":[10],"references":[{"surah":62,"verses":[10]}],"verseLabel":"الجمعة: 10","question":"هل الأمر ﴿فَانْتَشِرُوا فِي الْأَرْضِ﴾ بعد الجمعة يوجب الخروج للكسب؟","answer":"لا؛ جاء الأمر بعد منع البيع لرفع الحظر وإعادة الإباحة، فيجوز أن ينتشروا لمصالحهم ويجوز أن يبقوا، وليس كل مصلٍّ مأمورًا بالتجارة وجوبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص729، تحت عنوان «غرض الأمر في جملة ﴿فانتشروا﴾، ولطيفة إسناده إلى ضمير الجماعة»","url":""}]},{"id":"s62-23","number":23,"surah":62,"verses":[10],"references":[{"surah":62,"verses":[10]}],"verseLabel":"الجمعة: 10","question":"لماذا جُمع طلب الرزق بعد الجمعة مع الأمر بكثرة ذكر الله؟","answer":"حتى لا يتحول الانتشار في المعاش إلى غفلة؛ فيأخذ المؤمن بالأسباب ولسانه وقلبه موصولان بالله، فتجتمع عمارة الدنيا وعبادة المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص733، تحت عنوان «معنى (الواو) في جملة ﴿واذكروا الله كثيرًا﴾»","url":""}]},{"id":"s62-13","number":13,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"لماذا قُدّمت التجارة على اللهو في مشهد الانفضاض من الجمعة؟","answer":"لأن التجارة كانت المقصودة أصلًا عند قدوم العير، أما اللهو فكان تابعًا لها ومناديًا إليها؛ فبدأ بما حمل أكثرهم على الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص744، تحت عنوان «نكتة تقديم رؤية التجارة على اللهو»","url":""}]},{"id":"s62-24","number":24,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"لماذا قُدّم اللهو على التجارة في قوله ﴿خَيْرٌ مِنَ اللَّهْوِ وَمِنَ التِّجَارَةِ﴾؟","answer":"لأن اللهو أوضح ذمًا ولا منفعة معتبرة فيه، فبدأ به في المفاضلة، ثم ذكر التجارة ليقرر أن ما عند الله خير حتى من الكسب الذي يرجون نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص751–752، تحت عنوان «براعة تقديم ﴿من اللهو﴾ على (من التجارة)»","url":""}]},{"id":"s62-14","number":14,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"ما سرّ التعبير في قوله ﴿انْفَضُّوا إِلَيْهَا﴾ بالإفراد مع ذكر التجارة واللهو؟","answer":"عاد الضمير إلى التجارة لأنها المقصود الأهم في الانفضاض، وكان اللهو المصاحب لظهورها تابعًا لها. وتذكر الموسوعة أيضًا وجه الحذف لدلالة المذكور على الآخر؛ فإفراد الضمير يبرز الغرض الرئيس، ولا ينفي دخول اللهو في الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص746–747، تحت عنوان «مرجع الضمير في ﴿إليها﴾»","url":""}]},{"id":"s62-25","number":25,"surah":62,"verses":[10],"references":[{"surah":62,"verses":[10]}],"verseLabel":"الجمعة: 10","question":"ما دلالة «إذا» في قوله: ﴿فَإِذَا قُضِيَتِ الصَّلَاةُ فَانْتَشِرُوا فِي الْأَرْضِ﴾ دون «إن»؟","answer":"«إذا» تُستعمل لما هو مقطوع بحصوله ولما يكثر حصوله، ولا تُستعمل للأمر الافتراضي المحض، أما «إن» فلعموم الافتراضات. وانقضاء الصلاة مقطوع بحصوله لا بد منه، فجاء بـ«إذا».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص159.","url":""}]},{"id":"s62-26","number":26,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"ما سر تكرار «ما» في قوله تعالى: ﴿يُسَبِّحُ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾؟","answer":"حيث كرر «ما» في آيات التسبيح خصّ أهل الأرض بعدها بالذكر. وقد قال بعدها هنا: ﴿هُوَ الَّذِي بَعَثَ فِي الْأُمِّيِّينَ رَسُولًا مِنْهُمْ﴾ ومضى في الكلام على أهل الأرض، فكرر «ما».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص98–99.","url":""}]},{"id":"s62-27","number":27,"surah":62,"verses":[8],"references":[{"surah":62,"verses":[8]}],"verseLabel":"الجمعة: 8","question":"ما دلالة الفعل «ردّ» في قوله: ﴿ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ﴾ دون «تُرجعون»؟","answer":"يستعمل القرآن «ردّ» في الغالب للأمور الثقيلة والمستكرهة، و«رجع» لما هو أخف وأيسر. والآية في اليهود الذين زعموا أنهم أولياء الله ولا يتمنون الموت، فردّهم إلى ربهم ردّ ثقيل شديد، بخلاف ما جاء في المؤمنين من الرجوع.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص47–48.","url":""}]},{"id":"s62-28","number":28,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"ما سر تكرار «مِن» في قوله: ﴿مَا عِنْدَ اللَّهِ خَيْرٌ مِنَ اللَّهْوِ وَمِنَ التِّجَارَةِ﴾؟","answer":"كرر «مِن» ليُؤذن باستقلال الأفضلية على كل واحد منهما، لئلا يُتصور أن الذم إنما هو لاجتماع التجارة واللهو فيخرج انفراد أحدهما من الذم، كما تقول: «الأناة خير من التهور ومن العجلة». وفي «روح المعاني» عن الطيبي نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص176–177.","url":""}]},{"id":"s63-1","number":1,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"ما براعة افتتاح سورة المنافقون بجملة شرطية؟","answer":"يفتتح بمشهد مجيئهم إلى النبي ﷺ ونطقهم بالشهادة، ثم يأتي الجواب الإلهي كاشفًا كذبهم؛ فيضع القارئ مباشرة أمام التناقض بين الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص769، تحت عنوان «براعة الاستهلال بالجملة الشرطية»","url":""}]},{"id":"s63-2","number":2,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"لماذا حشد المنافقون المؤكدات في قولهم ﴿نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ﴾؟","answer":"بالغوا في توثيق كلامهم بلفظ الشهادة و﴿إن﴾ واللام والجملة الاسمية ليستروا كذب باطنهم وراء صورة اليقين. فكثرة المؤكدات هنا لا تدل على صدقهم، بل تكشف حاجتهم إلى إقناع السامع بما لا يعتقدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص773، تحت عنوان «فائدة تتابع المؤكدات في الجملة»","url":""}]},{"id":"s63-3","number":3,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"لماذا توسط قوله ﴿وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ﴾ بين دعوى المنافقين وتكذيبهم؟","answer":"لئلا يوهم تكذيب المنافقين أن مضمون قولهم في الرسالة كاذب؛ فأثبت الله حقيقة رسالة نبيه أولًا، ثم بيّن أن الكذب في ادعائهم الشهادة الصادقة بما لا يوافق قلوبهم. فالجملة تحمي الحقيقة وتحدد موضع الكذب بدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص773–774، تحت عنوان «دلالة الواو في صدر الجملة وأثرها الدلالي»","url":""}]},{"id":"s63-4","number":4,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"لماذا قيل ﴿إِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ﴾ ولم يقل: إنهم لكاذبون؟","answer":"أظهر وصفهم بدل الضمير ليقرر أن النفاق هو سبب كذبهم، ويثبت هذه الصفة عليهم في مقام فضحهم. كما يحول الحكم من الإشارة إلى أشخاص حاضرِين إلى قاعدة تكشف حقيقة المنافق أينما تكرر وصفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص777، تحت عنوان «دلالة التعبير بالإظهار موضع الإضمار»","url":""}]},{"id":"s63-18","number":18,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"كيف قابلت شهادة الله شهادة المنافقين في مطلع السورة؟","answer":"كرر السياق لفظ الشهادة على سبيل المشاكلة، لكن شهادتهم دعوى تخالف باطنهم، وشهادة الله خبر حق يكشف كذبهم. فالتشابه اللفظي يزيد المفارقة وضوحًا: صورة القول واحدة، والحقيقة متقابلة تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص776، تحت عنوان «بلاغة المشاكلة في الآية»","url":""}]},{"id":"s63-5","number":5,"surah":63,"verses":[2],"references":[{"surah":63,"verses":[2]}],"verseLabel":"المنافقون: 2","question":"لماذا سميت أيمان المنافقين ﴿جُنَّةً﴾؟","answer":"شُبهت أيمانهم الكاذبة بالترس الذي يتقي به المقاتل الضرب؛ فقد احتموا بها من انكشاف كفرهم ومن أحكامه، وجعلوها وسيلة لاكتساب الثقة والأمان. والصورة تكشف أنهم لم يقسموا طلبًا للحق بل دفاعًا عن باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص779، تحت عنوان «بلاغة التشبيه في قوله: ﴿جنة﴾»","url":""}]},{"id":"s63-6","number":6,"surah":63,"verses":[3],"references":[{"surah":63,"verses":[3]}],"verseLabel":"المنافقون: 3","question":"كيف قيل عن المنافقين ﴿آمَنُوا ثُمَّ كَفَرُوا﴾؟","answer":"لأنهم أظهروا الإيمان بألسنتهم ثم كشف سلوكهم ما استقر من كفرهم، وقيل: دخل بعضهم في الإيمان ثم ارتد. وفي الوجهين يبين التعبير أن الانتساب الظاهر لا ينفع إذا نقضه القلب والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص786، تحت عنوان «دلالة التعبير بالفعل ﴿آمنوا﴾ مادة وصيغة»","url":""}]},{"id":"s63-7","number":7,"surah":63,"verses":[3],"references":[{"surah":63,"verses":[3]}],"verseLabel":"المنافقون: 3","question":"ما الذي تصوره عبارة ﴿طُبِعَ عَلَى قُلُوبِهِمْ﴾، ولماذا لا يفقهون؟","answer":"تصور العبارة القلب كشيء خُتم عليه فانغلق عن قبول الحق؛ فإذا انسد طريق الهدى إلى القلب فقد صاحبه الفقه والبصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص788، تحت عنوان «بلاغة المجاز في الطبع على القلوب»","url":""}]},{"id":"s63-8","number":8,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا قيل ﴿تُعْجِبُكَ أَجْسَامُهُمْ﴾ لا «أشخاصهم»؟","answer":"لأن لفظ الأجسام يلفت إلى البنية الظاهرة وحدها، كأن ما يثير الإعجاب فيهم قشرة جسمية بلا روح إيمان ولا عقل نافع. فاختيار اللفظ يمهد للمفارقة بين حسن الهيئة وفراغ الباطن التي يكشفها تشبيههم بالخشب.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص797، تحت عنوان «دلالة التعبير بلفظ الأجسام دون غيره»","url":""}]},{"id":"s63-9","number":9,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا شُبّه المنافقون بالخشب؟","answer":"لأن لهم أجسامًا ومناظر قد تعجب، لكنهم خالون من الفهم النافع كما أن الخشب له جرم ولا يعقل. فالتشبيه يهدم الواجهة الجذابة ويصور جمود قلوبهم وعجزهم عن الانتفاع بما يسمعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص801–802، تحت عنوان «بلاغة التشبيه في قوله ﴿كأنهم خشب مسندة﴾»","url":""}]},{"id":"s63-19","number":19,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"ماذا يضيف وصف الخشب بأنها ﴿مُسَنَّدَةٌ﴾ إلى صورة المنافقين؟","answer":"يصوّر أجسامًا مصفوفة تستند إلى الجدار ولا تقوم بنفسها ولا تؤدي نفعًا، مع أن منظرها قد يبدو مستقيمًا. وكذلك المنافقون يعتمدون على غيرهم ويتزينون بالمظهر، لكنهم فارغون من الثبات والعمل النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص803–804، تحت عنوان «نكتة وصف الخشب بأنها ﴿مسندة﴾»","url":""}]},{"id":"s63-10","number":10,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا كان المنافقون يحسبون ﴿كُلَّ صَيْحَةٍ﴾ واقعةً عليهم؟","answer":"لأن خوف انكشافهم جعلهم يترقبون العقوبة في كل صوت مرتفع أو خبر مفاجئ، فلا تمر صيحة إلا ظنوها تفضحهم أو تستدعي قتالهم. ولفظ ﴿كل﴾ يصور دوام هلعهم واتساعه مهما اختلف سبب الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص805، تحت عنوان «نكتة التعبير بلفظ ﴿كل﴾»","url":""}]},{"id":"s63-11","number":11,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا قيل عن المنافقين ﴿هُمُ الْعَدُوُّ﴾ مع أن للمؤمنين أعداء غيرهم؟","answer":"المقصود إبراز أنهم العدو الأشد خطرًا في هذا المقام، لأنهم يخفون العداوة ويخالطون المؤمنين ويعرفون أسرارهم، بخلاف العدو الظاهر الذي يُعرف موضع الحذر منه. فالقصر للمبالغة في التحذير لا لنفي كل عدو سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص807–808، تحت عنوان «بلاغة القصر بتعريف طرفي الإسناد»","url":""}]},{"id":"s63-12","number":12,"surah":63,"verses":[5],"references":[{"surah":63,"verses":[5]}],"verseLabel":"المنافقون: 5","question":"لماذا صُوّر إعراض المنافقين بقوله ﴿لَوَّوْا رُءُوسَهُمْ﴾؟","answer":"لأن ليّ الرأس حركة مرئية تجمع الإعراض بالاستكبار والاستهزاء، وهي أبلغ من مجرد القول إنهم أعرضوا. فالصورة تستحضر رفضهم الاستغفار وإظهارهم أنهم لا يبالون بالدعوة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص16، تحت عنوان «سر التعبير بـ﴿لووا رؤوسهم﴾»","url":""}]},{"id":"s63-13","number":13,"surah":63,"verses":[6],"references":[{"surah":63,"verses":[6]}],"verseLabel":"المنافقون: 6","question":"لماذا فُصل قوله ﴿إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ﴾ عما قبله؟","answer":"لأنه يأتي تعليلًا مستقلًا لعدم المغفرة في هذا المقام: إصرارهم على الفسق هو الذي حرمهم طريق الهداية، لا قصور الاستغفار لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص25، تحت عنوان «نكتة فصل قوله ﴿إن الله لا يهدي القوم الفاسقين﴾»","url":""}]},{"id":"s63-14","number":14,"surah":63,"verses":[7,8],"references":[{"surah":63,"verses":[7,8]}],"verseLabel":"المنافقون: 7–8","question":"لماذا وصف المنافقين مرة بأنهم ﴿لَا يَفْقَهُونَ﴾ ومرة بأنهم ﴿لَا يَعْلَمُونَ﴾؟","answer":"نُفي عنهم الفقه حين كان المطلوب فهم أن خزائن الله ورزقه لا يملكها المنافقون، وهو معنى يحتاج إلى تدبر. ونُفي عنهم العلم حين جهلوا الحقيقة الظاهرة أن العزة لله ورسوله والمؤمنين؛ فجمع السياق فقدان الفهم العميق والجهل بالحق الواضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص47–48، تحت عنوان «نكتة تكرار نفي العلم عنهم بعد نفي الفقه»","url":""}]},{"id":"s63-15","number":15,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"كيف نسبت الآية الإلهاء إلى الأموال والأولاد في قوله ﴿لَا تُلْهِكُمْ أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ﴾؟","answer":"أسند الإلهاء إلى المال والولد لأنهما سببه الظاهر، أما الفاعل الحقيقي فهو الإنسان حين يفرط في التعلق بهما ويقدمهما على ذكر الله. فالمجاز يحذر من تحويل النعمة إلى شاغل، ولا يذم المال والولد في ذاتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص56، تحت عنوان «بلاغة المجاز العقلي»","url":""}]},{"id":"s63-16","number":16,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"لماذا كانت الصدقة أول ما تمناه المحتضر في قوله ﴿فَأَصَّدَّقَ وَأَكُنْ مِنَ الصَّالِحِينَ﴾؟","answer":"لأن سياق الآيات حذّر من أن تلهي الأموال عن ذكر الله والإنفاق، فكان أول ما يندم عليه المحتضر ما أمسكه ولم يقدمه. وتقديم الصدقة يكشف أن المال الذي شغله صار عند انكشاف النهاية أحب شيء إليه أن يبذله قبل فوات العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص70–71، تحت عنوان «سر تقديم الصدقة»","url":""}]},{"id":"s63-17","number":17,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ماذا تكشف الفاء في أمنية المحتضر ﴿فَأَصَّدَّقَ﴾ عن غرضه من طلب التأخير؟","answer":"تكشف أنه لا يطلب مهلةً ليزداد من الدنيا، بل يجعل التأخير سببًا مباشرًا لإيقاع الصدقة وتحقيق الصلاح. كما تصور وعده بالمبادرة فورًا إلى تدارك ما فاته، لأن الأجل المطلوب قريب والفرصة لا تحتمل إبطاءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص68، تحت عنوان «دلالة التعبير بالفاء»","url":""}]},{"id":"s63-20","number":20,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"ما سر الختم بقوله: ﴿فَأُولَئِكَ هُمُ الْخَاسِرُونَ﴾، واختيار ﴿عَنْ ذِكْرِ اللَّهِ﴾ دون غيره من العبادات؟","answer":"الخسران أنسب شيء للمنشغل بالمال الذي يريد الربح، وضمير الفصل وتعريف الخبر يفيدان القصر والتوكيد. واختار ذكر الله لأنه يشمل جميع الفرائض، فكان الخسران كبيرًا متناسبًا مع عظم المعصية. وفي «الكشاف» و«روح المعاني» و«البحر المحيط» نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص183–184.","url":""}]},{"id":"s63-21","number":21,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"ما سر قوله: ﴿وَمَنْ يَفْعَلْ ذَلِكَ﴾ دون «ومن تُلهِه تلك» أو «ومن فعل»؟","answer":"نسب الفعل إلى الشخص ليدل على أن الانصراف عن اللهو بمقدوره وأنه من كسبه فينال جزاءه. وجاء بالمضارع لأن الالتهاء بالأموال والأولاد أمر يومي متكرر، ولو قال «ومن فعل» لاحتمل أن ذلك الخسران الكبير يقع ولو فُعل مرة واحدة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص183.","url":""}]},{"id":"s63-22","number":22,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما دلالة «مِن» وإسناد الرزق في قوله: ﴿وَأَنْفِقُوا مِنْ مَا رَزَقْنَاكُمْ﴾؟","answer":"الأمر بالإنفاق يقابل قول المنافقين: ﴿لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ﴾. و«مِن» للتبعيض فتستسهل النفوس التخلي عن قسم من المال لا كله، وأسند الرزق إلى نفسه ليدل على أن المال من رزق الله فتطيب النفوس بإخراج بعضه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص185.","url":""}]},{"id":"s63-23","number":23,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما دلالة «مِن» وتقديم المفعول على الفاعل في قوله: ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ أَحَدَكُمُ الْمَوْتُ﴾؟","answer":"«مِن» تفيد ابتداء الغاية الزمانية، أي الزمن المتصل بالموت، ففيها إشارة إلى قربه وطلب التعجيل، وحذفها يفيد الوقت الذي قبل الموت قريبًا أو بعيدًا. وقدّم المفعول لأنه المهم هنا، فهو المعنيّ بالإنفاق وهو المتحسر النادم إذا عاجله الموت.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص185–186.","url":""}]},{"id":"s63-24","number":24,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر إثبات الياء في ﴿أَخَّرْتَنِي﴾، وحذفها في قول إبليس: ﴿لَئِنْ أَخَّرْتَنِ إِلَى يَوْمِ الْقِيَامَةِ﴾؟","answer":"هذا الطالب يريد التأخير لنفسه حقًا ولا شيء ألزم منه لمصلحته فأظهر الضمير، وإبليس لا يريده لنفسه بل ليُضلّ ذرية آدم فحذفه واجتزأ بالكسرة. ثم إن ﴿لَوْلَا أَخَّرْتَنِي﴾ طلب صريح، وكلام إبليس شرط دخل عليه القسم، فصرّح بالضمير في الطلب الصريح.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص188–189؛ وبلاغة الكلمة في التعبير القرآني، ص24.","url":""}]},{"id":"s63-25","number":25,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر التعبير بـ«لولا» والفعل الماضي في قوله: ﴿لَوْلَا أَخَّرْتَنِي﴾ دون «لو أخرتني» أو «لولا تؤخرني»؟","answer":"«لولا» أشدّ في الطلب من «لو» وفيها إلحاح وتنديم، و«لو» قد تفيد العرض الخفيف أو التمني الميؤوس منه، وهذا طالب لا متمنٍّ. وجاء بالماضي لأن المحذور وقع، والمضارع قد يفيد أن الأمر لم يقع بعد وأن فيه سعة، مع ما في دخول «لولا» على الماضي من قوة الطلب.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص187.","url":""}]},{"id":"s63-26","number":26,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر قوله: ﴿فَأَصَّدَّقَ﴾ دون «فأتصدّق» الذي هو الأصل؟","answer":"مقاطع «فأصّدّق» خمسة ومقاطع «فأتصدّق» ستة، فاختار الأقصر لتناسب طلب التأخير إلى أجل قريب. وفيها تضعيفان في الصاد والدال، والتضعيف يدل على المبالغة والتكثير، فدلّ على أنه أراد أجلًا قريبًا يُكثر فيه من الصدقة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص191–192. المصادر","url":""}]},{"id":"s63-27","number":27,"surah":63,"verses":[6],"references":[{"surah":63,"verses":[6]}],"verseLabel":"المنافقون: 6","question":"ما سر التوكيد بـ«إنّ» في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ﴾، وقد ورد بلا توكيد في المائدة والتوبة والصف؟","answer":"آيات المنافقون أشدّ المواضع تبكيتًا وذمًّا، فقد فصّلت سوءاتهم: أنهم كاذبون، اتخذوا أيمانهم جنة، آمنوا ثم كفروا، يحسبون كل صيحة عليهم، يصدّون وهم مستكبرون، إلى غير ذلك، فناسب التوكيد. أما آيتا المائدة والتوبة ففي المسلمين، وآية الصف في قوم موسى وهم مؤمنون به.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص81–82.","url":""}]},{"id":"s63-28","number":28,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"ما سر تكرار «لا» في ﴿وَلَا أَوْلَادُكُمْ﴾، وتقديم الأموال على الأولاد؟","answer":"كلّ منهما داعٍ من دواعي الإلهاء، ولو قال «أموالكم وأولادكم» لاحتمل أن النهي عن الجمع بينهما. وقدّم الأموال لأنها تلهي أكثر والمقام مقام إلهاء، وليناظر تقديمَ الصدقة في الآية بعدها. وحيث اجتمع المال والولد في القرآن قُدّم المال إلا في موطن واحد من التوبة لأن المقام مقام حب.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص181–182.","url":""}]},{"id":"s63-29","number":29,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما دلالة الفاء وحذف حرف النداء في قوله: ﴿فَيَقُولَ رَبِّ﴾؟","answer":"الفاء تفيد السبب والتعقيب بلا مهلة، فالموت سبب الندم وطلب التأخير يأتي في ساعته، ولا تفيد «ثم» ولا الواو ذلك. وناسب قصرَ الوقت حذفُ «يا»، فالوقت لا يحتمل التضييع بل يستعجل في طلبه ويختصر ما لا حاجة به إليه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص186–187.","url":""}]},{"id":"s63-30","number":30,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر نصب ﴿فَأَصَّدَّقَ﴾ وجزم ﴿وَأَكُنْ مِنَ الصَّالِحِينَ﴾، ولم يجعلهما على نسق واحد؟","answer":"هذا عطف على المعنى: «أصّدّق» منصوب بعد فاء السببية، و«أكن» مجزوم جوابًا للطلب على نية إسقاط الفاء، أي: إن أخرتني أكن من الصالحين، فجمع بين معنيي السبب والشرط. ولم يسوِّ بينهما لأن الصلاح أهم من الصدقة فهو الذي ينجي من العذاب. وفي «البحر المحيط» عن الزمخشري وابن عطية نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص189–190؛ ومعاني النحو، ج4، ص18.","url":""}]},{"id":"s64-1","number":1,"surah":64,"verses":[1],"references":[{"surah":64,"verses":[1]}],"verseLabel":"التغابن: 1","question":"ماذا يفيد تكرار ﴿لَهُ﴾ في قوله ﴿لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ﴾؟","answer":"يفيد قصر الملك والحمد الكاملين على الله، ويقرر استقلال كل حقيقة منهما: فهو وحده المالك المتصرف، وهو وحده المستحق للحمد على نعمه وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص92–93، تحت عنوان «فائدة تقديم شبه الجملة على المسند إليه»","url":""}]},{"id":"s64-18","number":18,"surah":64,"verses":[1],"references":[{"surah":64,"verses":[1]}],"verseLabel":"التغابن: 1","question":"لماذا اقترن الحمد بالملك في مطلع سورة التغابن؟","answer":"لأن الملك يثبت تمام القدرة والتصرف، والحمد يثبت كمال الحكمة والإحسان؛ فليس ملكه قهرًا مجردًا، بل تدبيرًا يستحق الحمد في كل حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص95، تحت عنوان «مناسبة اقتران الحمد بالملك»","url":""}]},{"id":"s64-2","number":2,"surah":64,"verses":[2],"references":[{"surah":64,"verses":[2]}],"verseLabel":"التغابن: 2","question":"ما سرّ التعبير في قوله ﴿فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ وقدم الكافر؟","answer":"قدم الكافر لأن المقام مقام تعريض به وتوبيخ له على كفره مع أن الله خالقه، فكان ذكره أولًا أنسب بغرض الإنذار. وتذكر الموسوعة كذلك كثرة الكافرين في بيان وجه هذا التقديم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص103، تحت عنوان «فائدة تقديم ذكر ﴿كافر﴾ على ﴿مؤمن﴾»","url":""}]},{"id":"s64-3","number":3,"surah":64,"verses":[3],"references":[{"surah":64,"verses":[3]}],"verseLabel":"التغابن: 3","question":"ماذا يفيد قوله عن صور الناس ﴿فَأَحْسَنَ صُوَرَكُمْ﴾؟","answer":"يفيد أنه أوجد صورهم على هيئة متقنة مستقيمة تلائم وظائفهم، فالإحسان يشمل جمال الخِلقة وكمال التهيئة لا مجرد حسن المنظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص114، تحت عنوان «دلالة التعبير بفعل ﴿فأحسن﴾»","url":""}]},{"id":"s64-4","number":4,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"لماذا تكرر فعل ﴿يَعْلَمُ﴾ عند ذكر السماوات والأرض ثم السر والجهر؟","answer":"لاختلاف مجالات العلم وتنوعها؛ فيستقل كل مجال بالتقرير، ويتجدد التذكير بإحاطة علم الله بالكون وبأعمال الناس الظاهرة والخفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص121، تحت عنوان «دلالة تكرار فعل: (يعلم)»","url":""}]},{"id":"s64-19","number":19,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"لماذا خُصَّ ﴿مَا فِي الصُّدُورِ﴾ بعد قوله ﴿يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾؟","answer":"لأن ما في الصدور أخفى طبقات السر؛ فذكره بعد العموم يؤكد أن علم الله يبلغ النيات والخواطر والدوافع التي لا يطلع عليها البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص122–123، تحت عنوان «دلالة عطف الخاص على العام»","url":""}]},{"id":"s64-20","number":20,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"ماذا يقرر ختام الآية بقوله ﴿وَاللَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ﴾؟","answer":"يقرر ثبوت علم الله وإحاطته الدائمة بما استقر في القلوب، فيجعل التذييل قاعدة عامة تبعث على مراقبته والخوف من خفايا النيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص124، تحت عنوان «غرض التذييل بصفة العلم»","url":""}]},{"id":"s64-5","number":5,"surah":64,"verses":[5],"references":[{"surah":64,"verses":[5]}],"verseLabel":"التغابن: 5","question":"ما الصورة في قوله عن المكذبين ﴿فَذَاقُوا وَبَالَ أَمْرِهِمْ﴾؟","answer":"صُورت عاقبة الكفر بطعام مر يذوقونه مباشرة؛ فالذوق يجعل العقوبة تجربة محسوسة بعد أن كانت وعيدًا يسمعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص132، تحت عنوان «بلاغة الاستعارة في فعل الذوق»","url":""}]},{"id":"s64-21","number":21,"surah":64,"verses":[5],"references":[{"surah":64,"verses":[5]}],"verseLabel":"التغابن: 5","question":"لماذا أضيف الوبال إلى أمرهم في ﴿وَبَالَ أَمْرِهِمْ﴾؟","answer":"للدلالة على أن سوء العاقبة تولد من شأنهم الذي اختاروه، أي كفرهم وعنادهم؛ فالعذاب ثمرة عملهم لا ظلم واقع عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص133، تحت عنوان «نوع الإضافة ودلالتها»","url":""}]},{"id":"s64-6","number":6,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"ماذا يكشف تقديم ﴿بَشَرٌ﴾ في قولهم ﴿أَبَشَرٌ يَهْدُونَنَا﴾؟","answer":"يجعل بشرية الرسل نفسها محور الإنكار، كأنهم يستبعدون أن يكون الهادي إنسانًا مثلهم؛ فيفضح تعاليهم عن اتباع الحق لا ضعف دليله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص143، تحت عنوان «نكتة تقديم المسند إليه على المسند الفعلي»","url":""}]},{"id":"s64-7","number":7,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"لماذا عُطف التولي على الكفر في قوله ﴿فَكَفَرُوا وَتَوَلَّوْا﴾؟","answer":"ليجمع بين رفض الحق في الباطن والإعراض عن سماعه واتباعه في الظاهر؛ فالتولي أثر عملي يزيد الكفر ظهورًا وقبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص144، تحت عنوان «نكتة عطف التولي على الكفر»","url":""}]},{"id":"s64-22","number":22,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"ماذا يفيد قوله ﴿وَاسْتَغْنَى اللَّهُ﴾ جملةً اسمية بعد كفرهم وتوليهم؟","answer":"يفيد ثبوت غنى الله الدائم عن إيمانهم وطاعتهم؛ فكفرهم لا ينقص ملكه، وهم المحتاجون إليه في كل حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص145، تحت عنوان «نكتة التعبير بالجملة الاسمية»","url":""}]},{"id":"s64-23","number":23,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"لماذا خُتم الحديث عن استغناء الله بوصفه ﴿غَنِيٌّ حَمِيدٌ﴾؟","answer":"الغني يقرر أنه لا يحتاج إلى خلقه، والحميد يبين أنه مستحق للحمد بذاته ونعمه سواء حمدوه أم كفروا؛ فيجتمع كمال الاستغناء وكمال الاستحقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص146، تحت عنوان «مناسبة التذييل بصفتي: ﴿غني حميد﴾»","url":""}]},{"id":"s64-8","number":8,"surah":64,"verses":[7],"references":[{"surah":64,"verses":[7]}],"verseLabel":"التغابن: 7","question":"ماذا يكشف اختيار ﴿زَعَمَ﴾ في قوله ﴿زَعَمَ الَّذِينَ كَفَرُوا أَنْ لَنْ يُبْعَثُوا﴾؟","answer":"يشعر بأن قولهم دعوى باطلة بلا برهان، ويستنكر جرأتهم على الجزم بنفي البعث مع افتقارهم إلى العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص149، تحت عنوان «بلاغة استعمال مفردة: ﴿زعم﴾»","url":""}]},{"id":"s64-24","number":24,"surah":64,"verses":[7],"references":[{"surah":64,"verses":[7]}],"verseLabel":"التغابن: 7","question":"لماذا جاء الرد على نفي البعث بـ﴿بَلَى﴾؟","answer":"لأنها تنقض النفي السابق وتقلبه إلى إثبات مؤكد: سيبعثون حتمًا. فهي جواب موجز يهدم أصل دعواهم قبل إقامة القسم والدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص150–151، تحت عنوان «معنى ﴿بلى﴾ ودلالة استعمالها»","url":""}]},{"id":"s64-25","number":25,"surah":64,"verses":[7],"references":[{"surah":64,"verses":[7]}],"verseLabel":"التغابن: 7","question":"ما غرض القسم في ﴿قُلْ بَلَى وَرَبِّي لَتُبْعَثُنَّ﴾؟","answer":"لتوكيد البعث بأقوى أساليب التقرير، وربطه بربوبية الله وقدرته التي خلق بها أول مرة؛ فيواجه إنكارهم بقسم ووعد لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص151، تحت عنوان «بلاغة القسم وغرضه الارتباطي»","url":""}]},{"id":"s64-9","number":9,"surah":64,"verses":[8],"references":[{"surah":64,"verses":[8]}],"verseLabel":"التغابن: 8","question":"لماذا صُوّر القرآن بأنه ﴿النُّورِ﴾؟","answer":"لأنه يكشف حقائق الإيمان ويهدي من ظلمات الجهل والشك كما يكشف النور المرئيات ويهدي في الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص160، تحت عنوان «بلاغة الاستعارة في لفظ (النور)»","url":""}]},{"id":"s64-26","number":26,"surah":64,"verses":[8],"references":[{"surah":64,"verses":[8]}],"verseLabel":"التغابن: 8","question":"ماذا يضيف قوله عن القرآن ﴿الَّذِي أَنْزَلْنَا﴾ بعد وصفه بالنور؟","answer":"يميز هذا النور بأنه وحي منزل من عند الله، ويعظم شأن إنزاله ويذكر بنعمة وصول الهداية إلى الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص161، تحت عنوان «غرض التعبير بالاسم الموصول»","url":""}]},{"id":"s64-10","number":10,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"لماذا سُمي يوم القيامة ﴿يَوْمُ التَّغَابُنِ﴾؟","answer":"لأنه اليوم الذي يظهر فيه الربح والخسران الحقيقيان: يرى المؤمنون فوزهم، ويرى الكافرون أنهم باعوا الآخرة بالدنيا وخسروا أنفسهم ومنازلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص168–169، تحت عنوان «بلاغة الاستعارة والمجاز والتمثيل في لفظ: ﴿التغابن﴾»","url":""}]},{"id":"s64-27","number":27,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"ماذا يفيد تعريف الطرفين في قوله ﴿ذَلِكَ يَوْمُ التَّغَابُنِ﴾؟","answer":"يقصر التغابن الكامل الحقيقي على ذلك اليوم؛ فما يعده الناس ربحًا وخسارة في الدنيا يتضاءل أمام انكشاف المصير الأبدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص169، تحت عنوان «بلاغة القصر بتعريف طرفي الإسناد»","url":""}]},{"id":"s64-11","number":11,"surah":64,"verses":[10],"references":[{"surah":64,"verses":[10]}],"verseLabel":"التغابن: 10","question":"ما الصورة في قوله عن المؤمن ﴿يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ﴾؟","answer":"تفيد ﴿عن﴾ المجاوزة، فتصور السيئات وقد أُبعدت عنه ومحيت آثارها، فلا تبقى حاجزًا بينه وبين رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص172، تحت عنوان «دلالة حرف (عن)»","url":""}]},{"id":"s64-28","number":28,"surah":64,"verses":[10],"references":[{"surah":64,"verses":[10]}],"verseLabel":"التغابن: 10","question":"لماذا جُمع للمؤمن بين تكفير السيئات وإدخال الجنات؟","answer":"ليجتمع له دفع الضرر وجلب النفع: تزول تبعات الذنب أولًا، ثم ينال الرحمة والنعيم الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص172، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s64-29","number":29,"surah":64,"verses":[10],"references":[{"surah":64,"verses":[10]}],"verseLabel":"التغابن: 10","question":"ماذا يوحي وصف الكافرين بأنهم ﴿أَصْحَابُ النَّارِ﴾؟","answer":"يوحي بملازمتهم النار ودوام مقامهم فيها؛ فالصاحب يلازم صاحبه، وفيه تقريع يقابل دخول المؤمنين في الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص182، تحت عنوان «دلالة التعبير بلفظ ﴿أصحاب﴾»","url":""}]},{"id":"s64-12","number":12,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"ماذا يقرر القصر في قوله ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ﴾؟","answer":"يقرر أن كل مصيبة تقع بعلم الله وتقديره، لا فوضى ولا خروجًا عن سلطانه؛ فيورث المؤمن طمأنينة وتسليمًا لا استسلامًا للأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص188، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s64-30","number":30,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"لماذا قُدم الإيمان بالله على هداية القلب عند المصيبة؟","answer":"لأن التصديق بأن المصيبة بإذن الله هو السبب الذي يفتح القلب للرضا والصبر وحسن الفهم؛ فالهداية ثمرة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص192، تحت عنوان «سر تقديم الإيمان على الهداية»","url":""}]},{"id":"s64-31","number":31,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"لماذا خُص القلب بالهداية في قوله ﴿يَهْدِ قَلْبَهُ﴾؟","answer":"لأن القلب موضع الجزع والرضا ومركز ثبات الإنسان؛ فإذا هداه الله عند المصيبة استقام الجسد والعمل، وتحولت المحنة إلى يقين وصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص195–196، تحت عنوان «سر التنصيص على القلب وجعله مفعول الهداية»","url":""}]},{"id":"s64-13","number":13,"surah":64,"verses":[12],"references":[{"surah":64,"verses":[12]}],"verseLabel":"التغابن: 12","question":"ماذا تضيف نسبة الرسول إلى الله في قوله ﴿رَسُولِنَا﴾؟","answer":"تشرف الرسول وتعظم قدره وتقرر وجوب طاعته؛ لأنه مبعوث الله المؤتمن على بلاغ رسالته، لا متحدث من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص207، تحت عنوان «دلالة إضافة الرسول إلى ضمير العظمة ﴿رسولنا﴾»","url":""}]},{"id":"s64-14","number":14,"surah":64,"verses":[14],"references":[{"surah":64,"verses":[14]}],"verseLabel":"التغابن: 14","question":"ماذا يفيد قوله ﴿مِنْ أَزْوَاجِكُمْ وَأَوْلَادِكُمْ﴾ بدل وصفهم جميعًا بالعداوة؟","answer":"يفيد التبعيض؛ فليس كل زوج أو ولد عدوًا، وإنما يقع التحذير ممن يصد عن الطاعة أو يثبط عن الحق، فيبقى الحكم منصفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص223، تحت عنوان «دلالة التعبير بـ﴿من﴾ في قوله: ﴿من أزواجكم﴾»","url":""}]},{"id":"s64-32","number":32,"surah":64,"verses":[14],"references":[{"surah":64,"verses":[14]}],"verseLabel":"التغابن: 14","question":"كيف يكون بعض الأزواج والأولاد ﴿عَدُوًّا﴾ مع بقاء محبتهم؟","answer":"قد تكون العداوة حقيقية إن قصدوا الصد عن الدين، وقد تكون مجازية إذا حملت محبتهم المرء على ترك واجب أو ارتكاب محرم؛ فالعبرة بأثرهم لا بزوال المودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص226، تحت عنوان «الحقيقة والمجاز في لفظة ﴿عدوًا﴾»","url":""}]},{"id":"s64-15","number":15,"surah":64,"verses":[14],"references":[{"surah":64,"verses":[14]}],"verseLabel":"التغابن: 14","question":"لماذا أعقب التحذير من بعض الأزواج والأولاد بقوله ﴿وَإِنْ تَعْفُوا وَتَصْفَحُوا وَتَغْفِرُوا﴾؟","answer":"حتى لا يتحول الحذر إلى ظلم وقسوة؛ فالآية تدعو إلى معالجة الخطأ بالعفو والصفح والمغفرة، مع بقاء الانتباه لما يصد عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص228، تحت عنوان «دلالة العطف في قوله: ﴿وإن تعفوا﴾»","url":""}]},{"id":"s64-33","number":33,"surah":64,"verses":[14],"references":[{"surah":64,"verses":[14]}],"verseLabel":"التغابن: 14","question":"ما دلالة ترتيب ﴿تَعْفُوا وَتَصْفَحُوا وَتَغْفِرُوا﴾؟","answer":"يرتقي بالمؤمن من ترك المؤاخذة، إلى الإعراض عن اللوم وإزالة أثر الإساءة، ثم إلى مغفرة تامة تستر الذنب وتعيد صفاء العلاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص229، تحت عنوان «دلالة الترتيب في قوله: ﴿وإن تعفوا وتصفحوا وتغفروا﴾»","url":""}]},{"id":"s64-16","number":16,"surah":64,"verses":[15],"references":[{"surah":64,"verses":[15]}],"verseLabel":"التغابن: 15","question":"ماذا يفيد قصر الأموال والأولاد على كونهم ﴿فِتْنَةٌ﴾ في هذا السياق؟","answer":"يبالغ في التحذير من شدة ملازمتهم للاختبار وكثرة ما يعرض بسببهم من انشغال أو تقصير، فلا ينبغي أن يحجب حبهم حق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص235، تحت عنوان «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s64-34","number":34,"surah":64,"verses":[15],"references":[{"surah":64,"verses":[15]}],"verseLabel":"التغابن: 15","question":"ماذا يضيف وصف الأجر عند الله بأنه ﴿عَظِيمٌ﴾ بعد التحذير من فتنة المال والولد؟","answer":"يرغب في تقديم طاعة الله على متاع الدنيا، فالأجر أعظم قدرًا وأبقى من الأموال والأولاد، ويعوض المؤمن عما تركه لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص240، تحت عنوان «دلالة وصف الأجر بأنه عظيم»","url":""}]},{"id":"s64-17","number":17,"surah":64,"verses":[16],"references":[{"surah":64,"verses":[16]}],"verseLabel":"التغابن: 16","question":"هل يعني قوله ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾ الاكتفاء بما تهواه النفس؟","answer":"لا؛ معناه بذل أقصى الوسع في التقوى من غير تكليف بما يعجز عنه الإنسان. فهو يرفع الحرج الحقيقي، ولا يجعل الاستطاعة ذريعة لترك الممكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص246، تحت عنوان «بلاغة التعبير بقوله: ﴿ما استطعتم﴾»","url":""}]},{"id":"s64-35","number":35,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"ما الفرق بين التعبير بالفعل في ﴿يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ﴾ وباسم المفعول في ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ﴾؟","answer":"آثر في هود اسم المفعول «مجموع» على الفعل المستقبل «يُجمَع» لما فيه من الدلالة على ثبات معنى الجمع لليوم وأنه موصوف بهذه الصفة، ويظهر ذلك بالموازنة بآية التغابن التي جاءت بالفعل الدال على الحدوث. وهذا التوجيه منقول عن «المثل السائر».","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص13.","url":""}]},{"id":"s64-36","number":36,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"ما سر زيادة ﴿يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ﴾ هنا، ولم ترد في نظيرتها من سورة الطلاق؟","answer":"آية التغابن خطاب للكافرين ودعوة لهم إلى الإيمان بعد قوله: ﴿زَعَمَ الَّذِينَ كَفَرُوا﴾ و﴿فَآمِنُوا بِاللَّهِ وَرَسُولِهِ﴾، وآية الطلاق خطاب للمؤمنين ودعوة إلى التقوى. فكان ذكر تكفير السيئات مع الكافرين الذين هم في معصية مستديمة أولى من ذكره مع المؤمنين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص111–112.","url":""}]},{"id":"s64-37","number":37,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"ما سر الإجمال في ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ﴾، وقد زاد في الحديد: ﴿فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ﴾؟","answer":"فصّل في سورة الحديد أحوال الدنيا والآخرة في قوله: ﴿اعْلَمُوا أَنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ﴾ وما بعدها، ولم يرد مثل ذلك في التغابن، فزاد التفصيل هناك موافقةً لما قبلها وأجمل هنا. وهذا التوجيه منقول عن «البرهان» للكرماني.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص116–117.","url":""}]},{"id":"s64-38","number":38,"surah":64,"verses":[17],"references":[{"surah":64,"verses":[17]}],"verseLabel":"التغابن: 17","question":"ما سر التعبير بصيغة المبالغة في قوله: ﴿وَاللَّهُ شَكُورٌ حَلِيمٌ﴾ دون «شاكر»؟","answer":"كل ما ذكر الله فيه عن نفسه أنه «شكور» ورد في سياق مضاعفة الأجور والزيادة من فضله، وهنا قال: ﴿يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ﴾، فناسبته صيغة المبالغة. أما اسم الفاعل «شاكر» فيستعمله حيث لا يقتضي المقام المبالغة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص33. المصادر","url":""}]},{"id":"s64-39","number":39,"surah":64,"verses":[1],"references":[{"surah":64,"verses":[1]}],"verseLabel":"التغابن: 1","question":"ما دلالة افتتاح السورة بالفعل المضارع ﴿يُسَبِّحُ لِلَّهِ﴾، وقد افتُتحت الحديد والحشر والصف بالماضي ﴿سَبَّحَ﴾؟","answer":"كل سورة افتُتحت بالتسبيح بالفعل الماضي جرى فيها ذكر القتال، كالحديد والحشر والصف، وما افتُتح بالمضارع لا يُذكر فيه القتال، وسورة التغابن من القسم الثاني. وهي ملاحظة قائمة على الاستقراء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص202؛ ومن أسرار البيان القرآني، ص75.","url":""}]},{"id":"s64-40","number":40,"surah":64,"verses":[1],"references":[{"surah":64,"verses":[1]}],"verseLabel":"التغابن: 1","question":"ما سر تكرار «ما» في قوله: ﴿مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾؟","answer":"حيث كرّر «ما» في آيات التسبيح أعقب ذلك بالكلام على أهل الأرض، وهنا أعقبه بقوله: ﴿هُوَ الَّذِي خَلَقَكُمْ فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ ومضى في الكلام عليهم. وحيث لم يكررها لم يذكر بعدها شيئًا يتعلق بأهل الأرض.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص99؛ ومعاني النحو، ج1، ص146؛ وعلى طريق التفسير البياني، ج1، ص202–203.","url":""}]},{"id":"s64-41","number":41,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"ما سر تقديم السر على العلن في قوله: ﴿وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾؟","answer":"يُبدأ بالإخفاء حيث يجري الكلام على أهل الكفر، وبالإبداء حيث الخطاب للمؤمنين. وهذه الآية وإن لم تختص بالكافرين فقد جرى قبلها ﴿فَمِنْكُمْ كَافِرٌ﴾ وجرى بعدها مباشرة ذكر الكافرين: ﴿أَلَمْ يَأْتِكُمْ نَبَأُ الَّذِينَ كَفَرُوا﴾، فقدّم السر. وهذا التوجيه منقول عن «ملاك التأويل».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص266–268.","url":""}]},{"id":"s64-42","number":42,"surah":64,"verses":[8],"references":[{"surah":64,"verses":[8]}],"verseLabel":"التغابن: 8","question":"ما سر تقديم العمل على الخبرة في قوله: ﴿وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ﴾، وقد قال في النور: ﴿إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ﴾؟","answer":"إذا كان السياق في عمل الإنسان قدّم عمله، والكلام هنا على الإنسان وعمله: ﴿ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ﴾. أما آية النور ففي المنافقين، والنفاق أمر قلبي يحتاج إلى خبرة لمعرفة أصحابه، فقدّم وصفه سبحانه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص133–134.","url":""}]},{"id":"s64-43","number":43,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"ما سر إطلاق الفعل في قوله: ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ﴾ دون «ما أصابكم»؟","answer":"أطلق الفعل ولم يقيّده بمفعول معيّن لأنه أراد الإطلاق والعموم، فالكلام ليس خاصًا بالمخاطبين، بخلاف قوله في الشورى: ﴿وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾ إذ الكلام هناك يتعلق بهم. ومثله الإطلاق في آية الحديد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص282.","url":""}]},{"id":"s65-1","number":1,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"لماذا خوطب النبي مفردًا ثم قيل ﴿إِذَا طَلَّقْتُمُ النِّسَاءَ﴾ بالجمع؟","answer":"خص النبي بالنداء تشريفًا له باعتباره إمام أمته وقدوتها، ثم عم الحكم بضمير الجمع ليتناول المؤمنين. فالجمع بين النداء الخاص والخطاب العام يبرز مقام التبليغ والاقتداء، ويقرر أن أحكام الطلاق تشريع للأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص288–289، تحت عنوان «نكتة خصوصية لفظة ﴿النبي﴾ بالنداء»","url":""}]},{"id":"s65-2","number":2,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"ما دلالة اللام في قوله ﴿فطلقوهن لعدتهن﴾؟","answer":"اللام للتوقيت، أي طلقوهن مستقبلات لعدتهن، وذلك في طهر لم يقع فيه مسيس. فالتعبير يضبط زمن الطلاق بما تصح معه بداية العدة، ويمنع الإضرار بإطالتها بسبب الطلاق في غير وقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص293–294، تحت عنوان «معنى اللام في قوله: ﴿لعدتهن﴾»","url":""}]},{"id":"s65-3","number":3,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"لماذا أُمر المطلقون بإحصاء العدة لا بمجرد تذكرها؟","answer":"لأن الإحصاء ضبط دقيق يشمل بدء العدة ونهايتها وما يترتب عليها من حق الرجعة والسكنى والنفقة، لا مجرد حفظ رقم تقريبي. فاختيار اللفظ يحمي الحقوق ويمنع الخطأ في الحكم العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص314، تحت عنوان «الإحصاء والعد»","url":""}]},{"id":"s65-4","number":4,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"ما سرّ التعبير في قوله ﴿لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ﴾ فنسب البيوت إليهن؟","answer":"الإضافة باعتبار السكنى والاختصاص في مدة العدة، فلا تتوقف على ملكية المرأة للبيت. وهي تكرم المطلقة وتؤكد استحقاقها البقاء في مسكنها، فكأن البيت ما زال بيتها، مما يصونها ويعين على إمكان الرجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص299–300، تحت عنوان «نكتة إضافة البيوت إلى ضمير النساء»","url":""}]},{"id":"s65-5","number":5,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"ما سرّ الجمع بين ﴿لَا تُخْرِجُوهُنَّ﴾ و﴿وَلَا يَخْرُجْنَ﴾؟","answer":"الإخراج فعل الزوج، والخروج فعل المرأة، فجاء النهي متوجهًا إلى كل منهما ليصان حق السكنى من الطرفين. فلا يجوز للزوج أن يخرجها، ولا يكون ترك المسكن بمجرد اختيارها طريقًا إلى إهدار حكم العدة؛ وفي بقائها حفظ لفرصة الرجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص301، تحت عنوان «علة الجمع بين الإخراج ﴿لا تخرجوهن﴾ والخروج ﴿ولا يخرجن﴾»","url":""}]},{"id":"s65-6","number":6,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"ما الرجاء الذي تفتحه عبارة ﴿لَعَلَّ اللَّهَ يُحْدِثُ﴾ بعد الطلاق؟","answer":"تفتح باب الأمل في أن تتغير القلوب ويحدث ندم أو رغبة في الرجعة قبل انتهاء العدة؛ ولذلك شُرعت الإقامة وعدم الإخراج، فلا يغلق الغضب العابر طريق الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص311، تحت عنوان «نكتة التعبير بـ﴿لعل﴾ وبيان اسمها وخبرها»","url":""}]},{"id":"s65-19","number":19,"surah":65,"verses":[1],"references":[{"surah":65,"verses":[1]}],"verseLabel":"الطلاق: 1","question":"لماذا أبهم ما يحدثه الله بعد الطلاق بقوله ﴿أَمْرًا﴾؟","answer":"لأن ما يستجد قد يكون مودة أو رجعة أو سببًا آخر من وجوه الإصلاح التي لا يحيط بها الناس. واختيار لفظ عام منكر يعظم شأن المفاجأة ويترك أبواب التغيير الإلهي مفتوحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص312–313، تحت عنوان «سر اختيار لفظة ﴿أمرًا﴾ دون غيرها»","url":""}]},{"id":"s65-7","number":7,"surah":65,"verses":[2],"references":[{"surah":65,"verses":[2]}],"verseLabel":"الطلاق: 2","question":"ما سرّ تكرار ﴿بِمَعْرُوفٍ﴾ في الإمساك والمفارقة؟","answer":"تكرار «بمعروف» يجعل الإحسان قيدًا مستقلًا في الإمساك وفي المفارقة؛ فالمفارقة لا تبيح الإساءة، كما أن الإمساك لا يكون وسيلة إلى الضرر. وبهذا يمتد المعروف إلى حال انتهاء العلاقة كما يمتد إلى استمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص326، تحت عنوان «نكتة تكرار لفظة ﴿بمعروف﴾»","url":""}]},{"id":"s65-8","number":8,"surah":65,"verses":[2],"references":[{"surah":65,"verses":[2]}],"verseLabel":"الطلاق: 2","question":"لماذا اشترط في شاهدي الطلاق والرجعة أن يكونا ﴿ذَوَيْ عَدْلٍ﴾؟","answer":"لأن الشهادة تحفظ الحقوق وتمنع التنازع، فلا تؤدى إلا ممن عُرف بالاستقامة والإنصاف. والتثنية تقرر شاهدين تتوافر فيهما العدالة، و﴿منكم﴾ تربط الشهادة بجماعة المسلمين الموثوقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص329، تحت عنوان «نكتة التعبير بـ﴿ذوي عدل منكم﴾»","url":""}]},{"id":"s65-20","number":20,"surah":65,"verses":[2],"references":[{"surah":65,"verses":[2]}],"verseLabel":"الطلاق: 2","question":"ماذا يضيف وصف الشاهدين بـ﴿ذَوَيْ عَدْلٍ﴾ بدل «عادلين»؟","answer":"يجعل العدل كأنه ملكة راسخة يمتلكانها وتصدر عنها شهادتهما، لا وصفًا طارئًا قد يظهر مرة ويغيب أخرى؛ فيشدد في الثقة والأمانة المطلوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص329–330، تحت عنوان «نكتة التعبير بـ﴿ذوي عدل﴾ دون غيره كـ(عادلين)»","url":""}]},{"id":"s65-9","number":9,"surah":65,"verses":[2,3],"references":[{"surah":65,"verses":[2,3]}],"verseLabel":"الطلاق: 2–3","question":"لماذا جاء وعد التقوى بالمخرج والرزق في أثناء أحكام الطلاق؟","answer":"جاء اعتراضًا يثبت القلوب عند تنفيذ أحكام قد تثقلها المخاوف المادية والنفسية؛ فمن يلتزم حدود الله لا يضيعه الله، بل يجعل له فرجًا ورزقًا. وهكذا يقترن التكليف العملي بوعد يعين على الطاعة ولا يحصر أثر التقوى في الطلاق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص339، تحت عنوان «فائدة الاعتراض بقوله: ﴿ومن يتق الله﴾»","url":""}]},{"id":"s65-21","number":21,"surah":65,"verses":[2,3],"references":[{"surah":65,"verses":[2,3]}],"verseLabel":"الطلاق: 2–3","question":"لماذا جمع وعد المتقي بين المخرج والرزق؟","answer":"لأن الإنسان قد يخرج من الضيق ثم يبقى محتاجًا، فجمع الله له إزالة الكربة وإمداده بما تقوم به حياته. وفي سياق الطلاق يطمئن الطرفين إلى أن التقوى لا تضيق الرزق بل تفتح بعد العسر فرجًا وكفاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص343، تحت عنوان «علة الجمع بين جعل المخرج والرزق»","url":""}]},{"id":"s65-22","number":22,"surah":65,"verses":[2,3],"references":[{"surah":65,"verses":[2,3]}],"verseLabel":"الطلاق: 2–3","question":"ماذا يضيف قوله عن رزق المتقي ﴿مِنْ حَيْثُ لَا يَحْتَسِبُ﴾؟","answer":"ينفي حصر الرزق في الأسباب التي يعرفها الإنسان ويتوقعها؛ فقد يفتح الله له بابًا لم يخطر بباله. وفي ذلك حماية للوعد من أن يفهم على طريق واحد، وتقوية للتوكل مع الأخذ بالأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص344، تحت عنوان «بلاغة الاحتراس في قوله: ﴿من حيث لا يحتسب﴾»","url":""}]},{"id":"s65-10","number":10,"surah":65,"verses":[3],"references":[{"surah":65,"verses":[3]}],"verseLabel":"الطلاق: 3","question":"ماذا يطمئن المتوكل في قوله ﴿فَهُوَ حَسْبُهُ﴾؟","answer":"يطمئنه إلى أن الله كافيه ما أهمه، وأن هذه الكفاية ثابتة متجددة لا وعدًا عابرًا. فالجملة الاسمية تقوي اليقين بأن من صدق اعتماده على الله لن يضيعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص347، تحت عنوان «نكتة التعبير بالجملة الاسمية ﴿فهو حسبه﴾»","url":""}]},{"id":"s65-23","number":23,"surah":65,"verses":[3],"references":[{"surah":65,"verses":[3]}],"verseLabel":"الطلاق: 3","question":"لماذا أُتبع وعد المتوكل بقوله ﴿إِنَّ اللَّهَ بَالِغُ أَمْرِهِ﴾؟","answer":"ليبين أن كفاية الله ليست أمنية؛ فإرادته نافذة ولا يعجزها سبب أو مانع. وبذلك يجتمع في قلب المتوكل وعد الكفاية واليقين بقدرة من وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص347، تحت عنوان «نكتة فصل قوله: ﴿إن الله بالغ أمره﴾»","url":""}]},{"id":"s65-11","number":11,"surah":65,"verses":[3],"references":[{"surah":65,"verses":[3]}],"verseLabel":"الطلاق: 3","question":"لماذا ذُكر بعد التوكل أن الله ﴿قَدْ جَعَلَ لِكُلِّ شَيْءٍ قَدْرًا﴾؟","answer":"ليمنع التوكل من التحول إلى استعجال للنتيجة؛ فالله يبلغ أمره في الوقت والطريق اللذين قدرهما. على المتوكل أن يأخذ بالأسباب ويثق بالحكمة، لا أن يشترط صورة بعينها للفرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص351، تحت عنوان «دلالة الاستئناف البياني في قوله: ﴿قد جعل الله﴾»","url":""}]},{"id":"s65-24","number":24,"surah":65,"verses":[3],"references":[{"surah":65,"verses":[3]}],"verseLabel":"الطلاق: 3","question":"ماذا يعني أن الله جعل لكل شيء ﴿قَدْرًا﴾؟","answer":"يعني أنه وضع له مقدارًا ووقتًا وحدًّا تقتضيه الحكمة؛ فلا تدوم الشدة بلا نهاية ولا يأتي الفرج عبثًا. وهذا التقدير يثبت القلب ويمنع اليأس والاستعجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص353، تحت عنوان «دلالة التعبير بـ﴿قدرًا﴾ مادة وصيغة»","url":""}]},{"id":"s65-12","number":12,"surah":65,"verses":[4],"references":[{"surah":65,"verses":[4]}],"verseLabel":"الطلاق: 4","question":"لماذا عُلّق بيان عدة الآيسات بقوله ﴿إِنِ ارْتَبْتُمْ﴾ مع أن الحكم ثابت؟","answer":"لأن الارتياب هو سبب السؤال والحاجة إلى البيان، لا شرط ثبوت العدة. فالجملة تتجه إلى من التبس عليه حكم الآيسة أو الصغيرة، ثم ترفع الشك ببيان المدة، سواء وقع الشك بعد ذلك أم لم يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص361–362، تحت عنوان «فائدة التعبير بالجملة الشرطية ﴿إن ارتبتم﴾»","url":""}]},{"id":"s65-13","number":13,"surah":65,"verses":[4],"references":[{"surah":65,"verses":[4]}],"verseLabel":"الطلاق: 4","question":"لماذا تنتهي عدة الحامل بوضع حملها لا بعدد من الأشهر أو الأقراء؟","answer":"لأن المقصود الأهم من العدة التحقق من براءة الرحم وحفظ النسب، والحمل القائم لا تزول دلالته إلا بالوضع. فجُعل الأجل تابعًا للحقيقة التي من أجلها شرعت العدة، طال الحمل أو قصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص368، تحت عنوان «علة جعل خبر ﴿أولات الأحمال﴾ بالوضع لا بالأشهر أو الأقراء»","url":""}]},{"id":"s65-14","number":14,"surah":65,"verses":[5],"references":[{"surah":65,"verses":[5]}],"verseLabel":"الطلاق: 5","question":"لماذا تدرج جزاء التقوى من تيسير الأمر إلى تكفير السيئات ثم تعظيم الأجر؟","answer":"لأنه يجمع مصالح الدنيا والآخرة في ترتيب صاعد: ييسر الله للمتقي شأنه العاجل، ويمحو عنه تبعات ذنوبه، ثم يمنحه فوق النجاة أجرًا عظيمًا. فيرى أن التقوى لا تحل أزمة واحدة فحسب بل تصلح مصيره كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص383، تحت عنوان «نكتة الترتيب بين هذه الثمرات»","url":""}]},{"id":"s65-15","number":15,"surah":65,"verses":[6],"references":[{"surah":65,"verses":[6]}],"verseLabel":"الطلاق: 6","question":"ما معيار السكن الذي يجب توفيره للمطلقة في قوله ﴿مِنْ وُجْدِكُمْ﴾؟","answer":"المعيار أن تسكن بحسب سعة الزوج وقدرته وفي مستوى يقارب مسكنه، من غير تكليف بما لا يملك. فالحكم يوازن بين حقها في السكن وحال المنفق الواقعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص393، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من وجدكم﴾»","url":""}]},{"id":"s65-25","number":25,"surah":65,"verses":[6],"references":[{"surah":65,"verses":[6]}],"verseLabel":"الطلاق: 6","question":"لماذا نُهي الزوج عن مضارة المطلقة بعد الأمر بإسكانها؟","answer":"لئلا ينفذ حق السكن في الظاهر ثم يفرغه من مقصوده بالتضييق أو الإساءة حتى تضطر إلى الخروج أو إسقاط حقها. فالنهي يغلق باب التحايل ويجعل السكن أمانًا حقيقيًا لا صورة شكلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص394، تحت عنوان «دلالة النهي في الفعل وبلاغته»","url":""}]},{"id":"s65-16","number":16,"surah":65,"verses":[6],"references":[{"surah":65,"verses":[6]}],"verseLabel":"الطلاق: 6","question":"ماذا يطلب الأمر ﴿وَأْتَمِرُوا بَيْنَكُمْ﴾ من الأبوين في شأن الرضاع؟","answer":"يطلب منهما أن يتشاورا ويتوافقا في مصلحة الطفل وأجر الرضاع ومدته، بدل أن ينفرد أحدهما بالقرار أو يجعل الولد أداة للنزاع. فالمسؤولية مشتركة بعد الطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص402–403، تحت عنوان «دلالة الأمر في ﴿وأتمروا﴾، وبيان مرجع الضمير فيه»","url":""}]},{"id":"s65-26","number":26,"surah":65,"verses":[6],"references":[{"surah":65,"verses":[6]}],"verseLabel":"الطلاق: 6","question":"كيف يضبط ﴿الْمَعْرُوفِ﴾ تشاور الأبوين في الرضاع؟","answer":"يجعله قائمًا على العدل والعرف الحسن ومصلحة الطفل، بعيدًا عن التعنت والانتقام. فما اتفقا عليه يجب أن يكون مما تقبله الشريعة والإنصاف، لا مجرد اتفاق يضر أحد الأطراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص403، تحت عنوان «دلالة قيد الائتمار بمعروف»","url":""}]},{"id":"s65-17","number":17,"surah":65,"verses":[7],"references":[{"surah":65,"verses":[7]}],"verseLabel":"الطلاق: 7","question":"ما سر التعبير في الطلاق بـ﴿لا يكلف الله نفسًا إلا ما آتاها﴾، وفي البقرة بـ﴿لا يكلف الله نفسًا إلا وسعها﴾؟","answer":"في الطلاق يناسب ﴿ما آتاها﴾ سياق النفقة والسعة وضيق الرزق، فالتكليف متعلق بما أعطي الإنسان. وفي البقرة تناسب ﴿وسعها﴾ التخفيف عن المؤمنين في سياق التكليف والمحاسبة؛ فكل تعبير ملائم لسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص420، تحت عنوان «بيان المتشابه اللفظي بين عبارتي ﴿وسعها﴾ و﴿ما آتاها﴾»","url":""}]},{"id":"s65-18","number":18,"surah":65,"verses":[8,9,10,11,12],"references":[{"surah":65,"verses":[8,9,10,11,12]}],"verseLabel":"الطلاق: 8–12","question":"لماذا انتقلت سورة الطلاق من أحكام الأسرة إلى مصير القرى العاصية؟","answer":"لتخرج الأحكام من صورة تفاصيل اجتماعية إلى كونها حدودًا لله لا يجوز التهاون بها. فذكر القرى التي عتت عن أمر ربها يحذر من عاقبة مخالفة التشريع، ويبين أن صلاح المجتمع يبدأ بطاعة الله في أدق شؤونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص425، تحت عنوان «نوع الواو ودلالتها في صدر الآية»","url":""}]},{"id":"s65-27","number":27,"surah":65,"verses":[8,9,10,11,12],"references":[{"surah":65,"verses":[8,9,10,11,12]}],"verseLabel":"الطلاق: 8–12","question":"لماذا استؤنف في آخر سورة الطلاق الحديث عن خلق السماوات والأرض؟","answer":"ليدل اتساع القدرة والتدبير في الكون على قدرة الله على إنفاذ أحكامه وجزائه، وليوقظ القلب بعد تفاصيل التشريع إلى عظمة المشرع المحيط علمًا بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص470، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s65-28","number":28,"surah":65,"verses":[8,9,10,11,12],"references":[{"surah":65,"verses":[8,9,10,11,12]}],"verseLabel":"الطلاق: 8–12","question":"كيف تربط خاتمة سورة الطلاق خلق السماوات والأرض بموضوعها؟","answer":"تربط قوانين الأسرة بربوبية من خلق الكون ودبره بقدر؛ فالذي أحكم السماوات والأرض هو الأعلم بما يصلح حياة الناس، وقدرته وعلمه ضمان لوعد المتقي ووعيد المتجاوز. وهكذا تعود الخاتمة إلى التقوى والحدود التي بنيت عليها السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص481، تحت عنوان «وجه ارتباط خاتمة السورة بمطلعها وموضوعها»","url":""}]},{"id":"s65-29","number":29,"surah":65,"verses":[4],"references":[{"surah":65,"verses":[4]}],"verseLabel":"الطلاق: 4","question":"ما سر التعبير بـ«أشهر» في قوله: ﴿فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ﴾ دون «شهور»؟","answer":"«أشهر» جمع قلة و«شهور» جمع كثرة، فاستعمل القرآن «الأشهر» للقلة كما هنا وفي ﴿الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ﴾ و﴿أَرْبَعَةَ أَشْهُرٍ﴾، واستعمل «الشهور» لما زاد على العشرة في ﴿إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا﴾.","sources":[{"label":"فاضل السامرائي، الصرف العربي أحكام ومعان، ص155؛ ومعاني الأبنية في العربية، ص119.","url":""}]},{"id":"s65-30","number":30,"surah":65,"verses":[4,6],"references":[{"surah":65,"verses":[4,6]}],"verseLabel":"الطلاق: 4، 6","question":"ما سر الجمع في ﴿وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ﴾، والإفراد في ﴿وَإِنْ كُنَّ أُولَاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ﴾؟","answer":"الآيتان في المطلَّقات، غير أن الأولى عامة لا تفاوت فيها، فكل أولات الأحمال أجلهن وضع الحمل فجمع. أما الثانية فهن متفاوتات في مقدار النفقة بحسب سعة الزوج، وفي التوافق على الإرضاع أو التعاسر، فلما شمل الحكم بعضًا دون بعض جاء بالمفرد الذي هو أقل في الدلالة من الجمع.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص104–106.","url":""}]},{"id":"s65-31","number":31,"surah":65,"verses":[8],"references":[{"surah":65,"verses":[8]}],"verseLabel":"الطلاق: 8","question":"ما دلالة التعبير بـ«كأيِّن» في قوله: ﴿وَكَأَيِّنْ مِنْ قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِ﴾ دون «كم»؟","answer":"«كأيّن» تُستعمل في مواطن التفخيم والتعظيم إضافة إلى التكثير، كأنه قال: وكم من قرية أيّة قرية، وفي «أي» المبهمة إشعار بذلك. والتفخيم هنا لله الذي أخذ مثل هذه القرى المتجبرة العاتية، وليس السياق كذلك في آية الأعراف ﴿وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا﴾.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص342–343.","url":""}]},{"id":"s65-32","number":32,"surah":65,"verses":[8],"references":[{"surah":65,"verses":[8]}],"verseLabel":"الطلاق: 8","question":"ما سر قوله: ﴿عَذَابًا نُكْرًا﴾ بسكون الكاف، وقد قال في القمر: ﴿إِلَى شَيْءٍ نُكُرٍ﴾ بضمتين؟","answer":"«نُكُر» بضمتين أشدّ وأثقل من «نُكْر» لما فيه من توالي ثقيلين، وموقف القمر هول القيامة الذي لم يُعهد له نظير. أما عقوبات آية الطلاق ففي الدنيا، فليست نكارتها كنكارة عذاب الآخرة، فجعل الوصف أخف، وليس ذلك للفاصلة فقط.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص170–171.","url":""}]},{"id":"s65-33","number":33,"surah":65,"verses":[9],"references":[{"surah":65,"verses":[9]}],"verseLabel":"الطلاق: 9","question":"ما دلالة التعبير بـ«الخُسْر» في قوله: ﴿وَكَانَ عَاقِبَةُ أَمْرِهَا خُسْرًا﴾ دون «خَسَارًا» أو «خُسْرَانًا»؟","answer":"استعمل القرآن «الخُسر» لعموم الخسارة قليلةً كانت أو كثيرة، فهو لمطلق الخسارة، وهي هنا خسارة كبيرة. أما «الخَسار» فاستعمله للزيادة على الخسارة القائمة، كقوله: ﴿وَلَا يَزِيدُ الظَّالِمِينَ إِلَّا خَسَارًا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص12–13.","url":""}]},{"id":"s65-34","number":34,"surah":65,"verses":[11],"references":[{"surah":65,"verses":[11]}],"verseLabel":"الطلاق: 11","question":"ما سر الإفراد في ﴿وَمَنْ يُؤْمِنْ بِاللَّهِ … يُدْخِلْهُ﴾ ثم الجمع في ﴿خَالِدِينَ فِيهَا﴾ ثم الإفراد في ﴿قَدْ أَحْسَنَ اللَّهُ لَهُ رِزْقًا﴾؟","answer":"حمل أولًا على لفظ «مَن» ثم على معناها في ﴿خَالِدِينَ﴾ ليدل على أنهم جمع لا واحد، ولأن الاجتماع أدنى إلى الأنس فهو زيادة في الإنعام. ثم عاد إلى الإفراد في ﴿لَهُ رِزْقًا﴾ للدلالة على رعاية كل فرد بعينه، فلا يضيع في غمرة الكثرة.","sources":[{"label":"فاضل السامرائي، الجملة العربية والمعنى، ص124–125.","url":""}]},{"id":"s65-35","number":35,"surah":65,"verses":[11],"references":[{"surah":65,"verses":[11]}],"verseLabel":"الطلاق: 11","question":"ما سر الاقتصار على ﴿يُدْخِلْهُ جَنَّاتٍ﴾ هنا، وقد زاد في التغابن: ﴿يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ﴾؟","answer":"آية الطلاق خطاب للمؤمنين ودعوة إلى التقوى: ﴿فَاتَّقُوا اللَّهَ يَا أُولِي الْأَلْبَابِ الَّذِينَ آمَنُوا﴾، وآية التغابن خطاب للكافرين ودعوة لهم إلى الإيمان. فكان ذكر تكفير السيئات مع الكافرين الذين هم في معصية مستديمة أولى من ذكره مع المؤمنين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص111–112.","url":""}]},{"id":"s66-1","number":1,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"لماذا نودي الرسول ﷺ بوصف النبوة في ﴿يَا أَيُّهَا النَّبِيُّ﴾ لا باسمه؟","answer":"لتشريفه باستحضار منزلته ووظيفته قبل العتاب، والتنبيه إلى أن ما يوجه إليه متصل بمقام النبوة وتربية الأمة، مع ما في الوصف من توقير وتأنيس.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص495–496، تحت عنوان «غرض النداء بوصف النبوة دون اسم العلم»","url":""}]},{"id":"s66-19","number":19,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"لماذا سبق النداءُ عتابَ النبي ﷺ في أول سورة التحريم؟","answer":"ليدخل العتاب من باب التكريم والقرب، فلا يفاجأ به مجردًا؛ وفيه إظهار للعناية به قبل سؤاله عن تحريم ما أحل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص495، تحت عنوان «بلاغة تقديم النداء على العتاب»","url":""}]},{"id":"s66-2","number":2,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"لماذا جاء العتاب في صورة سؤال ﴿لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ﴾ بدل النهي «لا تحرم»؟","answer":"لأن السؤال ألطف في المعاتبة وأبعث على مراجعة السبب، وفي الوقت نفسه ينكر أن يُترك المباح طلبًا لرضا غير الله؛ فجمع التلطف والتنبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص497–498، تحت عنوان «بلاغة الاستفهام وغرضه»","url":""}]},{"id":"s66-20","number":20,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"لماذا سُمّي امتناع النبي ﷺ عن المباح ﴿تَحْرِيمًا﴾؟","answer":"لأنه ألزم نفسه ترك ما أحل الله فصار الامتناع في أثره كالمحرّم عليه، مع أن الحكم الشرعي العام لم يتغير؛ فالاستعارة تشدد في النهي عن التضييق على النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص498، تحت عنوان «بلاغة الاستعارة في التعبير بالتحريم عن الامتناع»","url":""}]},{"id":"s66-3","number":3,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"لماذا خُتم عتاب النبي ﷺ بقوله ﴿وَاللَّهُ غَفُورٌ رَحِيمٌ﴾؟","answer":"ليغلب التأنيس بعد العتاب، ويفتح باب التجاوز عن هذا الاجتهاد، ويقرر أن توجيه الله لعبده صادر عن مغفرة ورحمة لا عن إبعاد أو إهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص505، تحت عنوان «بلاغة التذييل بالاسمين الجليلين»","url":""}]},{"id":"s66-4","number":4,"surah":66,"verses":[2],"references":[{"surah":66,"verses":[2]}],"verseLabel":"التحريم: 2","question":"ماذا يفيد قوله ﴿قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ﴾؟","answer":"يفيد أن الله شرع طريقًا معلومًا للخروج من اليمين بالكفارة، فلم يترك العبد أسير ما حلف عليه إذا ظهر أن الخير في خلافه؛ وفي ﴿فرض﴾ معنى التقدير والتشريع الملزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص509، تحت عنوان «دلالة استعمال مفردة ﴿فرض﴾»","url":""}]},{"id":"s66-21","number":21,"surah":66,"verses":[2],"references":[{"surah":66,"verses":[2]}],"verseLabel":"التحريم: 2","question":"لماذا سُمّيت كفارة اليمين ﴿تَحِلَّةً﴾؟","answer":"لأنها تحل عقد اليمين وتفتح للحالف الرجوع إلى المباح بعد أن ألزم نفسه، فاللفظ يصور اليمين كعقدة لها حل شرعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص511، تحت عنوان «سر التعبير بمفردة ﴿تحلة﴾ مادة وصيغة»","url":""}]},{"id":"s66-5","number":5,"surah":66,"verses":[2],"references":[{"surah":66,"verses":[2]}],"verseLabel":"التحريم: 2","question":"لماذا ذُكِّر المؤمنون بعد تشريع الكفارة بأن ﴿اللَّهُ مَوْلَاكُمْ﴾؟","answer":"لأن الذي شرع التحلة هو وليهم المتكفل بتربيتهم ونصرتهم وتدبير مصالحهم؛ فحكمه تيسير صادر عن رعاية، لا إطلاق للأهواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص514، تحت عنوان «بلاغة الكناية في استعمال مفردة (المولى)»","url":""}]},{"id":"s66-22","number":22,"surah":66,"verses":[2],"references":[{"surah":66,"verses":[2]}],"verseLabel":"التحريم: 2","question":"ما مناسبة ختم حكم الأيمان بقوله ﴿وَهُوَ الْعَلِيمُ الْحَكِيمُ﴾؟","answer":"هو عليم بما يصلح عباده وبما عقدته نياتهم، حكيم في تشريع الكفارة ووضعها موضعها؛ فتطمئن النفس إلى أن الرخصة قائمة على علم وحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص515، تحت عنوان «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s66-6","number":6,"surah":66,"verses":[3],"references":[{"surah":66,"verses":[3]}],"verseLabel":"التحريم: 3","question":"ما سرّ التعبير بقوله ﴿أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ حَدِيثًا﴾ دون تسمية الزوجة؟","answer":"الإبهام بـ«بعض» يحقق الستر ويجنب التشهير، ويصرف العناية من تعيين صاحبة الواقعة إلى أدب كتمان السر والعبرة من الحادثة. كما أن اللفظ يقصر نسبة الفعل على بعض الأزواج فلا ينسبه إليهن جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص523، تحت عنوان «فائدة الإبهام بلفظ ﴿بعض﴾ دون التعيين»","url":""}]},{"id":"s66-7","number":7,"surah":66,"verses":[3],"references":[{"surah":66,"verses":[3]}],"verseLabel":"التحريم: 3","question":"ماذا تكشف المقابلة في ﴿عَرَّفَ بَعْضَهُ وَأَعْرَضَ عَنْ بَعْضٍ﴾ عن أدب النبي ﷺ؟","answer":"تكشف أنه واجه بما يكفي لإثبات علمه بالسر، وتجاوز عن بعضه كرمًا وحلمًا؛ فجمع بين إظهار الحقيقة وصيانة المخطئ من استقصاء الفضيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص530، تحت عنوان «بلاغة المقابلة بين التعريف والإعراض»","url":""}]},{"id":"s66-8","number":8,"surah":66,"verses":[4],"references":[{"surah":66,"verses":[4]}],"verseLabel":"التحريم: 4","question":"لماذا بدأ الخطاب للزوجتين بالحث على التوبة قبل التحذير من التظاهر؟","answer":"لأن المقصود إصلاح الحال وفتح طريق الرجوع قبل الوعيد، ولأن ميل القلب الذي وقع منهما أولى ما يعالج؛ فإن لم تتوبا جاء التحذير من التناصر على النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص540، تحت عنوان «سر تقديم ذكر الحث على التوبة على التظاهر»","url":""}]},{"id":"s66-9","number":9,"surah":66,"verses":[4],"references":[{"surah":66,"verses":[4]}],"verseLabel":"التحريم: 4","question":"لماذا وُسِّط ﴿صَالِحُ الْمُؤْمِنِينَ﴾ بين جبريل والملائكة في نصرة النبي ﷺ؟","answer":"لرفع منزلة المؤمنين الصالحين وإدخال نصرتهم في هذا الموكب العظيم، مع الإشارة إلى أن تأييد النبي يجمع أعظم مَلَك وخيرة البشر ثم عموم الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص550، تحت عنوان «فائدة توسيط ﴿وصالح المؤمنين﴾ بين جبريل والملائكة»","url":""}]},{"id":"s66-10","number":10,"surah":66,"verses":[5],"references":[{"surah":66,"verses":[5]}],"verseLabel":"التحريم: 5","question":"لماذا قُدّم الإسلام على الإيمان في صفات الزوجات الصالحات؟","answer":"لأن الإسلام يظهر في الانقياد والعمل، ثم يأتي الإيمان باطنًا مصدقًا له؛ أو لأن الإسلام أساس الدخول في الطاعة ثم ترتقي الصفات إلى رسوخ القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص564، تحت عنوان «نكتة تقديم الإسلام على الإيمان»","url":""}]},{"id":"s66-23","number":23,"surah":66,"verses":[5],"references":[{"surah":66,"verses":[5]}],"verseLabel":"التحريم: 5","question":"ما الحكمة في ترتيب صفات الزوجات: ﴿مُسْلِمَاتٍ مُؤْمِنَاتٍ قَانِتَاتٍ تَائِبَاتٍ عَابِدَاتٍ سَائِحَاتٍ﴾؟","answer":"ينتقل الترتيب من أصل الانقياد والتصديق إلى دوام الطاعة، ثم تصحيح الزلل بالتوبة، ثم رسوخ العبادة ومجاهدة النفس؛ فترسم الصفات بناء الصلاح من الأصل إلى آثاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص566–567، تحت عنوان «بلاغة ترتيب ذكر الصفات»","url":""}]},{"id":"s66-11","number":11,"surah":66,"verses":[6],"references":[{"surah":66,"verses":[6]}],"verseLabel":"التحريم: 6","question":"لماذا بدأ الأمر بالوقاية من النار بالنفس قبل الأهل؟","answer":"لأن الإنسان مسؤول عن إصلاح نفسه أولًا، وبصلاحها يقدر على تعليم أهله وقدوتهم؛ فلا يستقيم أن يطلب نجاتهم وهو مهمل نجاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص575، تحت عنوان «غرض تقديم النفس على الأهل»","url":""}]},{"id":"s66-24","number":24,"surah":66,"verses":[6],"references":[{"surah":66,"verses":[6]}],"verseLabel":"التحريم: 6","question":"ماذا يضيف عطف الأهل في قوله ﴿قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا﴾؟","answer":"يوسع المسؤولية من النجاة الفردية إلى رعاية البيت بالتعليم والتأديب والدعوة، فلا يكتفي المؤمن بصلاحه ويترك من تحت ولايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص575، تحت عنوان «دلالة عطف الأهلين على الأنفس»","url":""}]},{"id":"s66-12","number":12,"surah":66,"verses":[6],"references":[{"surah":66,"verses":[6]}],"verseLabel":"التحريم: 6","question":"لماذا وصفت النار بأن وقودها ﴿النَّاسُ وَالْحِجَارَةُ﴾؟","answer":"في اقتران الناس بالحجارة تهويل للنار وإهانة لمن يدخلها؛ فيُقرن العابد بمعبوده، ويُحتمل أن تكون الحجارة مما يشتد احتراقه فيزيد صورة النار هولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص579، تحت عنوان «نكتة قرن ﴿الناس﴾ بالحجارة في الذكر»","url":""}]},{"id":"s66-13","number":13,"surah":66,"verses":[6],"references":[{"surah":66,"verses":[6]}],"verseLabel":"التحريم: 6","question":"لماذا جُمع في وصف الملائكة بين ﴿لَا يَعْصُونَ اللَّهَ﴾ و﴿يَفْعَلُونَ مَا يُؤْمَرُونَ﴾؟","answer":"نفي العصيان يزيل كل احتمال للتردد أو المخالفة، وإثبات الفعل يقرر تنفيذ الأمر كاملًا كما وُجه إليهم؛ فليس وصفهم مجرد ترك للمعصية بل طاعة إيجابية تامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص583، تحت عنوان «بلاغة السلب والإيجاب»","url":""}]},{"id":"s66-14","number":14,"surah":66,"verses":[8],"references":[{"surah":66,"verses":[8]}],"verseLabel":"التحريم: 8","question":"ما الذي يجعل التوبة ﴿نَصُوحًا﴾؟","answer":"أن تكون خالصة صادقة تقلع عن الذنب وتندم عليه وتعزم ألا تعود إليه، وتصلح ما أفسده؛ فهي توبة تنصح صاحبها ولا تغشه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص599–600، تحت عنوان «دلالة الوصف بـ﴿نصوحًا﴾ مادة وصيغة»","url":""}]},{"id":"s66-25","number":25,"surah":66,"verses":[8],"references":[{"surah":66,"verses":[8]}],"verseLabel":"التحريم: 8","question":"ما الصورة في وصف التوبة بأنها ﴿نَصُوحًا﴾؟","answer":"تصور التوبة ناصحًا أمينًا يدعو صاحبها إلى ما ينجيه، أو تصورها خياطة تصلح ما مزقه الذنب في الدين؛ فتتجاوز مجرد الندم إلى إصلاح حقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص600–601، تحت عنوان «بلاغة الاستعارة في التعبير بالنصح»","url":""}]},{"id":"s66-15","number":15,"surah":66,"verses":[8],"references":[{"surah":66,"verses":[8]}],"verseLabel":"التحريم: 8","question":"لماذا يقول المؤمنون ﴿رَبَّنَا أَتْمِمْ لَنَا نُورَنَا﴾ مع أن نورهم يسعى؟","answer":"لأن هول الموقف ورؤية انطفاء نور المنافقين يدفعانهم إلى طلب دوام نورهم حتى يبلغ بهم الجنة؛ فليس الدعاء إنكارًا لما معهم بل افتقارًا إلى تثبيت النعمة وإكمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص617–618، تحت عنوان «دلالة فصل قوله ﴿يقولون ربنا أتمم لنا نورنا﴾»","url":""}]},{"id":"s66-26","number":26,"surah":66,"verses":[8],"references":[{"surah":66,"verses":[8]}],"verseLabel":"التحريم: 8","question":"ماذا يفيد طلب المؤمنين ﴿أَتْمِمْ لَنَا نُورَنَا﴾؟","answer":"يفيد سؤال بلوغ النور غايته واستمراره بلا انقطاع حتى يتم العبور والنجاة، ويكشف أنهم لا يغترون بما ظهر لهم بل يسألون الله تمام الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص619، تحت عنوان «دلالة فعل الطلب بقوله ﴿أتمم﴾»","url":""}]},{"id":"s66-16","number":16,"surah":66,"verses":[10],"references":[{"surah":66,"verses":[10]}],"verseLabel":"التحريم: 10","question":"لماذا ضُرب المثل بزوجتي نوح ولوط دون غيرهما من قرابة الأنبياء؟","answer":"لأن الزوجية من أوثق الصلات وأقربها، فإذا لم تنفع مع الكفر كان ذلك أبلغ في هدم الاتكال على النسب والقرب، وتحذيرًا لكل من جاور الصالحين بلا طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص643، تحت عنوان «علة الاقتصار على الزوجتين دون غيرهما من قرابة الأنبياء»","url":""}]},{"id":"s66-27","number":27,"surah":66,"verses":[10],"references":[{"surah":66,"verses":[10]}],"verseLabel":"التحريم: 10","question":"ما المقصود بخيانة امرأتي نوح ولوط؟","answer":"هي خيانة الدين والرسالة بإفشاء السر أو إعانة المكذبين، وليست خيانة العرض؛ فاختيار اللفظ يصور نقضهما لحق الصحبة والإيمان مع قربهما من نبيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص649–650، تحت عنوان «نكتة التعبير بلفظ الخيانة دون غيرها»","url":""}]},{"id":"s66-17","number":17,"surah":66,"verses":[11],"references":[{"surah":66,"verses":[11]}],"verseLabel":"التحريم: 11","question":"ما الذي تكشفه المقابلة بين امرأتي نوح ولوط وامرأة فرعون؟","answer":"تكشف أن القرب من نبي لا ينجي مع الكفر، كما أن الارتباط بطاغية لا يضر مع صدق الإيمان؛ فالمعيار عمل الإنسان وعقيدته لا رابطة الزوجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص655، تحت عنوان «بلاغة المقابلة بين المثلين المضروبين»","url":""}]},{"id":"s66-18","number":18,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"لماذا عُبر عن عفة مريم بقوله ﴿أَحْصَنَتْ فَرْجَهَا﴾؟","answer":"كنى بأشد موضع الستر عن تمام العفة وصيانتها نفسها من الحرام، فجاء التعبير موجزًا عفيفًا يرفع منزلتها ويدفع الافتراء عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص668، تحت عنوان «بلاغة المجاز والكناية في قوله: ﴿فرجها﴾»","url":""}]},{"id":"s66-28","number":28,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ماذا تضيف نسبة الروح إلى الله في قوله ﴿مِنْ رُوحِنَا﴾؟","answer":"هي إضافة تشريف وتكريم للروح الذي كان به خلق عيسى، لا إضافة جزء أو حلول؛ فتربط المعجزة بأمر الله وقدرته وتكرم المخلوق المضاف إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص671، تحت عنوان «نكتة الإضافة في ﴿روحنا﴾»","url":""}]},{"id":"s66-29","number":29,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"لماذا قيل عن مريم ﴿وَكَانَتْ مِنَ الْقَانِتِينَ﴾ بجمع التذكير؟","answer":"لإدخالها في جماعة القانتين عامة من الرجال والنساء، ورفعها إلى سلك أهل الطاعة الكاملين؛ فالمقصود الجنس الإنساني لا الذكور وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص674–675، تحت عنوان «نكتة ذكر القانتين بجمع التذكير دون التأنيث»","url":""}]},{"id":"s66-30","number":30,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"ما سر التعبير بـ«المرضاة» في قوله: ﴿تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ﴾ دون «الرضوان»؟","answer":"الرضوان أكبر الرضا وأعظمه، ولذلك اختص في القرآن برضا الله ولم يُستعمل مع غيره. أما المرضاة فعامة في مرضاة الله وغيره، خاصة بالابتغاء، ولذا استُعملت هنا في مرضاة الأزواج.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص14–15.","url":""}]},{"id":"s66-31","number":31,"surah":66,"verses":[3],"references":[{"surah":66,"verses":[3]}],"verseLabel":"التحريم: 3","question":"ما سر التعبير بـ﴿نَبَّأَتْ بِهِ﴾ ثم ﴿مَنْ أَنْبَأَكَ هَذَا﴾ ثم ﴿نَبَّأَنِيَ الْعَلِيمُ الْخَبِيرُ﴾؟","answer":"«نبّأ» يقتضي تنبيئًا أكثر من «أنبأ»، كـ«علّم وأعلم». فلما عرّف بعض الحديث وأعرض عن بعض كأنما ذكر قسمًا من النبأ، فقالت: ﴿مَنْ أَنْبَأَكَ هَذَا﴾ أي هذا الجزء منه، فذكر أن العليم الخبير نبّأه به كله.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص106.","url":""}]},{"id":"s66-32","number":32,"surah":66,"verses":[4],"references":[{"surah":66,"verses":[4]}],"verseLabel":"التحريم: 4","question":"ما سر الجمع في قوله: ﴿فَقَدْ صَغَتْ قُلُوبُكُمَا﴾ والقياس «قلباكما»؟","answer":"المثنى المضاف إلى متضمّنه الأحسن أن يُعبَّر عنه بالجمع، كـ«قطعت رؤوس الكبشين»، وذلك لكراهة اجتماع تثنيتين ما لم يُؤدّ إلى اللبس، إذ ليس لكل واحدة منهما إلا قلب واحد. وفي «الكتاب» لسيبويه و«شرح الرضي» نحو هذا.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص123؛ والجملة العربية والمعنى، ص136.","url":""}]},{"id":"s66-33","number":33,"surah":66,"verses":[4],"references":[{"surah":66,"verses":[4]}],"verseLabel":"التحريم: 4","question":"ما سر مجيء الشرط بالمضارع في قوله: ﴿إِنْ تَتُوبَا إِلَى اللَّهِ﴾، وقد جاء بالماضي في ﴿فَإِنْ تَابُوا﴾ و﴿فَإِنْ تَابَا﴾؟","answer":"الماضي في آيتي التوبة والنساء للتوبة العامة، كالدخول في الإسلام أو الانخلاع عن الفاحشة. أما هنا فالكلام موجه إلى زوجَي النبي، والمقصود التوبة الجزئية العارضة التي يتكرر أمثالها من الوقوع في اللمم والصغائر، فجاء بالمضارع الدال على التجدد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص59–60.","url":""}]},{"id":"s66-34","number":34,"surah":66,"verses":[5],"references":[{"surah":66,"verses":[5]}],"verseLabel":"التحريم: 5","question":"ما سر التعبير باسم الفاعل في ﴿تَائِبَاتٍ﴾ دون صيغة المبالغة «توّابات»؟","answer":"جاءت الآية تعقيبًا على حديث السر وما وقع من بعض أزواج النبي مما يقع بين الضرائر، وهذا تكفي فيه التوبة ولا يستدعي المبالغة فيها. فالمبالغة في التوبة تكون من الآثام الكبيرة، إذ التوبة على قدر الذنب، بخلاف ﴿إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ﴾ في البقرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص30.","url":""}]},{"id":"s66-35","number":35,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ما سر ضمير الجمع في ﴿فَنَفَخْنَا فِيهِ مِنْ رُوحِنَا﴾، وقد قال في آدم: ﴿وَنَفَخْتُ فِيهِ مِنْ رُوحِي﴾؟","answer":"لأن النافخ في مريم هو رسوله الذي تمثّل لها بشرًا سويًا، وليس الأمر كذلك في آدم، فجاء فيه بضمير الإفراد: ﴿وَنَفَخْتُ﴾ و﴿وَنَفَخَ فِيهِ مِنْ رُوحِهِ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص161.","url":""}]},{"id":"s66-36","number":36,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ما سر قوله: ﴿فَنَفَخْنَا فِيهِ﴾ هنا، و﴿فَنَفَخْنَا فِيهَا﴾ في الأنبياء؟","answer":"﴿فِيهَا﴾ أعمّ لأنه يعمّها كلها، و﴿فِيهِ﴾ أخصّ لأنه أشار إلى موضع النفخ. وآية التحريم أخصّ لأنها عيّنتها بالاسم والوصف، وآية الأنبياء أعمّ لأنها بالوصف وحده وذكرت ابنها معها، فناسب العمومُ العمومَ والخصوصُ الخصوصَ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص160.","url":""}]},{"id":"s66-37","number":37,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ما سر التصريح باسم مريم في ﴿وَمَرْيَمَ ابْنَتَ عِمْرَانَ الَّتِي أَحْصَنَتْ فَرْجَهَا﴾، والاكتفاء بالصفة في الأنبياء: ﴿وَالَّتِي أَحْصَنَتْ فَرْجَهَا﴾؟","answer":"السياق في الأنبياء في ذكر الأنبياء وهي ليست منهم فلم يصرّح باسمها، والسياق في التحريم في ذكر النساء: أزواج النبي، وامرأة نوح وامرأة لوط وامرأة فرعون، فناسب ذكر اسمها. ثم إن التصريح بالاسم أبلغ في المدح، وهي أعلى المذكورات في سياقها هنا، وأقل المذكورين منزلة في سياق الأنبياء.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص159–160.","url":""}]},{"id":"s66-38","number":38,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ما سر عدم ذكر ابنها هنا، وقد قال في الأنبياء: ﴿وَجَعَلْنَاهَا وَابْنَهَا آيَةً لِلْعَالَمِينَ﴾؟","answer":"السياق في سورة الأنبياء في ذكر الأنبياء وابنها واحد منهم، وقد ذكر فيها ابن إبراهيم وابن ابنه، فناسب ذكره. أما في سورة التحريم فالسياق في ذكر النساء فلا يناسب ذكره فيه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص161.","url":""}]},{"id":"s67-2","number":2,"surah":67,"verses":[1],"references":[{"surah":67,"verses":[1]}],"verseLabel":"الملك: 1","question":"ما دلالة تقديم ﴿بِيَدِهِ﴾ في قوله ﴿بِيَدِهِ الْمُلْكُ﴾؟","answer":"تقديم «بيده» يفيد القصر والاختصاص، أي أن الملك الكامل الذي لا يزول لله وحده. وما يملكه الخلق محدود معرض للنقص والزوال، فلا يعتد به في جانب ملكه المحيط بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص697، تحت عنوان «سر تقديم خبر صلة الموصول على المبتدأ»","url":""}]},{"id":"s67-3","number":3,"surah":67,"verses":[2],"references":[{"surah":67,"verses":[2]}],"verseLabel":"الملك: 2","question":"ما سرّ تقديم الموت على الحياة في ﴿خَلَقَ الْمَوْتَ وَالْحَيَاةَ﴾؟","answer":"تذكر الموسوعة وجهين: سبق حال عدم الحياة على وجودها في الإنسان، وأن ذكر الموت أدعى إلى الزجر وأقوى في التحذير، إذ يدعو إلى قصر الأمل والاستعداد بالعمل. فالتقديم يناسب غرض الابتلاء والحث على إحسان العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص707–708، تحت عنوان «سر تقديم الموت على الحياة في الذكر»","url":""}]},{"id":"s67-4","number":4,"surah":67,"verses":[2],"references":[{"surah":67,"verses":[2]}],"verseLabel":"الملك: 2","question":"ما سرّ التعبير في قوله ﴿أَيُّكُمْ أَحْسَنُ عَمَلًا﴾ لا «أكثر عملًا»؟","answer":"وجّه التعبير النظر إلى حسن العمل والترقي في مراتبه، لا إلى مجرد كثرته؛ فالابتلاء يميز إحسان الطاعة ويحفز المؤمنين إلى بلوغ مراتب الإحسان بدل الاكتفاء بالحد الأدنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص713، تحت عنوان «سر تخصيص الابتلاء والمفاضلة فيما ابتلوا فيه على الأعمال الحسنة»","url":""}]},{"id":"s67-5","number":5,"surah":67,"verses":[2],"references":[{"surah":67,"verses":[2]}],"verseLabel":"الملك: 2","question":"لماذا خُتمت آية الابتلاء باسمَي ﴿الْعَزِيزُ الْغَفُورُ﴾؟","answer":"ليجمع المختبَر بين الخوف والرجاء: فالله عزيز قادر على محاسبة من أساء، وغفور يفتح باب الرجوع لمن قصر ثم تاب. واجتماعهما يمنع الاغترار بالمهلة كما يمنع اليأس من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص715–716، تحت عنوان «مناسبة اختيار الاسمين الجليلين في هذا المقام»","url":""}]},{"id":"s67-6","number":6,"surah":67,"verses":[3],"references":[{"surah":67,"verses":[3]}],"verseLabel":"الملك: 3","question":"ما الصورة في وصف السماوات السبع بأنها ﴿طِبَاقًا﴾؟","answer":"يصورها طبقات متوافقة، بعضها فوق بعض، من غير اضطراب أو تصادم. فالكلمة تجمع تعدد السماوات مع إحكام نظامها، وتوجه النظر إلى قدرة الخالق الذي أقام هذا البناء المتناسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص724–725، تحت عنوان «دلالة وصف السبعة بأنها ﴿طباقًا﴾»","url":""}]},{"id":"s67-7","number":7,"surah":67,"verses":[3],"references":[{"surah":67,"verses":[3]}],"verseLabel":"الملك: 3","question":"لماذا نسب الخلق هنا إلى ﴿الرَّحْمَنِ﴾ في ﴿مَا تَرَى فِي خَلْقِ الرَّحْمَنِ مِنْ تَفَاوُتٍ﴾؟","answer":"اسم الرحمن يربط إحكام الخلق وسلامته من التفاوت برحمة الله، إذ هيأ الكون لمنافع خلقه. وفي اختياره أيضًا تعريض بالمشركين الذين أنكروا هذا الاسم مع ظهور آثار الرحمة في صنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص729–730، تحت عنوان «سر إيثار التعبير بالاسم الجليل ﴿الرحمن﴾»","url":""}]},{"id":"s67-8","number":8,"surah":67,"verses":[3,4],"references":[{"surah":67,"verses":[3,4]}],"verseLabel":"الملك: 3–4","question":"لماذا طُلب من الإنسان أن يعيد النظر في السماء مرة بعد مرة؟","answer":"لإقامة الحجة بطريق المشاهدة المتكررة؛ فلو أعاد الناظر التفتيش طالبًا خللًا فلن يجد، وسيعود بصره عاجزًا متعبًا. فالتكرار لا يعالج نظرة عابرة، بل يتحدى أدق الفحص أن يكشف تفاوتًا في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص737، تحت عنوان «دلالة تكرار الأمر في ﴿ثم ارجع﴾»","url":""}]},{"id":"s67-9","number":9,"surah":67,"verses":[4],"references":[{"surah":67,"verses":[4]}],"verseLabel":"الملك: 4","question":"لماذا قيل ﴿كَرَّتَيْنِ﴾ بدل «مرتين»؟","answer":"لأن الكرة ليست مجرد عدد، بل رجوع إلى الشيء وإعادة للنظر بعد النظر؛ فتستحضر حركة العين وهي تفتش ثم تعود إلى التفتيش. والمراد استقصاء التكرار حتى ييأس البصر من العثور على خلل، لا الوقوف عند العدد الحرفي مرتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص738، تحت عنوان «سر التعبير بـ﴿كرتين﴾ بدل مرتين»","url":""}]},{"id":"s67-10","number":10,"surah":67,"verses":[5],"references":[{"surah":67,"verses":[5]}],"verseLabel":"الملك: 5","question":"لماذا سُمّيت النجوم ﴿مَصَابِيحَ﴾؟","answer":"شُبهت بالمصابيح لأنها تبدد ظلمة الليل بنورها وتزين صفحة السماء كما تزين المصابيح المكان. فتقرب الاستعارة المشهد إلى الحس، مع بقاء النجوم أعظم من مصابيح البشر قدرًا وصنعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص749، تحت عنوان «الاستعارة في التعبير بالمصابيح عن النجوم»","url":""}]},{"id":"s67-11","number":11,"surah":67,"verses":[7],"references":[{"surah":67,"verses":[7]}],"verseLabel":"الملك: 7","question":"ما الصورة في سماع ﴿شَهِيقٍ﴾ لجهنم؟","answer":"صُوّرت النار ككائن هائل يتنفس بصوت شديد من شدة تغيظه على أهلها، فيسمع الداخلون زفيرها قبل أن يذوقوا عذابها. فتضيف الصورة إلى ألم النار رعب الصوت والحياة المخيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص768–769، تحت عنوان «بلاغة الاستعارة في التعبير بالشهيق»","url":""}]},{"id":"s67-26","number":26,"surah":67,"verses":[7],"references":[{"surah":67,"verses":[7]}],"verseLabel":"الملك: 7","question":"ماذا ترسم جملة ﴿وَهِيَ تَفُورُ﴾ من حركة جهنم؟","answer":"ترسمها تغلي وتضطرب بأهلها كما يفور القدر بما فيه، فلا تبدو نارًا ساكنة بل عذابًا متحركًا متجددًا. واجتماع الفوران مع الشهيق يحيط الداخل بالرؤية والصوت المرعبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص770، تحت عنوان «بلاغة الاستعارة في قوله: ﴿وهي تفور﴾»","url":""}]},{"id":"s67-12","number":12,"surah":67,"verses":[8],"references":[{"surah":67,"verses":[8]}],"verseLabel":"الملك: 8","question":"ماذا يفيد قوله ﴿كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ﴾ عن تتابع أهل النار؟","answer":"يفيد تجدد المشهد مرة بعد مرة؛ فما إن يلقى فوج حتى يتبعه غيره، فتظل الخزنة تسأل وتتكرر الاعترافات. وهذا يصور كثرة الداخلين واستمرار امتلاء النار بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص775–776، تحت عنوان «سر التعبير بالتركيب ﴿كلما﴾»","url":""}]},{"id":"s67-27","number":27,"surah":67,"verses":[8],"references":[{"surah":67,"verses":[8]}],"verseLabel":"الملك: 8","question":"لماذا قيل عن أهل النار إنهم ﴿أُلْقِيَ﴾ بهم فيها؟","answer":"لأن الإلقاء يصور طرحهم بقوة وإهانة من غير اختيار، كشيء لا وزن له يقذف في موضعه. فاللفظ يزيد مشهد العذاب ذلًا وقهرًا فوق ألم النار نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص776، تحت عنوان «دلالة التعبير بالإلقاء في مقام التعذيب»","url":""}]},{"id":"s67-13","number":13,"surah":67,"verses":[8],"references":[{"surah":67,"verses":[8]}],"verseLabel":"الملك: 8","question":"لماذا يسأل خزنة جهنم أهلها ﴿أَلَمْ يَأْتِكُمْ نَذِيرٌ﴾؟","answer":"ليس طلبًا لمعلومة يجهلونها، بل توبيخ وإلزام لهم بأن الحجة قامت قبل العقاب. وإقرارهم بمجيء النذير يجعل اعترافهم شاهدًا عليهم، فلا يبقى لهم عذر في المصير الذي وصلوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص778، تحت عنوان «بلاغة الكناية في التعبير بالسؤال»","url":""}]},{"id":"s67-14","number":14,"surah":67,"verses":[10],"references":[{"surah":67,"verses":[10]}],"verseLabel":"الملك: 10","question":"لماذا جمع أهل النار في اعترافهم بين السماع والعقل؟","answer":"لأن الهداية تحتاج استقبال الحق من الرسل بالسمع، ثم تدبره بالعقل حتى يظهر صدقه ويثمر عملًا. وهم يعترفون بأنهم عطلوا الطريقين: لم يصغوا للوحي إصغاء قبول، ولم يستعملوا عقولهم في دلائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص796، تحت عنوان «دلالة الجمع بين السمع والتعقل في مقام الهداية»","url":""}]},{"id":"s67-15","number":15,"surah":67,"verses":[12,13],"references":[{"surah":67,"verses":[12,13]}],"verseLabel":"الملك: 12–13","question":"لماذا خُيّر الناس في قوله ﴿وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ﴾؟","answer":"ليس تخيير إباحة، بل تحد وتهديد: سواء أخفوا كلامهم أم أعلنوه فالله يعلم ما في الصدور قبل أن ينطق اللسان. فالأمر يسوي بين السر والجهر في انكشافهما لعلم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص18، تحت عنوان «غرض التعبير بفعل الأمر ودلالته»","url":""}]},{"id":"s67-16","number":16,"surah":67,"verses":[14],"references":[{"surah":67,"verses":[14]}],"verseLabel":"الملك: 14","question":"ما الحجة في قوله ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ﴾؟","answer":"أن من أوجد المخلوق وأحكم تكوينه لا يخفى عليه ظاهره ولا باطنه؛ فعلم الصانع بخلقه أسبق وأتم من علم المخلوق بنفسه. والاستفهام يقرر هذه الحقيقة وينكر على من يتوهم أن سرًا يغيب عن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص28–29، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s67-17","number":17,"surah":67,"verses":[15],"references":[{"surah":67,"verses":[15]}],"verseLabel":"الملك: 15","question":"ما الصورة في وصف الأرض بأنها ﴿ذَلُولًا﴾؟","answer":"شُبهت بدابة منقادة يسهل ركوبها والانتفاع بها؛ فقد هيأها الله للاستقرار والسير والزرع مع ضخامة خلقها. فالصورة تحول الألفة اليومية بالأرض إلى دليل على نعمة تسخيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص39–40، تحت عنوان «بلاغة التشبيه والاستعارة»","url":""}]},{"id":"s67-28","number":28,"surah":67,"verses":[15],"references":[{"surah":67,"verses":[15]}],"verseLabel":"الملك: 15","question":"لماذا عبّر عن نواحي الأرض بـ﴿مَنَاكِبِهَا﴾؟","answer":"شُبهت جوانب الأرض ومرتفعاتها بمناكب الكائن، استمرارًا لصورة الأرض المذللة التي يمشي الناس عليها. ويصور اللفظ قدرتهم على الانتشار في أرجائها وطلب الرزق فوقها بفضل تهيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص43، تحت عنوان «بلاغة الاستعارة في لفظ ﴿مناكبها﴾»","url":""}]},{"id":"s67-18","number":18,"surah":67,"verses":[16,17],"references":[{"surah":67,"verses":[16,17]}],"verseLabel":"الملك: 16–17","question":"لماذا انتقل التهديد من خسف الأرض إلى إرسال الحاصب؟","answer":"لينتقل المكذب من صورة عذاب تحت قدميه إلى عذاب يهجم عليه من فوقه؛ فليس أمنه متعلقًا بجهة واحدة. والانتقال لا يلغي التهديد الأول، بل يضيف إليه نوعًا آخر يوسع دائرة الخوف ويهدم وهم النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص54، تحت عنوان «بلاغة الإضراب ونوعه»","url":""}]},{"id":"s67-19","number":19,"surah":67,"verses":[19],"references":[{"surah":67,"verses":[19]}],"verseLabel":"الملك: 19","question":"ما سرّ التعبير عن الطير بقوله ﴿صَافَّاتٍ وَيَقْبِضْنَ﴾ بالاسم ثم الفعل؟","answer":"الصف هو الهيئة الأصلية التي يقوم عليها الطيران في هذا التصوير، فناسبه اسم الفاعل الدال على الثبوت. أما قبض الأجنحة فيتجدد من حين إلى حين فناسبه الفعل المضارع؛ فالفرق بين الأصل المستمر والفعل المتكرر، ولا يعني أن الطير ساكنة في حال الصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص68–69، تحت عنوان «نكتة التعبير بالاسم للصف والفعل للقبض»","url":""}]},{"id":"s67-20","number":20,"surah":67,"verses":[19],"references":[{"surah":67,"verses":[19]}],"verseLabel":"الملك: 19","question":"لماذا ختم مشهد الطير باسم ﴿الرَّحْمَنُ﴾؟","answer":"لأن إمساك الطير في الجو صورة رحمة مستمرة: وهبها أجنحتها وقوانين طيرانها ويحفظها من السقوط. فليس المشهد قدرة مجردة، بل عناية عامة تتجدد بكل طائر، ولا يملك هذا الإمساك على الحقيقة إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص71، تحت عنوان «نكتة إيثار اسم ﴿الرحمن﴾»","url":""}]},{"id":"s67-21","number":21,"surah":67,"verses":[20],"references":[{"surah":67,"verses":[20]}],"verseLabel":"الملك: 20","question":"ما التحدي في قوله ﴿أَمَّنْ هَذَا الَّذِي هُوَ جُنْدٌ لَكُمْ﴾؟","answer":"يتحدى المشركين أن يشيروا إلى أي قوة تزعم نصرتهم إذا أراد الرحمن بهم ضرًا؛ فلا آلهتهم ولا جماعتهم تملك دفع أمره. وصيغة السؤال تكشف أن الجند الذي يتوهمونه لا وجود له إلا في غرورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص78، تحت عنوان «براعة استعمال أسلوب الاستفهام»","url":""}]},{"id":"s67-22","number":22,"surah":67,"verses":[22],"references":[{"surah":67,"verses":[22]}],"verseLabel":"الملك: 22","question":"لماذا مثل الضال بـ﴿مُكِبًّا عَلَى وَجْهِهِ﴾ والمهتدي بـ﴿سَوِيًّا عَلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"مثل الضال بمن يمشي منكّبًا لا يستبين طريقه، ومثل المهتدي بمن يمشي معتدلًا على طريق واضح مستقيم. فتحولت حالتا الكفر والإيمان إلى هيئتين محسوسَتين، يظهر في المقابلة اضطراب الأولى واستقامة الثانية وأمن مسيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص99–100، تحت عنوان «بلاغة الاستعارات التمثيلية»","url":""}]},{"id":"s67-23","number":23,"surah":67,"verses":[23],"references":[{"surah":67,"verses":[23]}],"verseLabel":"الملك: 23","question":"ماذا يكشف جمع ﴿الْأَفْئِدَةَ﴾ عن تفاوت الناس في تلقي الهدى؟","answer":"يكشف أن القلوب ليست على استعداد واحد؛ فهي تختلف في استقبال الإنذار والبشارة والحجة، وتتفاوت درجات إدراكها للحق. ويلمح الجمع كذلك إلى تعدد قوى الفؤاد وتنوع ما تتعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص107، تحت عنوان «نكتة جمع ﴿الأفئدة﴾»","url":""}]},{"id":"s67-24","number":24,"surah":67,"verses":[28],"references":[{"surah":67,"verses":[28]}],"verseLabel":"الملك: 28","question":"لماذا أُمر النبي أن يقول للمكذبين ﴿إِنْ أَهْلَكَنِيَ اللَّهُ وَمَنْ مَعِيَ أَوْ رَحِمَنَا﴾؟","answer":"ليرد على تمنّيهم موته بأن مصيره ومصير المؤمنين بيد الله، ولن يغيّر هلاكه أو رحمته شيئًا من مصير الكافرين. فالسؤال الحقيقي ليس ماذا سيحدث للرسول، بل من ينقذ المكذبين من عذاب أليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص134، تحت عنوان «بلاغة الاستئناف ودلالته»","url":""}]},{"id":"s67-25","number":25,"surah":67,"verses":[30],"references":[{"surah":67,"verses":[30]}],"verseLabel":"الملك: 30","question":"لماذا خُتم التهديد بذهاب الماء في قوله ﴿إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا﴾؟","answer":"لأن الماء أقرب ضروريات الحياة وأشدها حضورًا في شعور الإنسان، ومع ذلك قد يغيبه الله في أعماق الأرض فلا تبلغه وسيلة. فالتهديد ينقلهم من الجدل البعيد إلى نعمة يومية يدركون عجزهم عن استردادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص151–152، تحت عنوان «بلاغة الإضافة ونوعها، ونكتة التهديد بالماء»","url":""}]},{"id":"s67-29","number":29,"surah":67,"verses":[30],"references":[{"surah":67,"verses":[30]}],"verseLabel":"الملك: 30","question":"كيف يرد ختام سورة الملك على مطلعها؟","answer":"افتتحت السورة بإثبات الملك والقدرة لله، وختمت بسؤال عملي يكشف أثر هذا الملك: من يملك إعادة الماء إذا غار؟ فالعجز عن جلب أصل الحياة يعيد القارئ إلى الحقيقة الأولى أن السلطان والتدبير كله بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص154، تحت عنوان «بلاغة فن رد الختام على صدر السورة»","url":""}]},{"id":"s67-30","number":30,"surah":67,"verses":[2],"references":[{"surah":67,"verses":[2]}],"verseLabel":"الملك: 2","question":"ما سر التخفيف في ﴿لِيَبْلُوَكُمْ﴾، في حين جاء في سورة الإنسان ﴿نَبْتَلِيهِ﴾ بالصيغة الأطول؟","answer":"سورة الملك ختمت الآية بـ﴿الْغَفُورُ﴾، والمغفرة تلائم التخفيف، كما أنها لم تفصّل وسائل الابتلاء وأعمال الفريقين. أما سورة الإنسان ففصّلت السمع والبصر والهداية وأعمال الأبرار والكافرين وجزاءهم؛ فناسب تفصيلُ المعنى وزيادةُ شدته الصيغةَ الأطول نبتليه، وناسب الإيجاز في الملك ليبلوكم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص210–216، مبحث الفرق بين ﴿نبتليه﴾ و﴿ليبلوكم﴾. والنص موثق إلكترونيًا في تدارس القرآن الكريم.","url":""}]},{"id":"s67-31","number":31,"surah":67,"verses":[9],"references":[{"surah":67,"verses":[9]}],"verseLabel":"الملك: 9","question":"ما سر قول أهل النار ﴿مَا نَزَّلَ اللَّهُ مِنْ شَيْءٍ﴾، بينما جاء في يس ﴿وَمَا أَنْزَلَ الرَّحْمَنُ مِنْ شَيْءٍ﴾؟","answer":"سورة الملك يشيع فيها الوعيد ومشاهد النار والتحذير من البطش، فلم يناسب هذا المقام أن تُحكى مقالتهم باسم الرحمن. أما سورة يس فالإرسال فيها رحمة، وذُكر فيها أصحاب الجنة، وتكرر اسم الرحمن؛ فجاء كل اسم موافقًا للجو الغالب في سورته.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص81–82، مبحث ﴿وما أنزل الرحمن من شيء﴾ و﴿ما نزل الله من شيء﴾. والنص موثق إلكترونيًا في تدارس القرآن الكريم.","url":""}]},{"id":"s67-32","number":32,"surah":67,"verses":[10],"references":[{"surah":67,"verses":[10]}],"verseLabel":"الملك: 10","question":"ما أثر إحاطة حرف ﴿فِي﴾ بهم في قولهم ﴿مَا كُنَّا فِي أَصْحَابِ السَّعِيرِ﴾ بدل «من أصحاب السعير»؟","answer":"في تفيد الظرفية؛ فهم وقت هذا الاعتراف داخل السعير وفي عداد أصحابه معًا. أما «من أصحاب السعير» فتثبت الانتساب إليهم، لكنها لا تنص على أنهم واقعون فيها لحظة الكلام. فجاء الحرف مصورًا الإحاطة والعذاب الحاضر، لا مجرد الانتماء إلى الفريق.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «ما دلالة استعمال في بدل من؟»، مبحث الآية (10).","url":""}]},{"id":"s67-33","number":33,"surah":67,"verses":[10],"references":[{"surah":67,"verses":[10]}],"verseLabel":"الملك: 10","question":"ما سر اقتران السمع بالعقل في اعتراف أهل السعير، وغياب البصر عن قولهم ﴿لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ﴾؟","answer":"المقام مقام نذير ورسالة تُلقى إليهم قولًا؛ فطريق تلقيها هو السمع، ثم يأتي العقل ليتدبر المسموع ويحكم بصدقه. وقد اعترفوا قبلها بأن النذير جاءهم فكذبوه، فناسب أن يذكروا الآلتين اللتين عطلوهما: سماع الوحي والاعتبار العقلي، لا مجرد الإبصار.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «لماذا لم يقل لو كنا نبصر؟»، مبحث الآية (10).","url":""}]},{"id":"s67-34","number":34,"surah":67,"verses":[14],"references":[{"surah":67,"verses":[14]}],"verseLabel":"الملك: 14","question":"ما دلالة اختيار ﴿مَنْ﴾ في السؤال القاطع ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ﴾؟","answer":"الأصل في من إذا انفردت أن تكون لذوات أولي العلم، بخلاف ما التي تستعمل لغير العاقل ولصفات أولي العلم. فجاءت من ملائمة للخالق العليم، ومركزةً السؤال على الذات المتصفة بالعلم والخلق، ثم أكد الختام هذا المعنى بقوله ﴿اللَّطِيفُ الْخَبِيرُ﴾.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «الفرق بين ما ومن في الاستعمال اللغوي»، مبحث الآية (14).","url":""}]},{"id":"s67-35","number":35,"surah":67,"verses":[18],"references":[{"surah":67,"verses":[18]}],"verseLabel":"الملك: 18","question":"ما سر ختم التحذير بـ﴿فَكَيْفَ كَانَ نَكِيرِ﴾ لا «فكيف كان عقابي»؟","answer":"السورة تعرض مظاهر الرحمن ورحمته في تسخير الأرض والرزق وإمساك الطير؛ فجاء نكير، أي إنكار الله عليهم وتغييره حالهم بالعقوبة، أنسب بخيط السورة اللفظي. أما موضع الرعد الذي غلب عليه الأخذ والجزاء فخُتم بـ﴿فَكَيْفَ كَانَ عِقَابِ﴾، فناسب كل ختام سياقه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «الفرق بين الرحمن وصافات في الملك، والله ومسخرات في النحل»، المبحث المتصل بالآيات (15–21).","url":""}]},{"id":"s67-36","number":36,"surah":67,"verses":[23],"references":[{"surah":67,"verses":[23]}],"verseLabel":"الملك: 23","question":"ما دلالة الجزم بقلة الشكر ﴿قَلِيلًا مَا تَشْكُرُونَ﴾، في مقابل ﴿لَعَلَّكُمْ تَشْكُرُونَ﴾ في سورة النحل؟","answer":"آية النحل تذكر النعم وغايتها، فجاء الرجاء ﴿لَعَلَّكُمْ تَشْكُرُونَ﴾ دعوةً إلى تحقيق الشكر. أما سورة الملك فتخاطب قومًا قائمين في العتو والنفور، ينكرون الوعد ويعرضون عن دلائل القدرة؛ فناسب مقامُ الحكم على واقعهم التقريرَ بأن شكرهم قليل.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «لعلكم تشكرون وقليلًا ما تشكرون»، المبحث المتصل بالآية (23).","url":""}]},{"id":"s67-37","number":37,"surah":67,"verses":[25],"references":[{"surah":67,"verses":[25]}],"verseLabel":"الملك: 25","question":"ما دلالة المضارع في ﴿وَيَقُولُونَ مَتَى هَذَا الْوَعْدُ﴾ بدل أن يقال «وقالوا»؟","answer":"المضارع يصور القول متجددًا مستمرًا، فهم لم يلقوا السؤال مرة ثم سكتوا، بل ظلوا يكررونه استهزاءً وإنكارًا كلما أُنذروا بالآخرة. وبهذا تحولت العبارة من نقل مقولة ماضية إلى مشهد حي يكشف إصرارهم المتواصل.","sources":[{"label":"فاضل السامرائي، منصة باحث: «ويقولون متى هذا الوعد إن كنتم صادقين».","url":""}]},{"id":"s67-38","number":38,"surah":67,"verses":[27],"references":[{"surah":67,"verses":[27]}],"verseLabel":"الملك: 27","question":"ما سر اختيار ﴿زُلْفَةً﴾ لحظة انكشاف الوعد الذي طالما استبعده الكافرون؟","answer":"الزلفة هي القرب، وفي مادتها إيحاء بالتقرب والدنو؛ فإذا باليوم الذي جعلوه بعيدًا حاضر قريب أمام وجوههم. وجاء ﴿سِيئَتْ وُجُوهُ﴾ مبنيًا للمجهول لأن سبب الإساءة مشاهد معلوم، ولتركيز الصورة على أثر المفاجأة البادي في الوجوه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما معنى فلما رأوه زلفة سيئت وجوه الذين كفروا؟»، مبحث الآية (27).","url":""}]},{"id":"s67-39","number":39,"surah":67,"verses":[29],"references":[{"surah":67,"verses":[29]}],"verseLabel":"الملك: 29","question":"ما دلالة تأخير ﴿بِهِ﴾ في ﴿آمَنَّا بِهِ﴾، وتقديم ﴿عَلَيْهِ﴾ في ﴿وَعَلَيْهِ تَوَكَّلْنَا﴾؟","answer":"الإيمان لا ينحصر في الإيمان بالله وحده؛ بل يشمل ملائكته وكتبه ورسله واليوم الآخر، فلم يُقدَّم الجار والمجرور على وجه الحصر. أما التوكل فلا يكون إلا على الله، فقُدِّم ﴿عَلَيْهِ﴾ لإفادة الاختصاص: عليه وحده اعتمدنا، إذ لا يملك غيره ضرًا ولا نفعًا.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «دلالة تقديم وتأخير الجار والمجرور في آمنا به وعليه توكلنا»، مبحث الآية (29).","url":""}]},{"id":"s67-40","number":40,"surah":67,"verses":[30],"references":[{"surah":67,"verses":[30]}],"verseLabel":"الملك: 30","question":"ما الأثر البلاغي لاختتام السورة بسؤال الماء: ﴿فَمَنْ يَأْتِيكُمْ بِمَاءٍ مَعِينٍ﴾؟","answer":"هو استفهام تقريري يلزم المخاطَب بالإقرار بأن المنعم الأول واحد، وأن أحدًا لا يستطيع رد الماء إذا غار. وهو خاتمة لسلسلة من الأسئلة: من ينصركم؟ من يرزقكم؟ من يجير الكافرين؟ ثم تُختم بأقرب ضرورة للحياة، فيعود آخر السورة إلى معنى أولها: الملك والقدرة له وحده.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما دلالة هذا السؤال في ختام سورة الملك؟»، مبحث الآية (30).","url":""}]},{"id":"s67-41","number":41,"surah":67,"verses":[2],"references":[{"surah":67,"verses":[2]}],"verseLabel":"الملك: 2","question":"ما سر التعبير بخلق الموت والحياة، مع أن الموت يبدو عدمًا لا مخلوقًا؟","answer":"الخلق هو الإيجاد ابتداءً على غير مثال، أما الجعل ففيه معنى تصيير الشيء أو ملابسته بشيء آخر. والموت والحياة حقيقتان أوجدهما الله، لا وصفان حُوِّل أحدهما إلى الآخر؛ لذلك ناسب فعل خلق، بينما يقال: جعل النهار نشورًا، لأن الجعل هناك تضمَّن تصيير النهار حالًا مخصوصة.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «ما دلالة خلق مع الموت؟»، مبحث الآية (2).","url":""}]},{"id":"s67-42","number":42,"surah":67,"verses":[3],"references":[{"surah":67,"verses":[3]}],"verseLabel":"الملك: 3","question":"ما سر العدول من «ما ترى في السماوات» إلى ﴿مَا تَرَى فِي خَلْقِ الرَّحْمَنِ مِنْ تَفَاوُتٍ﴾؟","answer":"التعبير بـ﴿خَلْقِ الرَّحْمَنِ﴾ يعمّ السماوات وغير السماوات، فيجعل نفي التفاوت شاملًا للخلق كله، لا مقصورًا على المشهد السماوي السابق. كما أن اسم الرحمن يلائم ما في إحكام الخلق وتسويته من رحمة، ثم عاد السياق بعد هذا العموم إلى السماء الدنيا في الآية الخامسة.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما دلالة استخدام كلمة الرحمن… مع أن الكلام عن خلق السماوات؟»، مبحث الآية (3).","url":""}]},{"id":"s67-43","number":43,"surah":67,"verses":[12],"references":[{"surah":67,"verses":[12]}],"verseLabel":"الملك: 12","question":"ما سر الجمع بين ﴿مَغْفِرَةٌ﴾ و﴿أَجْرٌ كَبِيرٌ﴾ في جزاء الذين يخشون ربهم بالغيب؟","answer":"إذا ورد الأجر الكبير في سياق سبقه ذكر الكفر والذنوب أضيفت إليه المغفرة؛ لأن المقام يقتضي محو الذنب قبل نيل الثواب. وقد سبقت هذه الآيةَ صورةُ الكافرين واعترافُهم بذنبهم، فجاءت المغفرة في مقابلة الذنب، ثم الأجر الكبير جزاءً للخشية.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص246–249، مبحث زيادة المغفرة مع الأجر الكبير. والنص موثق إلكترونيًا في تدارس القرآن الكريم.","url":""}]},{"id":"s67-44","number":44,"surah":67,"verses":[19],"references":[{"surah":67,"verses":[19]}],"verseLabel":"الملك: 19","question":"ما سر قوله ﴿مَا يُمْسِكُهُنَّ إِلَّا الرَّحْمَنُ﴾، بينما قال في النحل ﴿مَا يُمْسِكُهُنَّ إِلَّا اللَّهُ﴾؟","answer":"سورة الملك تعرض فعل الطير في حالتي الراحة والحركة: صافات ويقبضن، وفي تمكينها من هذا الاختيار والإمساك بها مظهر رحمة، فناسب اسم الرحمن. أما سورة النحل فعبّرت بـ﴿مُسَخَّرَاتٍ﴾ في سياق التوحيد والعبادة، والتسخير لم يُسنَد في القرآن إلى الرحمن؛ فناسب الاسم العلم الله.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما الفرق بين استخدام الله ومسخرات في النحل، والرحمن وصافات في الملك؟»، مبحث الآية (19).","url":""}]},{"id":"s68-1","number":1,"surah":68,"verses":[1],"references":[{"surah":68,"verses":[1]}],"verseLabel":"القلم: 1","question":"ما مناسبة القسم بـ﴿وَالْقَلَمِ وَمَا يَسْطُرُونَ﴾ لنفي الجنون عن النبي ﷺ؟","answer":"لأن القلم وما يكتب به عنوان العلم والبيان، وما سُطر من الوحي يشهد بكمال عقل الرسول ﷺ وصدق رسالته؛ فجاء المقسم به من جنس البرهان على بطلان التهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص174–175، تحت عنوان «نكتة إيثار القسم بـ﴿والقلم وما يسطرون﴾»","url":""}]},{"id":"s68-2","number":2,"surah":68,"verses":[2],"references":[{"surah":68,"verses":[2]}],"verseLabel":"القلم: 2","question":"كيف جعل قوله ﴿بِنِعْمَةِ رَبِّكَ﴾ نعمة الله برهانًا على براءة النبي ﷺ من الجنون؟","answer":"يصوّر الرسول ﷺ ملابسًا لنعمة ربه من النبوة والعقل والرعاية، أو يجعلها سببًا لسلامته؛ وفي الوجهين تصبح النعمة الإلهية مناقضة لتهمة الجنون ودليلًا على بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص177–178، تحت عنوان «معنى (الباء) في ﴿بنعمة﴾ والغرض منها»","url":""}]},{"id":"s68-26","number":26,"surah":68,"verses":[2],"references":[{"surah":68,"verses":[2]}],"verseLabel":"القلم: 2","question":"كيف يقوّي التعبير ﴿مَا أَنْتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ﴾ نفيَ تهمة الجنون؟","answer":"دخول الباء في الخبر يشدد النفي ويستغرق أدنى صورة من صور الجنون؛ فلا يكتفي بنفي أصل التهمة، بل يدفعها دفعًا مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص182، تحت عنوان «معنى (الباء) في ﴿بمجنون﴾»","url":""}]},{"id":"s68-3","number":3,"surah":68,"verses":[3],"references":[{"surah":68,"verses":[3]}],"verseLabel":"القلم: 3","question":"لماذا وصف الأجر بأنه ﴿غَيْرُ مَمْنُونٍ﴾؟","answer":"تذكر الموسوعة في «ممنون» معنى المقطوع أو المنقوص، ومعنى ما يشوبه المن المؤذي. فنفي الوصف يجمع دوام الأجر وكماله وتكريم صاحبه، مع بقاء فضل الله عليه وعنايته به.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص189، تحت عنوان «نكتة اختيار الوصف ﴿ممنون﴾ مادة وصيغة»","url":""}]},{"id":"s68-4","number":4,"surah":68,"verses":[4],"references":[{"surah":68,"verses":[4]}],"verseLabel":"القلم: 4","question":"ما سرّ التعبير في قوله ﴿لَعَلَى خُلُقٍ عَظِيمٍ﴾ بحرف «على»؟","answer":"استعير الاستعلاء للتمكن من الخلق والاستقرار عليه، فكأنه متمكن منه تمكّن من علا شيئًا واستقر فوقه. فالصورة تبرز رسوخ أخلاقه وارتفاع منزلتها، وتؤكد أن الحلم وسائر الخصال ملكة ثابتة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص192–193، تحت عنوان «معنى (على) والغرض منها»","url":""}]},{"id":"s68-5","number":5,"surah":68,"verses":[5,6],"references":[{"surah":68,"verses":[5,6]}],"verseLabel":"القلم: 5–6","question":"ما الوعد والوعيد المندمجان في قوله ﴿فَسَتُبْصِرُ وَيُبْصِرُونَ﴾؟","answer":"فيه وعد للنبي ﷺ بأن يرى قريبًا ظهور صدقه وعاقبة صبره، ووعيد للمكذبين بأن يروا افتضاح باطلهم وحلول ما أنذروا به؛ فجمع فعل واحد تثبيت الرسول وتهديد خصومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص197، تحت عنوان «دلالة الإدماج في ﴿فستبصر﴾»","url":""}]},{"id":"s68-27","number":27,"surah":68,"verses":[5,6],"references":[{"surah":68,"verses":[5,6]}],"verseLabel":"القلم: 5–6","question":"لماذا عُرض تعيين المفتون بصيغة ﴿بِأَيِّكُمُ الْمَفْتُونُ﴾؟","answer":"ليجاري الخصوم في صورة المنصف الذي يترك انكشاف الحقيقة للحكم القريب، مع أن السياق قد قرر براءة النبي ﷺ؛ فتزيد الصيغة ثقة بالحجة وتهكمًا من التهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص202، تحت عنوان «معنى (أيكم) والغرض منه»","url":""}]},{"id":"s68-6","number":6,"surah":68,"verses":[7],"references":[{"surah":68,"verses":[7]}],"verseLabel":"القلم: 7","question":"لماذا عُبّر عن الضلال بالفعل ﴿ضَلَّ﴾، وعن الهداية بالاسم ﴿الْمُهْتَدِينَ﴾؟","answer":"الفعل يعرض الضلال أمرًا حادثًا يمكن أن يزول، فيبقى باب الرجوع مفتوحًا. أما الاسم فيبرز ثبات الهداية ورسوخها؛ فناسب الحدوث جانب الضلال والثبوت جانب المهتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص217، تحت عنوان «الاختلاف بالفعلية والاسمية في ﴿ضل﴾ و﴿المهتدين﴾»","url":""}]},{"id":"s68-7","number":7,"surah":68,"verses":[9],"references":[{"surah":68,"verses":[9]}],"verseLabel":"القلم: 9","question":"كيف تكشف الفاء أن مداهنتهم معلقة بمداهنته؟","answer":"تكشف الفاء تعلق مداهنتهم بما يتمنونه من مداهنته؛ فهم ينتظرون تنازله ليقابلوه بمثله، فجاء الاستئناف مصورًا استعدادهم لهذا المسلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص230، تحت عنوان «سر الاستئناف بـ(الفاء)»","url":""}]},{"id":"s68-8","number":8,"surah":68,"verses":[10,11,12,13],"references":[{"surah":68,"verses":[10,11,12,13]}],"verseLabel":"القلم: 10–13","question":"لماذا نهى القرآن عن طاعة ﴿كُلَّ حَلَّافٍ مَهِينٍ﴾ ولم يسمِّ شخصًا بعينه؟","answer":"ليتجاوز الحكم فردًا مخصوصًا إلى كل من تحققت فيه هذه الخصال، فيظل التحذير قاعدة عامة؛ ولفظ ﴿كل﴾ يبين أن النهي يتناول أفراد هذا الصنف.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص239–240، تحت عنوان «العدول من (العلم) إلى الوصف المصدر بـ﴿كل﴾»","url":""}]},{"id":"s68-28","number":28,"surah":68,"verses":[10,11,12,13],"references":[{"surah":68,"verses":[10,11,12,13]}],"verseLabel":"القلم: 10–13","question":"ماذا يصنع اقتران الصفات ﴿حَلَّافٍ مَهِينٍ هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ...﴾ بصورة المكذب؟","answer":"يراكم وجوه فساد اللسان والعمل والطبع حتى تتكون شخصية متكاملة الشر، ويكشف أن الخصال يجر بعضها بعضًا؛ فليس الذم لأفعال متناثرة بل لبنية خلقية متماسكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص253، تحت عنوان «دلالات الاقتران بين الخصال المذكورة»","url":""}]},{"id":"s68-9","number":9,"surah":68,"verses":[11],"references":[{"surah":68,"verses":[11]}],"verseLabel":"القلم: 11","question":"ماذا تكشف صيغة ﴿هَمَّازٍ﴾ عن صاحبها؟","answer":"صيغة المبالغة تصور الطعن في الناس عادة متكررة راسخة، لا زلة عابرة؛ فهو كثير الانتقاص والوقيعة في أعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص245–246، تحت عنوان «دلالة النعت ﴿هماز﴾ مادة وصيغة»","url":""}]},{"id":"s68-29","number":29,"surah":68,"verses":[11],"references":[{"surah":68,"verses":[11]}],"verseLabel":"القلم: 11","question":"ما الصورة التي يحملها وصف المكذب بأنه ﴿هَمَّازٍ﴾؟","answer":"ينقل الهمز من النخس والطعن الحسي إلى أذى اللسان والإشارة، فكأن المنتقص يطعن الناس طعنًا محسوسًا؛ وبذلك يجسّم قبح الغيبة والعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص246، تحت عنوان «دلالة الاستعارة في ﴿هماز﴾»","url":""}]},{"id":"s68-10","number":10,"surah":68,"verses":[12],"references":[{"surah":68,"verses":[12]}],"verseLabel":"القلم: 12","question":"كيف تكشف الخصال ﴿مَنَّاعٍ لِلْخَيْرِ مُعْتَدٍ أَثِيمٍ﴾ أن الشر لديه مسار متصاعد؟","answer":"تبدأ بمن يكثر منع الخير والصد عنه؛ ومن يفعل ذلك يتجاوز حقوق الآخرين في الوصول إلى الخير وسماعه، فيتحول المنع إلى اعتداء. ثم يكشف تكرر المنع والعدوان بلوغه الغاية في الإثم، فتجتمع الصفات لترسم فسادًا يتعدى إلى الناس ويرسخ في صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص253، تحت عنوان «دلالات الاقتران بين الخصال المذكورة»","url":""}]},{"id":"s68-11","number":11,"surah":68,"verses":[13],"references":[{"surah":68,"verses":[13]}],"verseLabel":"القلم: 13","question":"ماذا يضيف وصف المكذب بأنه ﴿عُتُلٍّ﴾ إلى الصفات السابقة؟","answer":"يضيف صورة الغلظة والجفاء والشدة في الخصومة؛ فلا يقف فساده عند اللسان والعمل، بل يكشف عن طبع قاس يدفع الناس بعنف.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص253–254، تحت عنوان «دلالة النعت بـ﴿عتل﴾ مادة وصيغة»","url":""}]},{"id":"s68-30","number":30,"surah":68,"verses":[13],"references":[{"surah":68,"verses":[13]}],"verseLabel":"القلم: 13","question":"لماذا قيل ﴿بَعْدَ ذَلِكَ﴾ في أثناء تعداد صفات المكذب؟","answer":"ليست البعدية زمنية، بل رتبية: أي فوق ما تقدم من القبائح منزلة أخرى أشد وأبعد في الذم، فيصعّد التعبير درجة التنفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص255–256، تحت عنوان «دلالة الظرف ﴿بعد﴾ على البعدية المجازية»","url":""}]},{"id":"s68-31","number":31,"surah":68,"verses":[13],"references":[{"surah":68,"verses":[13]}],"verseLabel":"القلم: 13","question":"ما الذي توحي به كلمة ﴿زَنِيمٍ﴾ في ختام صفات المكذب؟","answer":"توحي بمن أُلصق بالقوم وليس أصيلًا فيهم، كما تلصق الزنمة بالشاة، ثم استعملت في الدعي أو المشهور بالشر؛ فتختم الصورة بذم ينبئ عن الدخالة واللصوق بالقبائح.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص257، تحت عنوان «دلالة النعت ﴿زنيم﴾ مادة وصيغة»","url":""}]},{"id":"s68-12","number":12,"surah":68,"verses":[14],"references":[{"surah":68,"verses":[14]}],"verseLabel":"القلم: 14","question":"كيف فضح قوله ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾ أثر النعمة في تكذيب المتكبر؟","answer":"جعل غناه وكثرة بنيه سببًا لبطره وجرأته على التكذيب، مع أن حق النعمة أن تورث الشكر؛ فالعبارة تقلب ما يراه سندًا للعظمة إلى حجة على جحوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص264–265، تحت عنوان «معنى ﴿أن﴾ والغرض منها»","url":""}]},{"id":"s68-13","number":13,"surah":68,"verses":[16],"references":[{"surah":68,"verses":[16]}],"verseLabel":"القلم: 16","question":"لماذا قيل ﴿سَنَسِمُهُ عَلَى الْخُرْطُومِ﴾ ولم يقل «على الأنف»؟","answer":"لتنزيل أنفه منزلة خرطوم الحيوان تحقيرًا وتشويهًا، فيقابل تعاليه بصورة تهدم الكرامة التي ادعاها لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص280–281، تحت عنوان «دلالة الاستعارة أو المجاز المرسل في ﴿الخرطوم﴾»","url":""}]},{"id":"s68-32","number":32,"surah":68,"verses":[16],"references":[{"surah":68,"verses":[16]}],"verseLabel":"القلم: 16","question":"لماذا اختير الأنف موضعًا للوسم في ﴿سَنَسِمُهُ عَلَى الْخُرْطُومِ﴾؟","answer":"لأن الأنف موضع الأنفة والكبرياء وأبرز ما في الوجه، فجعل علامة المهانة عليه يقلب استعلاءه ذلًا ظاهرًا لا يخفى.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص281–282، تحت عنوان «سر اختيار (الأنف) محلًا للوسم»","url":""}]},{"id":"s68-14","number":14,"surah":68,"verses":[17],"references":[{"surah":68,"verses":[17]}],"verseLabel":"القلم: 17","question":"ماذا يوحي وصف أهل البستان بأنهم ﴿أَصْحَابَ الْجَنَّةِ﴾؟","answer":"يوحي بشدة ملازمتهم للبستان واختصاصهم به حتى عُرفوا بصحبته، وهو ما يبرز تعلقهم الشديد به قبل أن يفقدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص295، تحت عنوان «دلالة الاستعارة في لفظ ﴿أصحاب﴾»","url":""}]},{"id":"s68-33","number":33,"surah":68,"verses":[17],"references":[{"surah":68,"verses":[17]}],"verseLabel":"القلم: 17","question":"ما المفارقة في إضافة البستان إلى أصحابه في ﴿أَصْحَابَ الْجَنَّةِ﴾؟","answer":"الإضافة تعرفهم بالنعمة التي اغتروا بملكها، ثم يكشف الابتلاء أن اختصاصهم بها لا يضمن دوامها؛ فملكهم الظاهر خاضع لمشيئة المالك الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص296، تحت عنوان «دلالة الإضافة في ﴿أصحاب الجنة﴾»","url":""}]},{"id":"s68-15","number":15,"surah":68,"verses":[18],"references":[{"surah":68,"verses":[18]}],"verseLabel":"القلم: 18","question":"ما الذي يكشفه قوله ﴿وَلَا يَسْتَثْنُونَ﴾ عن تدبير أصحاب الجنة؟","answer":"يحتمل أنهم لم يقولوا «إن شاء الله»، أو لم يتركوا للمساكين شيئًا من الثمر؛ وعلى الوجهين يكشف التعبير غفلتهم عن مشيئة الله وتصميمهم على الاستئثار.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص302، تحت عنوان «دلالة الفعل المضارع ﴿يستثنون﴾ مادة وصيغة»","url":""}]},{"id":"s68-16","number":16,"surah":68,"verses":[19],"references":[{"surah":68,"verses":[19]}],"verseLabel":"القلم: 19","question":"ما الذي يهوّل مشهد الآفة في قوله ﴿فَطَافَ عَلَيْهَا طَائِفٌ مِنْ رَبِّكَ﴾؟","answer":"لتهويل الأمر وإبقاء ماهية الآفة مبهمة، فيتجه الذهن إلى أثرها الساحق لا إلى تحديد صورتها؛ فأي طائف من أمر الله كاف لإبطال تدبيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص307، تحت عنوان «أسرار التنكير في ﴿طائف﴾»","url":""}]},{"id":"s68-34","number":34,"surah":68,"verses":[19],"references":[{"surah":68,"verses":[19]}],"verseLabel":"القلم: 19","question":"ماذا تضيف عبارة ﴿مِنْ رَبِّكَ﴾ إلى مشهد هلاك الجنة؟","answer":"تقرر أن الطائف صادر عن تدبير الله وقدرته، فلا هو حادث عابر ولا تملك حيلتهم رده؛ كما تذكّر بأن رب الرسول هو الذي تولى نصرة الحق وتربية عباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص308، تحت عنوان «دلالة النعت بشبه الجملة ﴿من ربك﴾»","url":""}]},{"id":"s68-17","number":17,"surah":68,"verses":[20],"references":[{"surah":68,"verses":[20]}],"verseLabel":"القلم: 20","question":"ما الصورة التي يرسمها التشبيه في ﴿فَأَصْبَحَتْ كَالصَّرِيمِ﴾؟","answer":"ينقل البستان من نضرة الثمر إلى هيئة شيء اجتيح تمامًا، فيجعل الانقلاب المفاجئ مرئيًا كأن السامع يشاهد أرضًا انمحت معالم خضرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص311، تحت عنوان «دلالة الكاف في ﴿كالصريم﴾»","url":""}]},{"id":"s68-35","number":35,"surah":68,"verses":[20],"references":[{"surah":68,"verses":[20]}],"verseLabel":"القلم: 20","question":"لماذا اختير لفظ ﴿الصَّرِيمِ﴾ لتصوير الجنة بعد هلاكها؟","answer":"لأنه يحتمل الليل في سواده، والأرض البيضاء بعد زوال نباتها، والبستان المقطوع ثمره؛ وتتضافر هذه الوجوه في تصوير المحو والجدب وذهاب الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص311–312، تحت عنوان «نكتة التعبير بلفظ (الصريم) مادة وصيغة»","url":""}]},{"id":"s68-18","number":18,"surah":68,"verses":[23,24],"references":[{"surah":68,"verses":[23,24]}],"verseLabel":"القلم: 23–24","question":"ما المعنيان اللذان يحتملهما قول أصحاب الجنة ﴿إِنَّا لَضَالُّونَ﴾؟","answer":"قد يعنون أنهم أخطؤوا طريق جنتهم فلم يعرفوها، وقد يعترفون بأنهم ضلوا عن الحق حين عزموا على حرمان المساكين؛ فالتعبير ينتقل من ضياع الطريق إلى ضياع الصواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص342–343، تحت عنوان «(ضالون) بين الحقيقة والاستعارة»","url":""}]},{"id":"s68-36","number":36,"surah":68,"verses":[23,24],"references":[{"surah":68,"verses":[23,24]}],"verseLabel":"القلم: 23–24","question":"كيف يتغير معنى ﴿بَلْ نَحْنُ مَحْرُومُونَ﴾ باختلاف معنى ﴿ضَالُّونَ﴾؟","answer":"إن كان الضلال ضياع الطريق فـ﴿بل﴾ تبطل ظنهم وتثبت أن الجنة جنتهم لكنهم حرموا ثمرها، وإن كان ضلال الحق فهي انتقال من الاعتراف بالذنب إلى الاعتراف بعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص343–344، تحت عنوان «تأثر دلالة ﴿بل﴾ بالمعنى الحقيقي والمجازي للضلال»","url":""}]},{"id":"s68-19","number":19,"surah":68,"verses":[28],"references":[{"surah":68,"verses":[28]}],"verseLabel":"القلم: 28","question":"ماذا أراد أوسط أصحاب الجنة بسؤاله ﴿لَوْلَا تُسَبِّحُونَ﴾؟","answer":"وبخهم وحضهم على ما سبق أن نصحهم به؛ فالسؤال ليس طلبًا للخبر، بل دعوة عاجلة إلى الرجوع عن الغفلة والبطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص350، تحت عنوان «معنى ﴿لولا﴾ والغرض منها»","url":""}]},{"id":"s68-37","number":37,"surah":68,"verses":[28],"references":[{"surah":68,"verses":[28]}],"verseLabel":"القلم: 28","question":"ما معاني التسبيح التي جمعها قول أوسطهم ﴿لَوْلَا تُسَبِّحُونَ﴾؟","answer":"يجمع تنزيه الله عن الظلم، وشكره على النعمة، وذكر مشيئته عند العزم؛ وكلها تصحح ما صاحب تدبيرهم من غرور واستغناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص351، تحت عنوان «دلالة الفعل المضارع ﴿تسبحون﴾ مادة وصيغة»","url":""}]},{"id":"s68-20","number":20,"surah":68,"verses":[32],"references":[{"surah":68,"verses":[32]}],"verseLabel":"القلم: 32","question":"ماذا أفاد تقديم ﴿إِلَى رَبِّنَا﴾ في قولهم ﴿إِنَّا إِلَى رَبِّنَا رَاغِبُونَ﴾؟","answer":"أفاد قصر رغبتهم على الله وانقطاعهم إليه وحده بعد أن علقوا آمالهم بالبستان وتدبيرهم؛ فصار الرجاء اعترافًا بالافتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص371، تحت عنوان «نكتة تقديم المتعلق ﴿إلى ربنا﴾»","url":""}]},{"id":"s68-38","number":38,"surah":68,"verses":[32],"references":[{"surah":68,"verses":[32]}],"verseLabel":"القلم: 32","question":"لماذا قال أصحاب الجنة ﴿إِلَى رَبِّنَا رَاغِبُونَ﴾ باسم الرب؟","answer":"لأن اسم الرب يستحضر الرعاية والتدبير والإنعام، وهو الأنسب بحال تائبين يرجون أن يربيهم الله بالمغفرة ويعوضهم خيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص371، تحت عنوان «دلالة الإضافة في ﴿ربنا﴾»","url":""}]},{"id":"s68-21","number":21,"surah":68,"verses":[35],"references":[{"surah":68,"verses":[35]}],"verseLabel":"القلم: 35","question":"لماذا سأل القرآن ﴿أَفَنَجْعَلُ الْمُسْلِمِينَ كَالْمُجْرِمِينَ﴾؟","answer":"لينكر مساواة أهل الطاعة بأهل الإجرام في الجزاء، ويلزم المكذبين بفساد تصورهم؛ فاختلاف الطريقين يقتضي اختلاف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص396–397، تحت عنوان «دلالة الهمزة في ﴿أفنجعل﴾ والغرض منها»","url":""}]},{"id":"s68-22","number":22,"surah":68,"verses":[42],"references":[{"surah":68,"verses":[42]}],"verseLabel":"القلم: 42","question":"ما الصورة البلاغية في قوله ﴿يَوْمَ يُكْشَفُ عَنْ سَاقٍ﴾؟","answer":"هي كناية أو استعارة تمثيلية عن اشتداد الهول، مأخوذة من حال من يشمر عن ساقه عند الأمر العظيم؛ فترسم القيامة في ذروة شدتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص456، تحت عنوان «دلالة الكناية أو الاستعارة التمثيلية في ﴿يكشف عن ساق﴾»","url":""}]},{"id":"s68-39","number":39,"surah":68,"verses":[42],"references":[{"surah":68,"verses":[42]}],"verseLabel":"القلم: 42","question":"ما المفارقة بين ﴿فَلَا يَسْتَطِيعُونَ﴾ وكونهم في الدنيا ﴿سَالِمِينَ﴾؟","answer":"كانوا أصحاء قادرين حين دعوا إلى السجود فامتنعوا، ثم يدعون إليه يوم القيامة وقد سلبوا القدرة؛ فتجعل المقابلة العجز جزاءً مصورًا للإعراض السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص468، تحت عنوان «دلالة التقابل بين ﴿فلا يستطيعون﴾ و﴿سالمون﴾»","url":""}]},{"id":"s68-23","number":23,"surah":68,"verses":[44],"references":[{"surah":68,"verses":[44]}],"verseLabel":"القلم: 44","question":"كيف يصور قوله ﴿سَنَسْتَدْرِجُهُمْ﴾ طريق أخذ المكذبين؟","answer":"تصور الاستعارة أخذهم على درجات خفية؛ يستمر الإنعام والإمهال فيظنه المكذب كرامة، فيزداد غفلة حتى تأتيه العاقبة من الطريق الذي أمِنَه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص480، تحت عنوان «دلالة الاستعارة التصريحية في ﴿سنستدرجهم﴾»","url":""}]},{"id":"s68-24","number":24,"surah":68,"verses":[48,49],"references":[{"surah":68,"verses":[48,49]}],"verseLabel":"القلم: 48–49","question":"لماذا عُرِّف يونس عليه السلام في التحذير بأنه ﴿صَاحِبِ الْحُوتِ﴾؟","answer":"لأن اللقب يستحضر مباشرة قصة العجلة وما انتهت إليه من التقام الحوت، فيجعل العبرة حاضرة من غير إطالة ولا تعريض باسمه الكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص510، تحت عنوان «نكتة العدول عن الاسم العلم إلى اللقب»","url":""}]},{"id":"s68-40","number":40,"surah":68,"verses":[48,49],"references":[{"surah":68,"verses":[48,49]}],"verseLabel":"القلم: 48–49","question":"ما النعمة التي تداركت صاحب الحوت في قوله ﴿لَوْلَا أَنْ تَدَارَكَهُ نِعْمَةٌ مِنْ رَبِّهِ﴾؟","answer":"يحتمل اللفظ معنى إنعام الله عليه بالتوبة والرحمة، ويحتمل النعمة التي أنعم بها عليه؛ وفي الحالين يبرز أن إنقاذه لم يكن بقوته بل بفضل ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص514، تحت عنوان «دلالة النعمة بين المعنى المصدري واسم المفعول»","url":""}]},{"id":"s68-41","number":41,"surah":68,"verses":[48,49],"references":[{"surah":68,"verses":[48,49]}],"verseLabel":"القلم: 48–49","question":"ماذا أضاف قوله ﴿فَاجْتَبَاهُ رَبُّهُ﴾ إلى قصة صاحب الحوت؟","answer":"أفاد أن الله اختاره واصطفاه بعد توبته، فلم تقف الرحمة عند إنقاذه من الشدة، بل أعادته إلى مقام الصلاح والرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص520، تحت عنوان «دلالة الفعل ﴿فاجتباه﴾ مادة وصيغة»","url":""}]},{"id":"s68-25","number":25,"surah":68,"verses":[51,52],"references":[{"surah":68,"verses":[51,52]}],"verseLabel":"القلم: 51–52","question":"لماذا صعّد المشركون أثر سماع القرآن إلى اتهام النبي ﷺ نفسه بالجنون؟","answer":"لأنهم عجزوا عن مقاومة سلطان الذكر وحجته، فحوّلوا انفعالهم به إلى طعن في صاحبه ليصدوا الناس عنه؛ فالتهمة اعتراف مستتر بقوة القرآن لا وصف حقيقي للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص535، تحت عنوان «علة تصعيد الاتهام بشخصه الشريف»","url":""}]},{"id":"s68-42","number":42,"surah":68,"verses":[51,52],"references":[{"surah":68,"verses":[51,52]}],"verseLabel":"القلم: 51–52","question":"كيف يرد ختام سورة القلم ﴿إِنَّهُ لَمَجْنُونٌ﴾ على مطلعها؟","answer":"يعيد الختام التهمة التي نفاها المطلع فيربط آخر السورة بأولها، ويجعل بنية السورة كلها ردًا على المكابرة ودفاعًا عن الرسول ﷺ بالذكر الذي حمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص537، تحت عنوان «رد الأعجاز على الصدور في ﴿لمجنون﴾»","url":""}]},{"id":"s68-43","number":43,"surah":68,"verses":[2,51],"references":[{"surah":68,"verses":[2,51]}],"verseLabel":"القلم: 2، 51","question":"كيف ردَّ مطلع السورة على تهمة الجنون في ختامها بأداة توكيد تماثل توكيدهم؟","answer":"قال المكذبون في الختام ﴿إِنَّهُ لَمَجْنُونٌ﴾ فأكدوا دعواهم باللام، وجاء الرد في المطلع ﴿مَا أَنْتَ… بِمَجْنُونٍ﴾ بالباء المؤكدة للنفي. فواجه التوكيدَ في الإثبات توكيدٌ في النفي، وربط آخر السورة بأولها ربطًا محكمًا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص169، مبحث مناسبة خاتمة القلم لمطلعها. النص المباشر.","url":""}]},{"id":"s68-44","number":44,"surah":68,"verses":[7],"references":[{"surah":68,"verses":[7]}],"verseLabel":"القلم: 7","question":"ما دلالة الماضي في ﴿أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ﴾، في مقابل المضارع ﴿مَنْ يَضِلُّ﴾ في الأنعام؟","answer":"سياق الأنعام شرطٌ متعلق بالمستقبل: إن تطع أكثر من في الأرض يضلوك؛ فناسبه المضارع ﴿مَنْ يَضِلُّ﴾. أما القلم فتعرض أشخاصًا استقر ضلالهم وظهرت صفاتهم: المكذب والحلاف والهماز والمشاء بنميم؛ فناسب الماضي ﴿مَنْ ضَلَّ﴾.","sources":[{"label":"فاضل السامرائي، منصة باحث: «الفرق بين إن ربك هو أعلم من يضل… وأعلم بمن ضل».","url":""}]},{"id":"s68-45","number":45,"surah":68,"verses":[10,14],"references":[{"surah":68,"verses":[10,14]}],"verseLabel":"القلم: 10، 14","question":"ما سر تعقيب الصفات الذميمة بقوله ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾؟","answer":"المال والبنون موضع قوة ومنعة في المجتمع، وقد يحملان الناس على الخضوع لصاحبهما مع فساد خلقه. فجاء التعقيب كاشفًا سبب اغتراره واستعلائه، ومحذرًا من طاعته لأجل جاهه؛ فلا يحوّل المال والبنون الحلافَ المهين والهمازَ المعتدي إلى صاحب أهلية للاتباع.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: مبحث «همّاز مشاء بنميم» وعلاقة المال والبنين بالنهي عن الطاعة.","url":""}]},{"id":"s68-46","number":46,"surah":68,"verses":[11],"references":[{"surah":68,"verses":[11]}],"verseLabel":"القلم: 11","question":"ما سر وصفه بـ﴿هَمَّازٍ﴾، بينما جاء في السورة الأخرى ﴿هُمَزَةٍ﴾؟","answer":"همّاز على وزن فعّال، وهي صيغة تشعر بالمزاولة والحرفة؛ فكأن الهمز صار عادةً يتعامل بها مع الناس. أما هُمزة فالمبالغة فيها بالتاء تبلغ نهاية الوصف، وناسبت سورة الهمزة التي فصّلت النهاية والعاقبة في الحطمة. وسورة القلم ركزت على السلوك المتكرر الذي يمنع طاعة صاحبه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما الفرق بين هُمَزة وهمّاز؟»، مبحث الآية (11).","url":""}]},{"id":"s68-47","number":47,"surah":68,"verses":[12],"references":[{"surah":68,"verses":[12]}],"verseLabel":"القلم: 12","question":"ما دلالة صيغة ﴿أَثِيمٍ﴾ بدل «آثم» وسط هذا السيل من الصفات؟","answer":"أثيم أبلغ من آثم، وقد سبقها في الوصف حلاف وهمّاز ومشّاء ومنّاع ومعتدٍ؛ وكلها تدل على التكرار والمبالغة. ومن اجتمعت فيه هذه الخصال لا يوصف بمجرد وقوع الإثم منه، بل بكثرته ورسوخه فيه، فجاءت الصيغة موافقة لجو المبالغة في السياق.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما الفرق بين أثيم وآثم؟»، مبحث الآية (12).","url":""}]},{"id":"s68-48","number":48,"surah":68,"verses":[1],"references":[{"surah":68,"verses":[1]}],"verseLabel":"القلم: 1","question":"ما سر اختيار ﴿يَسْطُرُونَ﴾ بعد القَسَم بالقلم، بدل التعبير العام «يكتبون»؟","answer":"الكتابة قد تصدق على حرف واحد أو كلمة قصيرة، أما التسطير فيدل على كتابة ممتدة تنتظم في سطور. فجاء ﴿مَا يَسْطُرُونَ﴾ أوسع دلالة على آثار القلم المتتابعة من علوم ووحي ومعارف، وهو معطوف على المقسَم به؛ فأخذ حكم القسم بالقلم.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «هل التسطير يتبع الكتابة بهذا القلم؟»، مبحث الآية (1).","url":""}]},{"id":"s68-49","number":49,"surah":68,"verses":[2],"references":[{"surah":68,"verses":[2]}],"verseLabel":"القلم: 2","question":"ما سر الاقتصار على نفي الجنون ﴿مَا أَنْتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ﴾، بينما زاد في الطور نفي الكهانة؟","answer":"سورة القلم لم تحكِ من دعاوى المكذبين في حق الرسول إلا قولهم إنه مجنون، فردّ مطلعها على الدعوى نفسها. أما الطور ففصّلت دعاواهم: كاهن وشاعر ومتقوّل، وذكرت استماع الكهان والسحر؛ فناسبها نفي الكهانة والجنون معًا. كما وافق الاختصار في القلم قِصَر القسم في مطلعها.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص168–169، مبحث «من سورتي الطور والقلم». النص المباشر.","url":""}]},{"id":"s68-50","number":50,"surah":68,"verses":[43],"references":[{"surah":68,"verses":[43]}],"verseLabel":"القلم: 43","question":"ما دلالة ﴿خَاشِعَةً أَبْصَارُهُمْ﴾ هنا، في مقابل ﴿خُشَّعًا أَبْصَارُهُمْ﴾ في القمر؟","answer":"خاشعة اسم فاعل يدل على الوصف، أما خُشّعًا فصيغة جمع تحمل مبالغة وتكثيرًا في الخشوع. وسياق القمر أشد: شيء نُكُر، وخروج كجراد منتشر، وإهطاع إلى الداعي، فناسبته الصيغة الأبلغ وتقديمها؛ أما القلم فجاءت ﴿خاشعة﴾ وفق مقدار الشدة في سياقها.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «الفرق بين خُشعًا أبصارهم وخاشعة أبصارهم»، مبحث الآية (43).","url":""}]},{"id":"s69-1","number":1,"surah":69,"verses":[1,2,3],"references":[{"surah":69,"verses":[1,2,3]}],"verseLabel":"الحاقة: 1–3","question":"لماذا أعيد اسم ﴿الْحَاقَّةُ﴾ بدل إضماره في مطلع السورة؟","answer":"لأن إظهار الاسم بعد إمكان الإضمار يستحضر الحاقة بهولها مرة أخرى، ويفخم شأنها ويثبت وقع اسمها في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص558، تحت عنوان «بلاغة الإظهار في مقام الإضمار في قوله: ﴿ما الحاقة﴾»","url":""}]},{"id":"s69-26","number":26,"surah":69,"verses":[1,2,3],"references":[{"surah":69,"verses":[1,2,3]}],"verseLabel":"الحاقة: 1–3","question":"كيف يزيد سؤال ﴿وَمَا أَدْرَاكَ مَا الْحَاقَّةُ﴾ هولَ يوم القيامة؟","answer":"ينقل الاستفهام السامع من مجرد سماع الاسم إلى الشعور بأن حقيقة الحاقة فوق ما يحيط به إدراك البشر إلا بإعلام الله، فيبلغ التهويل غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص562، تحت عنوان «بلاغة الإطناب الاستفهامي في ﴿وما أدراك ما الحاقة﴾»","url":""}]},{"id":"s69-2","number":2,"surah":69,"verses":[4],"references":[{"surah":69,"verses":[4]}],"verseLabel":"الحاقة: 4","question":"لماذا عدل السياق عن ضمير الحاقة إلى اسم ﴿الْقَارِعَةِ﴾؟","answer":"ليستحضر لليوم وصفًا جديدًا يصور قرع أهواله للقلوب والأسماع، بدل الاكتفاء بإحالة ضميرية خافتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص575، تحت عنوان «بلاغة العدول عن الضمير إلى الاسم الظاهر»","url":""}]},{"id":"s69-27","number":27,"surah":69,"verses":[4],"references":[{"surah":69,"verses":[4]}],"verseLabel":"الحاقة: 4","question":"لماذا خُص اسم ﴿الْقَارِعَةِ﴾ عند الحديث عن تكذيب ثمود وعاد؟","answer":"لأن الاسم يلائم ما تلاه من العذاب الذي قرع المكذبين وأصابهم بقوة، فيمهد اللفظ لمشهد هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص575–576، تحت عنوان «دلالة اصطفاء القارعة دون غيرها من أسماء يوم القيامة»","url":""}]},{"id":"s69-3","number":3,"surah":69,"verses":[5],"references":[{"surah":69,"verses":[5]}],"verseLabel":"الحاقة: 5","question":"لماذا عبر عن عذاب ثمود بـ﴿الطَّاغِيَةِ﴾؟","answer":"على تفسير الطاغية بالصيحة، يصفها اللفظ بأنها جاوزت الحد المعتاد في القوة، فيعظم هول ما أهلكهم. وتذكر الموسوعة وجهًا آخر هو أن المراد طغيانهم، فتكون العبارة بيانًا لسبب الهلاك؛ وهما وجهان مختلفان في التفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص580–581، تحت عنوان «سر التعبير بالطاغية مادة وصيغة»","url":""}]},{"id":"s69-4","number":4,"surah":69,"verses":[6],"references":[{"surah":69,"verses":[6]}],"verseLabel":"الحاقة: 6","question":"ماذا يصور وصف الريح بـ﴿صَرْصَرٍ﴾؟","answer":"يستحضر شدة بردها أو حدة صوتها، وكلاهما يرسم ريحًا قاسية نافذة مرعبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص583، تحت عنوان «سر وصف الريح بـ﴿صرصر﴾»","url":""}]},{"id":"s69-28","number":28,"surah":69,"verses":[6],"references":[{"surah":69,"verses":[6]}],"verseLabel":"الحاقة: 6","question":"كيف صوّر وصف الريح بـ﴿عَاتِيَةٍ﴾ شدتها؟","answer":"استعير العتو لتجاوزها الحد في القوة، فكأنها قوة متمردة لا يقف أمامها شيء، مع أنها مسخرة بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص583–584، تحت عنوان «بلاغة الاستعارة في وصف الريح بالعتو: ﴿بريح صرصر عاتية﴾»","url":""}]},{"id":"s69-5","number":5,"surah":69,"verses":[7],"references":[{"surah":69,"verses":[7]}],"verseLabel":"الحاقة: 7","question":"لماذا نصت الآية على مدة تسخير الريح: سبع ليال وثمانية أيام؟","answer":"ليظهر أن العذاب جرى بقدر محكم ودام زمنًا طويلًا كافيًا لاستئصال القوم، فيتضاعف مشهد شدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص586، تحت عنوان «دلالة التنصيص على مدة التسخير»","url":""}]},{"id":"s69-29","number":29,"surah":69,"verses":[7],"references":[{"surah":69,"verses":[7]}],"verseLabel":"الحاقة: 7","question":"ما الصورة التي يضيفها وصف الأيام بـ﴿حُسُومًا﴾؟","answer":"يجمع اللفظ معنى التتابع بلا فتور ومعنى القطع والاستئصال، فيصور أيامًا متوالية حسمت وجود القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص587، تحت عنوان «دلالات اصطفاء لفظ ﴿حسومًا﴾»","url":""}]},{"id":"s69-6","number":6,"surah":69,"verses":[7],"references":[{"surah":69,"verses":[7]}],"verseLabel":"الحاقة: 7","question":"لماذا قيل في الحاقة ﴿أَعْجَازُ نَخْلٍ خَاوِيَةٍ﴾ وفي القمر ﴿مُنْقَعِرٍ﴾؟","answer":"برز في الحاقة سقوط الأجساد وخواؤها بعد تفصيل العذاب، بينما أبرز ﴿منقعر﴾ في القمر اقتلاعها من أصولها؛ فوافق كل وصف سياقه وفاصلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص599–600، تحت عنوان «توجيه المتشابه اللفظي بين آية الحاقة وآية القمر»","url":""}]},{"id":"s69-30","number":30,"surah":69,"verses":[7],"references":[{"surah":69,"verses":[7]}],"verseLabel":"الحاقة: 7","question":"ما الذي يصوره تقييد أعجاز النخل بـ﴿مُنْقَعِرٍ﴾؟","answer":"يصور الأجساد مطروحة كجذوع نخل اقتُلعت من جذورها، فيجمع الضخامة مع تمام السقوط والاستئصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص509، تحت عنوان «دلالة التقييد بصفة ﴿منقعر﴾»","url":""}]},{"id":"s69-7","number":7,"surah":69,"verses":[8],"references":[{"surah":69,"verses":[8]}],"verseLabel":"الحاقة: 8","question":"ماذا يقرر الاستفهام في ﴿فَهَلْ تَرَى لَهُمْ مِنْ بَاقِيَةٍ﴾؟","answer":"هو استفهام إنكاري يقرر أن القوم استؤصلوا حتى لا يرى لهم أثر، ويدعو السامع إلى الاعتبار بمصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص596، تحت عنوان «دلالة الاستفهام في قوله: ﴿فهل ترى لهم من باقية﴾»","url":""}]},{"id":"s69-31","number":31,"surah":69,"verses":[8],"references":[{"surah":69,"verses":[8]}],"verseLabel":"الحاقة: 8","question":"كيف شددت ﴿مِنْ بَاقِيَةٍ﴾ نفي بقاء أحد منهم؟","answer":"زادت ﴿من﴾ النفي استغراقًا، وجاءت ﴿باقية﴾ نكرة ليشمل النفي أي نفس أو بقية مهما دقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص598، تحت عنوان «معنى ﴿من﴾، ودلالة تنكير ﴿باقية﴾»","url":""}]},{"id":"s69-8","number":8,"surah":69,"verses":[9,10],"references":[{"surah":69,"verses":[9,10]}],"verseLabel":"الحاقة: 9–10","question":"ما سر إفراد ﴿رسول ربهم﴾ مع الحديث عن أمم متعددة؟","answer":"يحتمل الإفراد التوزيع، أي عصت كل أمة رسولها. ويحتمل إرادة جنس الرسول، لأن الرسل متفقون في أصل الدعوة إلى الله؛ فيجمع الإفراد عصيان الأمم على اختلاف رسلها في وصف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص614، تحت عنوان «نكتة الإفراد في كلمة ﴿رسول﴾»","url":""}]},{"id":"s69-9","number":9,"surah":69,"verses":[11],"references":[{"surah":69,"verses":[11]}],"verseLabel":"الحاقة: 11","question":"كيف يصور قوله ﴿طَغَى الْمَاءُ﴾ قوة الطوفان؟","answer":"استعار للماء طغيان الجبار المتجاوز لحده، فبدا الطوفان قوة غامرة لا يرد اندفاعها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص622–623، تحت عنوان «بلاغة الاستعارة في قوله: ﴿طغا الماء﴾»","url":""}]},{"id":"s69-10","number":10,"surah":69,"verses":[11],"references":[{"surah":69,"verses":[11]}],"verseLabel":"الحاقة: 11","question":"ما سرّ التعبير في قوله ﴿حَمَلْنَاكُمْ فِي الْجَارِيَةِ﴾ مخاطبًا من لم يولدوا زمن نوح؟","answer":"نجاة الآباء في السفينة سبب لبقاء الذرية ووجود المخاطبين؛ فنسب الحمل إليهم لأن حفظ أصولهم حفظ لهم. وفي الخطاب تذكير مباشر بنعمة يتصل أثرها بحياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص624، تحت عنوان «دلالة خطاب الموجودين في: ﴿حملناكم في الجارية﴾»","url":""}]},{"id":"s69-11","number":11,"surah":69,"verses":[12],"references":[{"surah":69,"verses":[12]}],"verseLabel":"الحاقة: 12","question":"لماذا عُبر بالوعي لا بمجرد السماع في ﴿وَتَعِيَهَا﴾؟","answer":"لأن الوعي يجمع حفظ المسموع وفهمه والانتفاع به، وهو أعمق من سماع قد يمر بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص628، تحت عنوان «نكتة التعبير بالوعي دون السماع في: ﴿وتعيها﴾»","url":""}]},{"id":"s69-32","number":32,"surah":69,"verses":[12],"references":[{"surah":69,"verses":[12]}],"verseLabel":"الحاقة: 12","question":"ما سر إسناد الوعي إلى الأذن في ﴿أُذُنٌ وَاعِيَةٌ﴾؟","answer":"أُسند الوعي إلى الأذن مجازًا لأنها طريق وصول الموعظة إلى القلب، فصارت صورة للإنسان الذي يسمع فيفهم ويحفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص628، تحت عنوان «بلاغة المجاز في قوله: ﴿أذن واعية﴾»","url":""}]},{"id":"s69-33","number":33,"surah":69,"verses":[12],"references":[{"surah":69,"verses":[12]}],"verseLabel":"الحاقة: 12","question":"لماذا قُيدت الأذن بأنها ﴿وَاعِيَةٌ﴾؟","answer":"للتنبيه إلى أن العبرة لا تنفع كل سامع، وإنما تنفع أذنًا متلقية تحفظ وتفهم وتعتبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص628، تحت عنوان «نكتة التقييد بـ﴿أذن واعية﴾»","url":""}]},{"id":"s69-12","number":12,"surah":69,"verses":[13,14],"references":[{"surah":69,"verses":[13,14]}],"verseLabel":"الحاقة: 13–14","question":"ماذا يبرز وصف النفخة بأنها ﴿وَاحِدَةٌ﴾؟","answer":"يبرز نفاذ القدرة وسرعة وقوع الحدث؛ فنفخة واحدة كافية لإحداث أثرها الهائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص635، تحت عنوان «دلالة التقييد بالوحدة في قوله: ﴿نفخة واحدة﴾»","url":""}]},{"id":"s69-34","number":34,"surah":69,"verses":[13,14],"references":[{"surah":69,"verses":[13,14]}],"verseLabel":"الحاقة: 13–14","question":"لماذا وُصفت دكة الأرض والجبال بأنها ﴿وَاحِدَةٌ﴾؟","answer":"لبيان أن ضربة واحدة تحطم هذا الخلق العظيم، تعظيمًا للقدرة وسرعة القضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص639، تحت عنوان «غرض التنصيص على ﴿واحدة﴾»","url":""}]},{"id":"s69-13","number":13,"surah":69,"verses":[16],"references":[{"surah":69,"verses":[16]}],"verseLabel":"الحاقة: 16","question":"ما الذي يضيفه القيد ﴿يَوْمَئِذٍ﴾ إلى وهن السماء؟","answer":"يبين أن ضعف السماء طارئ يوم القيامة بعد إحكام بنائها الآن، فيعظم انقلاب نظام الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص643، تحت عنوان «دلالة القيد الزمني ﴿يومئذ﴾»","url":""}]},{"id":"s69-35","number":35,"surah":69,"verses":[16],"references":[{"surah":69,"verses":[16]}],"verseLabel":"الحاقة: 16","question":"ماذا يصور وصف السماء بـ﴿وَاهِيَةٌ﴾؟","answer":"يصور بناءها وقد انشق وضعف وتداعى، واختيار الصيغة يثبت فيها الوهن في ذلك المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص643، تحت عنوان «سر التعبير بـ﴿واهية﴾ مادة وصيغة»","url":""}]},{"id":"s69-14","number":14,"surah":69,"verses":[18],"references":[{"surah":69,"verses":[18]}],"verseLabel":"الحاقة: 18","question":"ما الصورة التي يستحضرها قوله ﴿يَوْمَئِذٍ تُعْرَضُونَ﴾؟","answer":"يستحضر وقوف الخلق أمام الله للحساب وانكشاف أعمالهم وسرائرهم، كالمعروض الذي لا يستتر.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص648، تحت عنوان «دلالة (العرض) في سياق الآيات»","url":""}]},{"id":"s69-36","number":36,"surah":69,"verses":[18],"references":[{"surah":69,"verses":[18]}],"verseLabel":"الحاقة: 18","question":"كيف عمَّ النفي كل الأسرار في ﴿لَا تَخْفَى مِنْكُمْ خَافِيَةٌ﴾؟","answer":"جاءت ﴿خافية﴾ نكرة في سياق النفي، فشملت كل ما يمكن أن يخفى من عمل أو سر مهما صغر.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص649، تحت عنوان «نكتة تنكير ﴿خافية﴾»","url":""}]},{"id":"s69-15","number":15,"surah":69,"verses":[19],"references":[{"surah":69,"verses":[19]}],"verseLabel":"الحاقة: 19","question":"ماذا تكشف دعوة صاحب اليمين ﴿هَاؤُمُ﴾ عن حاله؟","answer":"هي كناية عن فرحه وثقته بكتابه؛ يمده للناس مسرورًا ويريد أن يشركهم في مشاهدة فوزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص658، تحت عنوان «بلاغة الكناية في ﴿هاؤم﴾»","url":""}]},{"id":"s69-37","number":37,"surah":69,"verses":[19],"references":[{"surah":69,"verses":[19]}],"verseLabel":"الحاقة: 19","question":"لماذا قال صاحب اليمين ﴿اقْرَءُوا كِتَابِيَهْ﴾ لا انظروا إليه؟","answer":"لأنه مطمئن إلى تفاصيل عمله وجزائه، فيدعوهم إلى قراءة محتواه كاملًا لا مجرد رؤية الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص658، تحت عنوان «نكتة التعبير بفعل القراءة في قوله: ﴿اقرءوا﴾»","url":""}]},{"id":"s69-16","number":16,"surah":69,"verses":[20],"references":[{"surah":69,"verses":[20]}],"verseLabel":"الحاقة: 20","question":"ماذا تكني جملة ﴿إِنِّي ظَنَنْتُ أَنِّي مُلَاقٍ حِسَابِيَهْ﴾ عن صاحب اليمين؟","answer":"تكني عن استعداده للحساب بالإيمان والعمل؛ إذ أثمر استحضاره اللقاء سعيًا ظهرت عاقبته في فرحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص660، تحت عنوان «بلاغة الكناية في ﴿إني ظننت﴾»","url":""}]},{"id":"s69-38","number":38,"surah":69,"verses":[20],"references":[{"surah":69,"verses":[20]}],"verseLabel":"الحاقة: 20","question":"كيف دل لفظ ﴿ظَنَنْتُ﴾ هنا على اليقين لا الشك؟","answer":"دل عليه مقام المؤمن الفائز وتوكيد الجملة؛ فالمراد يقينه بلقاء الحساب، لا تردده فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص660، تحت عنوان «دلالة الظن في قوله تعالى: ﴿إني ملاق حسابيه﴾»","url":""}]},{"id":"s69-17","number":17,"surah":69,"verses":[21],"references":[{"surah":69,"verses":[21]}],"verseLabel":"الحاقة: 21","question":"كيف تصور كلمة ﴿رَاضِيَةٍ﴾ كمال عيشة أهل الجنة؟","answer":"تحتمل عيشةً ذات رضا، أو عيشةً رضي بها صاحبها، أو معنى مرضية؛ وتجتمع الأوجه في نعيم يرضي أهله تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص662، تحت عنوان «توجيه معنى ﴿راضية﴾، ودلالتها البلاغية»","url":""}]},{"id":"s69-18","number":18,"surah":69,"verses":[23],"references":[{"surah":69,"verses":[23]}],"verseLabel":"الحاقة: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿قُطُوفُهَا دَانِيَةٌ﴾؟","answer":"دنو الثمار يصور قربها وسهولة تناولها، وهو كناية عن كمال النعيم وملاءمته لرغبة أهل الجنة. فلا يحتاجون إلى مشقة بلوغ الثمرة أو الصعود إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص664، تحت عنوان «بلاغة الكناية في قوله: ﴿قطوفها دانية﴾»","url":""}]},{"id":"s69-19","number":19,"surah":69,"verses":[25,26,27,28,29],"references":[{"surah":69,"verses":[25,26,27,28,29]}],"verseLabel":"الحاقة: 25–29","question":"لماذا تتتابع «كتابيه، حسابيه، ماليه، سلطانيه» بهاء السكت؟","answer":"هاء السكت تحقق تناسب الفواصل عند الوقف، وقد تثبت في الوصل معاملة للفواصل معاملة القوافي. وتذكر الموسوعة أيضًا أن إثباتها ينقل القول المحكي بهيئته التي نطق بها صاحبه، فيحضر مشهد الكلام ووقعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص658–659، تحت عنوان «سر إثبات هاء السكت في ﴿كتابيه﴾ وأخواتها»","url":""}]},{"id":"s69-20","number":20,"surah":69,"verses":[30,31,32],"references":[{"surah":69,"verses":[30,31,32]}],"verseLabel":"الحاقة: 30–32","question":"كيف يصور الأمر ﴿فَغُلُّوهُ﴾ سرعة البطش بالمجرم؟","answer":"تفيد أن الغل يعقب الأخذ بلا إمهال، فتصور سرعة البطش والإذلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص686، تحت عنوان «دلالة الفاء في قوله: ﴿فغلوه﴾»","url":""}]},{"id":"s69-39","number":39,"surah":69,"verses":[30,31,32],"references":[{"surah":69,"verses":[30,31,32]}],"verseLabel":"الحاقة: 30–32","question":"لماذا قيل ﴿ثُمَّ الْجَحِيمَ صَلُّوهُ﴾ بعد الغل؟","answer":"تفيد ﴿ثم﴾ انتقالًا إلى عذاب أشد رتبة، من التقييد والإهانة إلى مباشرة نار الجحيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص686، تحت عنوان «سر التعبير بـ﴿ثم﴾ في قوله: ﴿ثم الجحيم صلوه﴾»","url":""}]},{"id":"s69-40","number":40,"surah":69,"verses":[30,31,32],"references":[{"surah":69,"verses":[30,31,32]}],"verseLabel":"الحاقة: 30–32","question":"ما دلالة ﴿ثُمَّ﴾ قبل إدخال المجرم في السلسلة؟","answer":"تصور تدرج العذاب وتصاعده؛ فبعد الإصلاء بالنار يزاد عليه قيد السلسلة الطويلة، مع احتمال ترتيب المراحل زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص687–688، تحت عنوان «دلالة ﴿ثم﴾ في قوله: ﴿ثم في سلسلة﴾»","url":""}]},{"id":"s69-21","number":21,"surah":69,"verses":[32],"references":[{"surah":69,"verses":[32]}],"verseLabel":"الحاقة: 32","question":"ما دلالة العدد في ﴿ذرعها سبعون ذراعًا﴾؟","answer":"تذكر الموسوعة احتمال أن يكون العدد للتكثير، فيعظم طول السلسلة وهولها، واحتمال أن يكون طولًا محددًا. وعلى الوجهين يصور ذكر امتدادها شدة الإحاطة والعذاب، فلا يجزم من هذا المبحث بأن المراد الحصر العددي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص689، تحت عنوان «دلالة العدد في قوله: ﴿ذرعها سبعون ذراعًا﴾»","url":""}]},{"id":"s69-22","number":22,"surah":69,"verses":[34],"references":[{"surah":69,"verses":[34]}],"verseLabel":"الحاقة: 34","question":"كيف يكشف قوله ﴿وَلَا يَحُضُّ﴾ أن إهمال المسكين خُلُق متجدد لا زلة عابرة؟","answer":"يصور عدم حثه على إطعام المسكين خصلة متجددة مستمرة، لا زلة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص694، تحت عنوان «دلالة التعبير بالفعل المضارع ﴿يحض﴾»","url":""}]},{"id":"s69-23","number":23,"surah":69,"verses":[40,41,42],"references":[{"surah":69,"verses":[40,41,42]}],"verseLabel":"الحاقة: 40–42","question":"كيف يكون القرآن ﴿لَقَوْلُ رَسُولٍ كَرِيمٍ﴾ مع أنه كلام الله؟","answer":"أضيف القول إلى الرسول من جهة تبليغه وأدائه بأمانة، لا من جهة إنشائه؛ فهو واسطة نقل الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص708–709، تحت عنوان «وجه الإضافة وأثرها في: ﴿لقول رسول﴾»","url":""}]},{"id":"s69-41","number":41,"surah":69,"verses":[40,41,42],"references":[{"surah":69,"verses":[40,41,42]}],"verseLabel":"الحاقة: 40–42","question":"لماذا جمع السياق بين نفي الشعر والكهانة عن القرآن؟","answer":"لإبطال أشهر المصدرين اللذين نسب المكذبون إليهما القرآن، وإظهار اختلافه عنهما في الحقيقة والغاية والأسلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص713، تحت عنوان «دلالة الجمع بين نفي الشاعرية ونفي الكهانة»","url":""}]},{"id":"s69-42","number":42,"surah":69,"verses":[40,41,42],"references":[{"surah":69,"verses":[40,41,42]}],"verseLabel":"الحاقة: 40–42","question":"ماذا يحسم التصريح ﴿تَنْزِيلٌ مِنْ رَبِّ الْعَالَمِينَ﴾ بعد نفي الشعر والكهانة؟","answer":"يحسم مصدر القرآن الحقيقي بعد إبطال الافتراءات: فهو منزل من رب العالمين، والرسول مبلغ له.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص716–717، تحت عنوان «موقع جملة: ﴿تنزيل من رب العالمين﴾»","url":""}]},{"id":"s69-24","number":24,"surah":69,"verses":[44,45,46],"references":[{"surah":69,"verses":[44,45,46]}],"verseLabel":"الحاقة: 44–46","question":"كيف يرسم الأخذ باليمين وقطع الوتين هول عقوبة التقول على الله؟","answer":"يصوغ فرض التقول في صورة قبض قاهر يتبعه قطع عرق الحياة، فتبلغ صورة التهديد أقصى الشدة وتقرر استحالة إقرار مفتَرٍ على الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص726، تحت عنوان «بلاغة التعبير في أخذ اليمين وقطع الوتين في قوله: ﴿لأخذنا منه باليمين﴾»","url":""}]},{"id":"s69-43","number":43,"surah":69,"verses":[44,45,46],"references":[{"surah":69,"verses":[44,45,46]}],"verseLabel":"الحاقة: 44–46","question":"لماذا خُص ﴿الْوَتِينَ﴾ بالقطع في تصوير العقوبة؟","answer":"لأنه عرق رئيس متصل بالقلب يتوقف عليه بقاء الجسد؛ فاختياره يصور هلاكًا حاسمًا لا نجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص728، تحت عنوان «بيان معنى ﴿الوتين﴾ وأثر اختياره»","url":""}]},{"id":"s69-25","number":25,"surah":69,"verses":[51,52],"references":[{"surah":69,"verses":[51,52]}],"verseLabel":"الحاقة: 51–52","question":"ما الذي يبلغه وصف القرآن بأنه ﴿لَحَقُّ الْيَقِينِ﴾؟","answer":"يقرر أن القرآن هو الحق الثابت الذي بلغ أعلى مراتب اليقين، فلا يتطرق إليه شك.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص738، تحت عنوان «بلاغة التعبير بـ﴿لحق اليقين﴾»","url":""}]},{"id":"s69-44","number":44,"surah":69,"verses":[51,52],"references":[{"surah":69,"verses":[51,52]}],"verseLabel":"الحاقة: 51–52","question":"كيف يقود اليقين بصدق القرآن إلى الأمر ﴿فَسَبِّحْ بِاسْمِ رَبِّكَ﴾؟","answer":"لأن ثبوت صدق الوحي وبطلان افتراءات المكذبين يستلزمان تنزيه الله وتعظيمه، فجاء التسبيح نتيجة لما سبق.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص740، تحت عنوان «معنى الفاء في قوله: ﴿فسبح باسم ربك﴾»","url":""}]},{"id":"s69-45","number":45,"surah":69,"verses":[51,52],"references":[{"surah":69,"verses":[51,52]}],"verseLabel":"الحاقة: 51–52","question":"لماذا ناسب وصف الرب بـ﴿الْعَظِيمِ﴾ ختام السورة؟","answer":"لأن المقام أمر بتنزيه الله بعد عرض قدرته وصدق وحيه؛ فناسبه الاسم الدال على كمال العظمة المستوجبة للتسبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج63، ص741، تحت عنوان «دلالة وصف ﴿العظيم﴾ في هذا المقام»","url":""}]},{"id":"s69-46","number":46,"surah":69,"verses":[4],"references":[{"surah":69,"verses":[4]}],"verseLabel":"الحاقة: 4","question":"ما دلالة تقديم ثمود على عاد هنا، مع أن عادًا أسبق زمنًا؟","answer":"السمت العام في السورة الانتقال من الأقرب إلى الأبعد: ثمود ثم عاد، وفرعون ثم من قبله، ثم قوم نوح. ويمتد النسق إلى مشاهد القيامة، فتذكر الأرض والجبال قبل السماء، وإلى القسم بما نبصر قبل ما لا نبصر؛ فكان التقديم جزءًا من نظام السورة لا مجرد ترتيب تاريخي.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «دلالة تقديم ثمود على عاد»، مبحث الآية (4).","url":""}]},{"id":"s69-47","number":47,"surah":69,"verses":[13],"references":[{"surah":69,"verses":[13]}],"verseLabel":"الحاقة: 13","question":"ما سر تذكير الفعل في ﴿نُفِخَ فِي الصُّورِ نَفْخَةٌ﴾ مع أن «نفخة» مؤنثة؟","answer":"«نفخة» مؤنث مجازي يجوز معه التذكير، وقد فصل الجار والمجرور بين الفعل ونائب الفاعل فحسّن التذكير. وجاءت قراءة بالنصب تجعل «نفخةً» مفعولًا مطلقًا لا فاعلًا أصلًا. وفوق ذلك، فإن المقام مقام شدة وهول، والتذكير يُختار في نظائر القرآن للمقام الأشد.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «لماذا جاء الفعل نفخ مذكرًا؟»، مبحث الآية (13).","url":""}]}]);
